window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0006", [{"word":"avoid","ipa_uk":"/əˈvɔɪd/","ipa_us":"/əˈvɔɪd/","definition_zh":"避免；避开；回避；防止","definition_en":"to keep away from something, prevent it from happening, or refuse to deal with it","core_image":"在身前留出一块空地：不碰、不进、不接","scene":"The cyclist swerved sharply to avoid a pothole in the rain.","sceneCN":"这里 avoid 是「避开某个具体物体、不撞上去」（第 1 个义项：避开物理对象）；句意：雨中骑车人猛地一拐，避开了一个坑洞。场景要点：湿滑路面、坑洞、转向的车把。","pos":[{"tag":"vt.","zh":"避免；避开；回避；防止"}],"collocations":[{"phrase":"avoid the risk","zh":"规避风险"},{"phrase":"avoid doing something","zh":"避免做某事（后接动名词）"},{"phrase":"avoid direct contact","zh":"避免直接接触"},{"phrase":"avoid the subject","zh":"回避这个话题"},{"phrase":"avoid detection","zh":"逃避侦测；不被人发现"}],"forms":[{"label":"三单（he/she/it）","form":"avoids"},{"label":"过去式（已经发生）","form":"avoided"},{"label":"过去分词（完成／被动）","form":"avoided"},{"label":"现在分词（进行体）","form":"avoiding"}],"derivatives":[{"word":"avoidance","pos":"n.","zh":"避免；回避；（心理学）回避行为"},{"word":"avoidable","pos":"adj.","zh":"可以避免的"},{"word":"unavoidable","pos":"adj.","zh":"不可避免的；无法回避的"},{"word":"avoidant","pos":"adj.","zh":"回避型的；倾向逃避的"}],"senses":[{"no":"01","title":"Keep clear of a physical thing","titleCN":"绕开实物：不碰上","definition":"to move or stay so that you do not touch or hit a physical object","definitionCN":"调整位置或保持距离，使自己不碰到、不撞上某个实物","example":"She stepped aside to avoid the falling ladder.","exampleCN":"她闪到一边，避开了倒下的梯子。","why":"The oldest English sense was to empty a place out. Once a space is emptied, you stand outside it; the physical sense is that empty gap kept between your body and the object.","whyCN":"英语最早的意思是“把某处腾空”。地方一腾空，人就站在它外面；物理义就是身体与物体之间留出的那段空当。"},{"no":"02","title":"Stay away from a person","titleCN":"避开某人：不照面","definition":"to keep away from someone you do not want to meet or deal with","definitionCN":"远离不想见到或不想打交道的人","example":"He changed his route to avoid his former colleague.","exampleCN":"他改了路线，避开原来的同事。","why":"The same empty gap is now social instead of physical: you keep a distance wide enough that contact never happens.","whyCN":"同一段空当从物理距离变成了社交距离：你把距离拉大到接触不会发生。"},{"no":"03","title":"Prevent an event from happening","titleCN":"防止发生：让事情无处落脚","definition":"to make sure that something does not happen","definitionCN":"确保某事不会发生","example":"Check the brakes regularly to avoid accidents.","exampleCN":"定期检查刹车以避免事故。","why":"If the space where an event would occur is kept empty, the event has nowhere to take place; avoidance turns into prevention.","whyCN":"如果事件本来要发生的那个位置被保持为空，事件就无处落脚；于是“避开”引申为“防止”。"},{"no":"04","title":"Refuse to perform an action","titleCN":"克制不做：把动作空着","definition":"to deliberately not do something","definitionCN":"有意不做某事","example":"Try to avoid using jargon in the introduction.","exampleCN":"引言里尽量避免使用术语。","why":"An action is treated like an object you decline to pick up; the slot where the action would sit is left unfilled.","whyCN":"一个动作被当成你不去拿的物件；动作本该占据的那个格子被留空。"},{"no":"05","title":"Evade a duty or obligation","titleCN":"逃避责任：该填的位置不填","definition":"to try not to deal with a responsibility that others expect you to accept","definitionCN":"设法不去承担别人期待你承担的责任","example":"The company was accused of avoiding its tax obligations.","exampleCN":"这家公司被指逃避纳税义务。","why":"A duty is a place reserved for you. To avoid it is to leave that reserved place empty and let someone else or no one fill it.","whyCN":"责任是为你预留的位置。avoid 它，就是让那个预留的位置空着，由别人或无人去填。"},{"no":"06","title":"Keep a substance out of the body","titleCN":"忌口：把某物挡在体外","definition":"to not eat, drink, or use something, usually for health reasons","definitionCN":"不吃、不喝或不用某物，通常出于健康原因","example":"Patients with this condition should avoid sugar.","exampleCN":"这类病人应避免摄入糖。","why":"The body is the enclosed space; the substance is kept outside its boundary. This is the emptied space applied to diet and health.","whyCN":"身体是被围起来的空间，某物被挡在边界之外。这就是“腾空”之意用在饮食与健康上。"},{"no":"07","title":"Steer clear of a topic","titleCN":"绕开话题：话不往那儿走","definition":"to not discuss or mention a subject","definitionCN":"不讨论、不提及某个话题","example":"They avoided the question of who would pay.","exampleCN":"他们回避了谁付钱这个问题。","why":"A topic is a space in a conversation. Avoiding it means the talk never enters that space, so the gap stays empty.","whyCN":"话题是对话中的一个空间。avoid 它，就是谈话从不进入那个空间，空当一直空着。"},{"no":"08","title":"Escape detection or capture","titleCN":"躲过侦测：不被发现","definition":"to manage not to be seen, caught, or noticed","definitionCN":"设法不被看见、抓住或注意到","example":"The animal avoids predators by staying still among the reeds.","exampleCN":"这种动物躲在芦苇里不动，以避开捕食者。","why":"Here the gap is between the observer and the target. Keeping that gap intact means the predator's attention never lands on you.","whyCN":"这里的空当在观察者与目标之间。空当保持完整，捕食者的注意就始终落不到你身上。"},{"no":"09","title":"Legal: make a contract void","titleCN":"法律：使契约失效","definition":"in law, to cancel or annul an agreement so that it has no legal effect","definitionCN":"在法律上取消或废止一项协议，使其不产生法律效力","example":"The buyer may avoid the contract if the goods were misrepresented.","exampleCN":"如果货物被虚假描述，买方可主张合同无效。","why":"This is the original sense surviving intact: to avoid is to empty something of force, to make it void. The modern everyday sense grew out of this legal emptying.","whyCN":"这是原义完整保留下来的一支：avoid 就是把某物“掏空”，使其失效（void）。日常的“避开”义正是从这种法律上的“使之无效”长出来的。"}],"etymology":{"intro":{"en":"Avoid entered English from Old French with a concrete image: emptying a place. Its modern meaning of keeping away grew from that emptied space.","cn":"avoid 从古法语进入英语时带着一个具体意象：把某处腾空。现代“避开”的意思，正是从这片被腾出的空间长出来的。"},"items":[{"era":"MIDDLE ENGLISH","en":"Borrowed in the 14th century from Old French esvuidier 'to empty out, clear out'. The earliest English records use it for clearing a place or getting out of it.","cn":"14 世纪从古法语 esvuidier“腾空、清空”借入。英语最早的记录用它表示清空某地或从某地退出。"},{"era":"OLD FRENCH esvuidier","en":"The verb was es- 'out' + vuidier 'to be empty'. The picture is a container or a room being made empty.","cn":"这个动词由 es-“向外”+ vuidier“是空的”构成。画面是一个容器或一个房间被清空。"},{"era":"OLD FRENCH voide","en":"Voide meant 'empty, vacant, wide'. English also borrowed it directly as void, which still carries the 'empty, without force' meaning.","cn":"voide 意为“空的、空的、空旷的”。英语也直接把它借成了 void，至今仍保留“空的、无效的”含义。"},{"era":"LATIN (PROBABLE)","en":"Voide is generally thought to come from Latin vocivus 'unoccupied, vacant', probably related to vacivus 'empty' and vacare 'to be empty'. The link is accepted by most sources rather than directly proven.","cn":"voide 一般被认为来自拉丁语 vocivus“无人占用的、空的”，可能与 vacivus“空的”和 vacare“空着”有关。这一联系多为词源学界接受，而非直接证实的文献链。"},{"era":"SEMANTIC SHIFT","en":"From 'empty a place' came 'leave a place', then 'stay out of a place', and finally 'keep away from anything'. Each step preserves the same empty gap.","cn":"从“腾空某地”到“离开某地”，再到“不进入某地”，最后到“远离任何东西”。每一步都保留了同一片空当。"},{"era":"MODERN ENGLISH","en":"The legal phrase avoid a contract still means 'make it void'. Everyday English applies the same gesture to traffic, people, health, taxes, questions, and detection.","cn":"法律短语 avoid a contract 至今仍表示“使合同失效”。日常英语把同一个动作用于交通、人际、健康、税务、话题和躲藏。"}]},"similar":{"note":{"en":"The first group is built on the same 'empty' root; the second collects words that also mean staying away, each from a different angle.","cn":"第一组共享同一个“空”词根，第二组收同样表示“远离”的词，但各自角度不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"void","ipa":"/vɔɪd/","tag":"same root","definition":"empty, without legal force, or a blank space. It is the direct English borrowing of Old French voide, the source of avoid.","definitionCN":"空的；无法律效力的；空白。它是古法语 voide 的直接借形，也是 avoid 的来源词。"},{"word":"devoid","ipa":"/dɪˈvɔɪd/","tag":"same root, different prefix","definition":"completely lacking something. De- 'away' + void 'empty' gives 'emptied of' a quality.","definitionCN":"完全缺乏某物。de-“去除”+ void“空”，表示某种性质被“掏空”。"},{"word":"avoidance","ipa":"/əˈvɔɪdəns/","tag":"derived noun","definition":"the act of staying away from something, or a defence mechanism in psychology. It is the noun of avoid, not a separate root.","definitionCN":"避开的行为；心理学中的回避机制。它是 avoid 的名词派生，不是另一个词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"evade","ipa":"/ɪˈveɪd/","tag":"escape a claim","definition":"to escape or avoid something, especially a duty, question, or capture, often by cleverness. Evade stresses escaping something that is chasing or claiming you.","definitionCN":"逃避某物，尤其是责任、问题或抓捕，常靠机巧。evade 强调摆脱正在追索你的东西。"},{"word":"prevent","ipa":"/prɪˈvent/","tag":"stop before it starts","definition":"to stop something from happening. Prevent focuses on the event being blocked; avoid can mean either staying away or blocking.","definitionCN":"阻止某事发生。prevent 聚焦事件被挡住；avoid 既可指自己远离，也可指阻止。"},{"word":"dodge","ipa":"/dɒdʒ/","tag":"quick physical move","definition":"to move quickly aside to escape something, or to avoid a question in a shifty way. It is more physical and more informal than avoid.","definitionCN":"快速闪身躲开，或以滑头的方式回避问题。它比 avoid 更具体、更口语。"},{"word":"shun","ipa":"/ʃʌn/","tag":"deliberate social rejection","definition":"to deliberately ignore or refuse to associate with someone. Shun is social and intentional; avoid can be merely practical.","definitionCN":"有意无视或拒绝与某人来往。shun 是社交性、刻意性的；avoid 可以只是实际需要。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: es- 'out', voide 'empty', the doublet void, and the legal sense that still means 'make void'.","cn":"只用真实成分与真实同族词：es-“向外”、voide“空”、同源双形 void，以及至今仍表示“使失效”的法律义。"},"normal":[{"en":"Avoid is built from 'out' + 'empty': to avoid is to keep a space empty between you and trouble.","cn":"avoid 由“向外”+“空”构成：avoid 就是在你与麻烦之间留出一块空地。"},{"en":"Void is the same word without the prefix: avoid something and you leave it void of your presence.","cn":"void 是同根词去掉前缀：avoid 某物，就是让它“空”得没有你的存在。"},{"en":"The legal phrase avoid a contract preserves the original image: the contract is emptied of legal force.","cn":"法律短语 avoid a contract 保留了原始意象：合同被掏空法律效力。"},{"en":"Avoid takes a gerund: avoid seeing him, not avoid to see him. The thing kept away is an activity, not a target.","cn":"avoid 后接动名词：avoid seeing him，而不是 avoid to see him。被避开的是一个活动，而不是一个目标。"},{"en":"Avoidance in psychology is the same geometry: the feared situation is kept outside the space a person will enter.","cn":"心理学里的 avoidance 是同一套几何：被恐惧的情境被挡在一个人愿意进入的空间之外。"}],"abstract":[{"en":"Think of a circle drawn around you. Avoid is the act of keeping certain things outside that circle.","cn":"想象在你周围画一个圈。avoid 就是把某些东西一直挡在圈外的动作。"},{"en":"The word describes absence rather than action: what matters is the space that remains empty, not what you do inside it.","cn":"这个词描述的是“缺席”而不是“行动”：重要的是仍然空着的那块地方，而不是你在里面做了什么。"},{"en":"Prevention is avoidance moved forward in time: the empty space is created before the event can enter it.","cn":"预防是把 avoid 往时间前方挪：在事件来得及进入之前，先把那块空间腾出来。"}]},"examples":[{"en":"The driver braked hard to avoid a dog running across the road.","cn":"司机猛踩刹车，避开一只横穿马路的狗。"},{"en":"She avoided mentioning the broken window because she had caused it.","cn":"她避而不提那扇破窗，因为是她弄坏的。"},{"en":"Regular maintenance helps avoid costly repairs later.","cn":"定期保养有助于避免日后昂贵的维修。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“阿沃伊德”——阿沃伊德走路总绕开坑洞和水洼 → avoid 避开、回避","word":"avoid"},"root":"源自古法语 esvuidier“腾空、清出”，由 es-“向外”+ voide“空的”构成；核心是“把某处腾空，从而不进入、不接触”。","sensesIntro":{"en":"Nine senses of avoid, all grown from one gesture: an empty space is kept between the self and something unwanted.","cn":"avoid 的九个义项都从同一个动作长出来：在自我与不想碰到的东西之间，留出一块空当。"},"semanticMap":{"core":{"en":"CORE IMAGE: an empty gap held open between you and what you do not want to meet.","cn":"核心意象：在你与不想遭遇之物之间，保持一段空当。"},"chain":["EMPTY SPACE","STAY OUTSIDE","KEEP DISTANCE","DO NOT TAKE UP","DO NOT LET IT HAPPEN","MAKE VOID OR EVADE"],"branches":[{"senses":"S1 · S2","en":"PHYSICAL AND SOCIAL DISTANCE: a pothole, a falling object, or a person you do not wish to meet.","cn":"物理与社交距离：坑洞、倒下的物体，或不想见到的人。"},{"senses":"S3","en":"PREVENTION: keeping the event's place empty so that it cannot occur.","cn":"预防：让事件本该发生的位置保持空着，使它无法发生。"},{"senses":"S4 · S6","en":"SELF-RESTRAINT: an action not performed, a substance kept out of the body.","cn":"自我克制：不做的动作，以及被挡在体外的物质。"},{"senses":"S5 · S7 · S8","en":"EVASION: an obligation, a question, or an observer is left with an empty place where you should have been.","cn":"逃避：责任、问题或观察者面对的，是本该有你却空着的位置。"},{"senses":"S9","en":"LEGAL VOID: a contract is emptied of legal force, preserving the oldest sense.","cn":"法律失效：合同被掏空法律效力，保留了最古老的含义。"}]},"affixes":{"intro":{"en":"English does not use a live prefix to form avoid. The es- 'out' is frozen inside the Old French verb, and English adds ordinary suffixes such as -able, -ance, and -ed.","cn":"英语并不是用活前缀来造 avoid 的。es-“向外”凝固在古法语动词里；英语只在后面加 -able、-ance、-ed 这类普通后缀。"},"latinIntro":{"en":"The deeper Latin family is built on vacare 'to be empty' and vocivus 'vacant'. The link to voide is generally accepted but not directly attested, so the Latin entries below are given as probable relatives.","cn":"更深一层的拉丁词族建立在 vacare“空着”和 vocivus“空的”上。它与 voide 的联系被普遍接受，但缺乏直接文献证据，因此下面的拉丁条目按“可能同源”处理。"},"items":[{"word":"avoidable","structure":"avoid + -able (able to be)","meaning":"able to be prevented or kept away from","meaningCN":"可以避免的（-able 表示“能被……的”）","example":"Most of these accidents are avoidable.","exampleCN":"这些事故大多是可以避免的。"},{"word":"unavoidable","structure":"un- (not) + avoidable","meaning":"impossible to prevent","meaningCN":"不可避免的（un- 表示否定）","example":"Delay was unavoidable because of the storm.","exampleCN":"因为暴风雨，延误不可避免。"},{"word":"unavoidably","structure":"un- + avoidable + -ly (adverb)","meaning":"in a way that cannot be prevented","meaningCN":"不可避免地（-ly 构成副词）","example":"The meeting was unavoidably postponed.","exampleCN":"会议不可避免地推迟了。"},{"word":"avoidance","structure":"avoid + -ance (act or state)","meaning":"the act of keeping away, or a psychological defence pattern","meaningCN":"回避；回避行为（-ance 表示行为或状态）","example":"His avoidance of the topic made the meeting awkward.","exampleCN":"他对这个话题的回避让会议很尴尬。"},{"word":"avoidant","structure":"avoid + -ant (adjective)","meaning":"tending to avoid closeness, risk, or conflict","meaningCN":"回避型的；倾向逃避的（-ant 构成形容词）","example":"An avoidant attachment style can make intimacy difficult.","exampleCN":"回避型依恋会让亲密关系变得困难。"},{"word":"avoided","structure":"avoid + -ed (past participle)","meaning":"kept away from; prevented","meaningCN":"被避开的；被防止的（-ed 构成过去分词）","example":"The worst outcome was narrowly avoided.","exampleCN":"最坏的结果被勉强避免了。"},{"word":"avoiding","structure":"avoid + -ing (present participle)","meaning":"the ongoing act of keeping away","meaningCN":"正在避开；回避（-ing 构成现在分词）","example":"He kept avoiding eye contact during the interview.","exampleCN":"面试时他一直避开眼神接触。"},{"word":"avoider","structure":"avoid + -er (person who)","meaning":"a person who habitually avoids something","meaningCN":"惯于回避的人（-er 表示执行者，较少用）","example":"As a rule, he is an avoider of conflict.","exampleCN":"他一向是个回避冲突的人。"}],"latinEntries":[{"word":"vacare","structure":"Latin verb","meaning":"to be empty, free, vacant (probable deeper relative)","meaningCN":"空着；空闲；无人占用（一般认为与本词有较深联系）"},{"word":"vocivus","structure":"Latin adjective","meaning":"unoccupied, vacant (probable source of Old French voide)","meaningCN":"无人占用的；空的（一般认为是古法语 voide 的来源）"}]}},{"word":"balance","ipa_uk":"/ˈbæləns/","ipa_us":"/ˈbæləns/","definition_zh":"平衡；余额；天平；权衡","definition_en":"a state of equal weight or steadiness, the money left in an account, or to weigh and steady opposing forces","core_image":"两只秤盘等高的横梁","scene":"The shopkeeper added weights to one pan until the balance stood level.","sceneCN":"这里 balance 是「天平」这一器具（第 1 个义项）；句意：店主往一只秤盘里加砝码，直到天平持平。场景要点：木质横梁、两只秤盘、砝码、持平的指针。","pos":[{"tag":"n.","zh":"平衡；余额；天平；均衡"},{"tag":"vt.","zh":"使平衡；权衡；结算"},{"tag":"vi.","zh":"保持平衡；收支相抵"}],"collocations":[{"phrase":"keep one's balance","zh":"保持平衡；站稳"},{"phrase":"balance the budget","zh":"平衡预算"},{"phrase":"a bank balance","zh":"银行账户余额"},{"phrase":"balance A against B","zh":"权衡 A 与 B"},{"phrase":"strike a balance","zh":"取得折中；找到平衡"}],"forms":[{"label":"复数（名词）","form":"balances"},{"label":"三单（he/she/it）","form":"balances"},{"label":"过去式（已经发生）","form":"balanced"},{"label":"过去分词（完成／被动）","form":"balanced"},{"label":"现在分词（进行体）","form":"balancing"}],"derivatives":[{"word":"balanced","pos":"adj.","zh":"均衡的；考虑周全的"},{"word":"unbalanced","pos":"adj.","zh":"失衡的；心理失衡的"},{"word":"imbalance","pos":"n.","zh":"不平衡；失衡"},{"word":"balancer","pos":"n.","zh":"平衡器；保持平衡的人或物"}],"senses":[{"no":"01","title":"The weighing instrument","titleCN":"天平：称重的器具","definition":"a device with two pans that shows equal weight by standing level","definitionCN":"有两个秤盘、通过横梁持平来显示重量相等的器具","example":"The chemist weighed the powder on a precision balance.","exampleCN":"化学家用精密天平称量粉末。","why":"The word came from Latin bilanx, literally 'two pans'. The object itself is the starting point: two pans hung from one beam.","whyCN":"这个词来自拉丁语 bilanx，字面就是“两只秤盘”。词义的起点就是这件器物：一根横梁下挂两只盘子。"},{"no":"02","title":"Physical steadiness","titleCN":"身体平衡：站得稳","definition":"the ability to keep your body steady without falling","definitionCN":"保持身体稳定、不摔倒的能力","example":"She lost her balance on the icy steps.","exampleCN":"她在结冰的台阶上失去了平衡。","why":"When the two pans are level, neither side pulls the beam down. A body that does not tip is in the same relation: no side wins.","whyCN":"两只秤盘齐平时，没有一边把横梁压下去。不倾倒的身体处在同一种关系里：没有哪一边占上风。"},{"no":"03","title":"Money left in an account","titleCN":"账户余额：收支相抵后剩下的数","definition":"the amount of money remaining after credits and debits are compared","definitionCN":"把收入与支出相抵之后剩下的金额","example":"The balance in my account is lower than I expected.","exampleCN":"我账户里的余额比预想的低。","why":"Bookkeeping treats money in and money out as two pans. What remains when they are level is the balance, the amount that keeps the account from tipping.","whyCN":"记账把进账与出账当成两只秤盘。两盘齐平后剩下的，就是 balance——让账目不至于倾倒的那个数。"},{"no":"04","title":"Equilibrium between forces","titleCN":"力量均衡：各方不相上下","definition":"a state in which opposing forces, interests, or powers have equal influence","definitionCN":"相互对抗的力量、利益或权力影响相当的状态","example":"The treaty created a balance of power in the region.","exampleCN":"该条约在该地区形成了力量均衡。","why":"The scales image is applied to politics and physics: each side weighs as much as the other, so the beam stays level.","whyCN":"天平的意象被用到政治与物理上：每一方与另一方分量相当，横梁因此保持水平。"},{"no":"05","title":"Mental or emotional stability","titleCN":"心理稳定：情绪不倾覆","definition":"a calm, stable state of mind in which emotions do not overwhelm reason","definitionCN":"情绪不会压倒理性的平静稳定状态","example":"Years of meditation gave her a sense of balance.","exampleCN":"多年的冥想让她有了一种平衡感。","why":"The same level beam is imagined inside a person: feelings and reason carry equal weight, so neither side drags the mind down.","whyCN":"同一根水平的横梁被想象到人的内部：情感与理性分量相当，没有哪一边把心智拽倒。"},{"no":"06","title":"To keep something steady","titleCN":"使保持平衡：不让它倒","definition":"to keep an object or body in a stable position","definitionCN":"让物体或身体保持在稳定位置","example":"He balanced the tray on one hand while opening the door.","exampleCN":"他一只手托稳托盘，另一只手开门。","why":"The verb turns the instrument into an action: you arrange the weight so that the beam, or the tray, does not tip.","whyCN":"动词把器具变成动作：你调整重量分配，使横梁——或托盘——不倾斜。"},{"no":"07","title":"To weigh and compare options","titleCN":"权衡：把两方面放上秤","definition":"to compare the value or importance of two or more things before deciding","definitionCN":"在决定前比较两个或更多事物的价值或重要性","example":"The committee balanced cost against safety.","exampleCN":"委员会在成本与安全之间做权衡。","why":"To weigh options is to put one on each pan. No decision is made until you see which side is heavier.","whyCN":"权衡选项就是把它们分别放上两只秤盘。在看清哪边更重之前，不做决定。"},{"no":"08","title":"To offset or compensate","titleCN":"抵消：用另一边补回来","definition":"to equal or cancel the effect of something with an opposing force or amount","definitionCN":"用相反的力量或数量与某物相等或抵消其影响","example":"Higher prices were balanced by lower shipping costs.","exampleCN":"较高的价格被较低的运费抵消了。","why":"If one pan is heavier, you add weight to the other until the beam returns to level. Compensation is that added weight.","whyCN":"若一只盘子更重，就往另一边加重量，直到横梁恢复水平。补偿就是加上去的那份重量。"},{"no":"09","title":"To make accounts equal","titleCN":"结平账目：让账面齐平","definition":"to make the debit and credit totals of an account equal","definitionCN":"使一个账户的借贷总额相等","example":"The accountant balanced the books before the audit.","exampleCN":"会计在审计前把账目结平了。","why":"This is the scales turned into arithmetic: two columns must end at the same total before the account is called balanced.","whyCN":"这是天平变成了算术：两栏必须在同一总数上收尾，账目才叫“结平”。"}],"etymology":{"intro":{"en":"Balance came into English from Old French as the name of a physical instrument. Its many abstract senses all keep the picture of two pans hanging from one beam.","cn":"balance 从古法语进入英语时，是一件实体器具的名称。它后来众多的抽象义项，都保留着“一根横梁挂两只秤盘”的画面。"},"items":[{"era":"EARLY 13C.","en":"Old French balance 'scales, balance' was borrowed into English in the 13th century, first as the instrument and soon after as 'equilibrium'.","cn":"古法语 balance“天平、秤”在 13 世纪借入英语，先指器具，很快又指“均衡状态”。"},{"era":"OLD FRENCH balance","en":"The French noun came from Vulgar Latin bilancia, a plural-looking form built on Latin bilanx 'having two pans'.","cn":"这个法语名词来自通俗拉丁语 bilancia，其形式看似复数，实际建立在拉丁语 bilanx“有两只秤盘的”上。"},{"era":"LATIN bilanx","en":"Bilanx was bi- 'two' + lanx 'dish, pan, scale'. The compound names the instrument by its most visible feature: two pans.","cn":"bilanx 是 bi-“二”+ lanx“盘子、秤盘”。这个复合词用器具最显眼的特征来命名它：两只盘子。"},{"era":"LATIN lanx","en":"Lanx meant a dish or the pan of a scale, and could also mean a plate of money. The weighing pan and the plate of value are the same object.","cn":"lanx 指盘子或天平秤盘，也可指一盘钱币。称重的盘与盛放价值的盘，是同一个物件。"},{"era":"SEMANTIC EXPANSION","en":"From the instrument came 'equal weight', then 'money remaining when accounts are level', then 'stable mind' and 'equal political forces'.","cn":"从器具义生出“重量相等”，再生成“账目齐平后剩下的钱”，又生成“稳定的心智”和“势均力敌的政治力量”。"},{"era":"MODERN ENGLISH","en":"Modern English uses balance in banking, design, chemistry, politics and everyday posture. The beam image is still visible in all of them.","cn":"现代英语在银行、设计、化学、政治和日常姿态中使用 balance。横梁的意象在所有这些用法里仍然看得见。"}]},"similar":{"note":{"en":"The first group shares the Latin image of two pans; the second collects words about equality and remaining amounts.","cn":"第一组共享拉丁语“两只秤盘”的意象，第二组收表示“相等”和“剩余量”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"imbalance","ipa":"/ɪmˈbæləns/","tag":"same base, negative prefix","definition":"a state in which two sides are not equal. Im- 'not' + balance gives the opposite of equilibrium.","definitionCN":"两边不相等的状态。im-“不”+ balance，构成均衡的反面。"},{"word":"counterbalance","ipa":"/ˈkaʊntəbæləns/","tag":"same base, added weight","definition":"a weight or force that balances another. Counter- 'against' + balance makes the compensating side explicit.","definitionCN":"平衡另一方的重量或力量。counter-“对抗”+ balance，把补偿的那一边写明。"},{"word":"balanced","ipa":"/ˈbælənst/","tag":"derived adjective","definition":"steady, equal, or fair. It is the past participle of balance used as an adjective.","definitionCN":"平稳的、均衡的、公正的。它是 balance 的过去分词转作形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"equilibrium","ipa":"/ˌiːkwɪˈlɪbriəm/","tag":"scientific balance","definition":"a state of rest produced by equal opposing forces. It is the technical Latin word for the same idea, used in physics and chemistry.","definitionCN":"相等对抗力量造成的静止状态。它是表达同一概念的技术性拉丁词，用于物理和化学。"},{"word":"poise","ipa":"/pɔɪz/","tag":"graceful steadiness","definition":"calm dignity and steady control of the body. Poise is personal and graceful; balance is broader and more mechanical.","definitionCN":"沉着体面与身体的稳定控制。poise 更个人化、更优雅；balance 更宽泛、更机械化。"},{"word":"remainder","ipa":"/rɪˈmeɪndə/","tag":"what is left","definition":"the part that is left after the rest is taken away. It overlaps with balance only in the money sense.","definitionCN":"其余部分被拿走之后剩下的部分。它只在“钱款余额”这一义项上与 balance 重叠。"},{"word":"offset","ipa":"/ˌɒfˈset/","tag":"compensating effect","definition":"something that cancels or reduces the effect of something else. Offset stresses cancelling an effect, while balance stresses equal weight.","definitionCN":"抵消或减轻另一事物影响的东西。offset 强调抵消效果，balance 强调重量相等。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: bi- 'two', lanx 'pan', and the banking phrase balance the books.","cn":"只用真实成分与真实同族词：bi-“二”、lanx“秤盘”，以及记账短语 balance the books。"},"normal":[{"en":"Bi- means 'two' and lanx means 'pan': a balance is literally a two-pan thing.","cn":"bi- 是“二”，lanx 是“盘”：balance 字面就是“两只盘子的东西”。"},{"en":"When the two pans are level, no side pulls the beam down. That levelness is the whole family of meanings.","cn":"两只盘子齐平时，没有一边把横梁压下。这种齐平就是这一整族含义的来源。"},{"en":"To balance the books is to make the debit and credit columns end at the same number.","cn":"balance the books 就是让借方与贷方两栏收在同一个数字上。"},{"en":"Imbalance is the beam tipping: one side carries more weight than the other.","cn":"imbalance 就是横梁倾斜：一边比另一边更重。"},{"en":"A balanced person is not a person with no feelings; it is a person whose feelings and reason carry equal weight.","cn":"a balanced person 不是没有情绪的人，而是情绪与理性分量相当的人。"}],"abstract":[{"en":"Picture one horizontal line with two equal weights hanging from its ends. Every sense of balance is a claim that this line has stayed level.","cn":"想象一条水平线，两端挂着相等的重量。balance 的每个义项，都是在说这条线保持住了水平。"},{"en":"The word is about relation, not about a single object: nothing is balanced by itself, only against something else.","cn":"这个词讲的是关系，不是单个物体：没有任何东西单独“平衡”，只能相对于别的东西平衡。"},{"en":"When one side changes, the other must change too. Balance is therefore a process, not a fixed point.","cn":"一边变了，另一边也必须变。因此 balance 是一个过程，而不是一个固定点。"}]},"examples":[{"en":"It is hard to balance study and work without losing sleep.","cn":"不牺牲睡眠就很难平衡学习与工作。"},{"en":"The company reported a healthy balance at the end of the year.","cn":"公司在年末报告了健康的账户余额。"},{"en":"The two countries agreed to restore the balance of trade.","cn":"两国同意恢复贸易平衡。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“巴兰斯”——巴兰斯把两筐货放上秤，两边一样重才点头 → balance 平衡、余额","word":"balance"},"root":"源自拉丁语 bilanx“有两只秤盘的”，由 bi-“二”+ lanx“盘、秤盘”构成，核心是“两盘齐平、不偏不倚”。","sensesIntro":{"en":"Nine senses of balance, all built on one instrument: two pans on a single beam, and the level position in which neither pan wins.","cn":"balance 的九个义项都建立在一件器具上：一根横梁上的两只秤盘，以及没有哪只盘占上风的齐平状态。"},"semanticMap":{"core":{"en":"CORE IMAGE: two pans hang from one beam; when they are level, no side wins.","cn":"核心意象：一根横梁下挂两只盘子；齐平时，没有哪一边占上风。"},"chain":["TWO PANS","EQUAL WEIGHT","BEAM LEVEL","STEADINESS","REMAINING AMOUNT","EQUAL FORCES"],"branches":[{"senses":"S1","en":"INSTRUMENT: the physical scales that name the whole family.","cn":"器具：为整个词族命名的实体天平。"},{"senses":"S2 · S5","en":"STEADINESS: a body that does not tip, and a mind whose feelings do not overpower reason.","cn":"稳定：不倾倒的身体，以及情绪不压倒理性的心智。"},{"senses":"S3 · S9","en":"ACCOUNTS: money left after two columns are compared, and the act of making them equal.","cn":"账目：两栏相抵后剩下的钱，以及让两栏相等的动作。"},{"senses":"S4","en":"POWER: opposing interests or states that carry equal weight.","cn":"力量：相互对抗的利益或国家具有相同分量。"},{"senses":"S6 · S7 · S8","en":"ACTION: holding something steady, weighing choices, and adding weight to offset a heavier side.","cn":"动作：托稳某物、权衡选项，以及给较轻的一边加重量以抵消。"}]},"affixes":{"intro":{"en":"Balance is a borrowed noun, not a prefix-built word. English adds ordinary suffixes and the productive counter- and im- prefixes.","cn":"balance 是借入的名词，不是由前缀构成的词。英语给它加普通后缀，以及能产的 counter-、im- 前缀。"},"latinIntro":{"en":"The Latin source is the instrument name bilanx, built on bi- 'two' and lanx 'pan'. Latin did not derive a large verb family from it; the financial and abstract senses developed in French and English.","cn":"拉丁语来源是器具名 bilanx，由 bi-“二”和 lanx“盘”构成。拉丁语并未由此派生庞大的动词词族；财务与抽象义是在法语和英语中发展出来的。"},"items":[{"word":"balances","structure":"balance + -s (plural / third person)","meaning":"more than one balance, or 'he/she/it balances'","meaningCN":"多个天平或余额；或动词第三人称单数","example":"The two accounts show different balances.","exampleCN":"两个账户显示的余额不同。"},{"word":"balanced","structure":"balance + -ed (past participle / adjective)","meaning":"made equal, steady, or fair","meaningCN":"已取得平衡的；均衡的（-ed 构成分词或形容词）","example":"A balanced diet includes both vegetables and protein.","exampleCN":"均衡饮食既包括蔬菜也包括蛋白质。"},{"word":"balancing","structure":"balance + -ing (participle / noun)","meaning":"the act of keeping or making something level","meaningCN":"保持平衡；使平衡（-ing 构成分词或动名词）","example":"Balancing work and family takes planning.","exampleCN":"平衡工作与家庭需要计划。"},{"word":"unbalanced","structure":"un- (not) + balanced","meaning":"not steady or equal; emotionally unstable","meaningCN":"不平衡的；失衡的；情绪不稳定的（un- 表示否定）","example":"The report gave an unbalanced view of the dispute.","exampleCN":"这份报告对争端给出了不均衡的看法。"},{"word":"imbalance","structure":"im- (not) + balance","meaning":"lack of equality between two sides","meaningCN":"失衡；不平衡（im- 是 in- 的否定变体）","example":"There is a trade imbalance between the two countries.","exampleCN":"两国之间存在贸易失衡。"},{"word":"imbalanced","structure":"im- + balanced","meaning":"not evenly distributed","meaningCN":"失衡的；分配不均的","example":"An imbalanced diet can cause health problems.","exampleCN":"不均衡的饮食会导致健康问题。"},{"word":"counterbalance","structure":"counter- (against) + balance","meaning":"a weight or force that balances another","meaningCN":"平衡力；抗衡（counter- 表示“对抗”）","example":"The heavy base acts as a counterbalance for the tall lamp.","exampleCN":"沉重的底座为高灯提供了平衡。"},{"word":"counterbalanced","structure":"counter- + balance + -ed","meaning":"balanced by an opposing weight or force","meaningCN":"被平衡的；被抵消的","example":"The risk was counterbalanced by a strong guarantee.","exampleCN":"风险被强有力的担保抵消了。"},{"word":"balancer","structure":"balance + -er (person or thing that)","meaning":"a device or person that keeps something level","meaningCN":"平衡器；使平衡的人或物（-er 表示执行者）","example":"The robot uses a gyroscopic balancer to stay upright.","exampleCN":"这个机器人用陀螺平衡器保持直立。"},{"word":"microbalance","structure":"micro- (small) + balance","meaning":"a very sensitive balance for tiny masses","meaningCN":"微量天平（micro- 表示“微小”）","example":"The lab weighed the sample on a microbalance.","exampleCN":"实验室用微量天平称量样品。"}],"latinEntries":[{"word":"bilanx","structure":"bi- (two) + lanx (pan)","meaning":"having two pans; a two-pan balance","meaningCN":"有两只秤盘的；双盘天平"},{"word":"lanx","structure":"Latin noun","meaning":"dish, plate, pan of a scale","meaningCN":"盘子；碟；天平秤盘"},{"word":"libra","structure":"Latin noun","meaning":"scales, balance; also a unit of weight (a related word, not the direct source)","meaningCN":"天平；秤；也指重量单位（相关词，并非本词的直接来源）"}]}},{"word":"barrier","ipa_uk":"/ˈbæriə/","ipa_us":"/ˈbæriər/","definition_zh":"障碍；屏障；壁垒；隔阂","definition_en":"a physical structure or an abstract condition that stops movement, access, or progress","core_image":"横在路上的栏杆：把人挡在一侧","scene":"A metal barrier closed the road after the landslide.","sceneCN":"这里 barrier 是「实体隔离设施」（第 1 个义项：挡住通行的实物）；句意：山体滑坡后，一道金属护栏封住了公路。场景要点：金属横杆、封闭的道路、滑坡碎石。","pos":[{"tag":"n.","zh":"障碍；屏障；壁垒；隔阂"},{"tag":"n.","zh":"（贸易、心理、技术等方面的）壁垒"}],"collocations":[{"phrase":"a physical barrier","zh":"实体屏障"},{"phrase":"a barrier to progress","zh":"进步的障碍"},{"phrase":"language barrier","zh":"语言障碍"},{"phrase":"trade barrier","zh":"贸易壁垒"},{"phrase":"break down barriers","zh":"打破隔阂"}],"forms":[{"label":"复数（名词）","form":"barriers"}],"derivatives":[{"word":"barrier-free","pos":"adj.","zh":"无障碍的（便于残障人士通行）"},{"word":"barrierless","pos":"adj.","zh":"无屏障的（技术用语）"},{"word":"barrier island","pos":"n.","zh":"障壁岛（沿海狭长岛屿）"},{"word":"barrier method","pos":"n.","zh":"屏障避孕法"}],"senses":[{"no":"01","title":"A physical structure that blocks passage","titleCN":"实体屏障：挡住通行","definition":"a fence, gate, wall, or similar structure that stops people or vehicles from going through","definitionCN":"栅栏、门、墙或类似结构，阻止人或车辆通过","example":"Police set up barriers around the construction site.","exampleCN":"警察在施工现场周围设置了隔离栏。","why":"The word is built on bar: a bar placed across an opening. The first sense is simply that bar made into a standing structure.","whyCN":"这个词建立在 bar（横杆）上：一根横杆横在出入口。第一个义项就是把这根横杆做成固定的设施。"},{"no":"02","title":"A natural obstacle","titleCN":"天然障碍：地形挡住去路","definition":"a natural feature such as a mountain range, river, reef, or ice wall that prevents movement","definitionCN":"山脉、河流、礁石或冰墙等自然地貌，阻止移动","example":"The Himalayas formed a barrier between the two regions.","exampleCN":"喜马拉雅山脉构成了两个地区之间的屏障。","why":"No human built it, but the geometry is the same: something stands across the route and blocks passage.","whyCN":"它不是人建的，但几何关系相同：有东西横在路线上，挡住通行。"},{"no":"03","title":"An obstacle to progress","titleCN":"抽象障碍：事情推不动","definition":"a condition that prevents something from developing or being achieved","definitionCN":"阻止某事发展或实现的条件","example":"High costs remain the main barrier to wider adoption.","exampleCN":"高成本仍是阻碍更广泛采用的主要障碍。","why":"The bar is no longer physical: it stands across a path of development, so the project cannot move past it.","whyCN":"横杆不再是实体的：它横在发展路径上，项目因此过不去。"},{"no":"04","title":"A language or cultural divide","titleCN":"语言与文化隔阂：沟通过不去","definition":"a difference in language, customs, or background that makes communication or understanding difficult","definitionCN":"语言、习俗或背景差异，使沟通或理解变得困难","example":"The language barrier made the first weeks abroad exhausting.","exampleCN":"语言障碍让出国的头几周非常疲惫。","why":"A gap between people works like a wall across a road: messages cannot pass, so each side stays on its own side.","whyCN":"人与人之间的差距就像横在路上的墙：信息过不去，各自留在自己那一侧。"},{"no":"05","title":"A trade or regulatory barrier","titleCN":"贸易壁垒：用规则挡货","definition":"a tariff, quota, standard, or rule that restricts the movement of goods or services","definitionCN":"限制商品或服务流动的关税、配额、标准或规则","example":"The new import standards became a barrier to foreign farmers.","exampleCN":"新的进口标准成了外国农户的壁垒。","why":"A border is a line, and a tariff is a bar laid along it. The goods are stopped at the line just as people are stopped at a gate.","whyCN":"国境是一条线，关税就是沿这条线横放的杆。货物像人一样，在门口被拦住。"},{"no":"06","title":"A psychological barrier","titleCN":"心理壁垒：自己先被挡住","definition":"an internal fear, belief, or habit that stops a person from acting","definitionCN":"阻止一个人行动的内在恐惧、信念或习惯","example":"She had to overcome a mental barrier before speaking in public.","exampleCN":"她必须先克服心理障碍，才能在公众面前讲话。","why":"The wall is now inside the person: the route is open, but an internal bar keeps the will from moving forward.","whyCN":"墙现在在人的内部：路是通的，但一道内在的横杆让意愿迈不出去。"},{"no":"07","title":"A defensive or military line","titleCN":"防御屏障：军事上的挡线","definition":"a line of defence, such as a wall, trench, or fortified position, that stops an enemy","definitionCN":"阻止敌方的防线，如城墙、壕沟或工事","example":"The river served as a natural defensive barrier.","exampleCN":"这条河充当了天然防御屏障。","why":"Here the bar is placed against an army. The purpose is not to keep things out of a field but to keep an armed force from crossing.","whyCN":"这里的横杆是针对军队放置的。目的不是把东西挡在田外，而是不让武装力量越过去。"},{"no":"08","title":"A biological membrane or boundary","titleCN":"生物屏障：身体或细胞的边界","definition":"in biology and medicine, a membrane or layer that controls what can pass into a tissue or organ","definitionCN":"生物学与医学中控制物质进入组织或器官的膜或层","example":"The blood-brain barrier protects the brain from many toxins.","exampleCN":"血脑屏障保护大脑免受许多毒素侵害。","why":"A cell or organ is an enclosed space; the barrier is the wall at its entrance, deciding which molecules may cross.","whyCN":"细胞或器官是被围起来的空间；屏障就是入口处的墙，决定哪些分子可以越过。"}],"etymology":{"intro":{"en":"Barrier is a French building word: a bar turned into a structure. Its history is the spread of that bar from a gate to trade, language, psychology and biology.","cn":"barrier 是一个法语建筑词：把一根横杆做成设施。它的历史，就是这根横杆从大门扩展到贸易、语言、心理和生物领域的过程。"},"items":[{"era":"LATE 13C.","en":"English borrowed barriere from Old French, where it meant a barrier, gate, or rampart. The earliest English uses are military and physical.","cn":"英语从古法语借入 barriere，意为屏障、门、壁垒。英语最早的用法是军事和实体层面的。"},{"era":"OLD FRENCH barriere","en":"Barriere was formed from barre 'bar' plus -iere, a suffix for a place or thing associated with it: a structure made of bars.","cn":"barriere 由 barre“横杆”加 -iere 构成，后者表示与该物相关的地点或物件：用横杆做成的设施。"},{"era":"OLD FRENCH barre","en":"Barre meant a bar, bolt, or rod used to fasten or block a door. English bar comes from the same word.","cn":"barre 指用于闩门或挡门的横杆、门闩、杆。英语的 bar 也来自同一个词。"},{"era":"VULGAR LATIN *barra","en":"The French word goes back to Vulgar Latin *barra 'bar, barrier'. One suggestion traces it to Gaulish *barros 'the bushy end', but the OED regards this explanation as discredited.","cn":"这个法语词可追溯到通俗拉丁语 *barra“横杆、障碍”。有说法认为它来自高卢语 *barros“丛毛状的末端”，但《牛津英语词典》认为此说不可信（discredited）。"},{"era":"SEMANTIC EXPANSION","en":"From a gate structure came 'anything that blocks a route', then 'anything that blocks progress', and finally trade, psychological, and biological barriers.","cn":"从门口设施生出“任何挡住路的东西”，再生成“任何阻碍进展的东西”，最后扩展到贸易、心理和生物屏障。"},{"era":"MODERN ENGLISH","en":"The core image has never changed: a bar stands across an opening. Only the opening has become abstract — a market, a conversation, a mind, a cell membrane.","cn":"核心意象从未改变：一根横杆横在开口处。改变的只是“开口”变抽象了——市场、对话、心智、细胞膜。"}]},"similar":{"note":{"en":"The first group is built on the same bar; the second collects blocking words that differ in what kind of obstacle they describe.","cn":"第一组建立在同一个 bar 上，第二组收“阻挡”类词，但各自描述的障碍类型不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bar","ipa":"/bɑː/","tag":"root word","definition":"a rod or rail used to block, fasten, or hold. Barrier is a structure built from this word.","definitionCN":"用于阻挡、闩住或支撑的杆或栏。barrier 就是用这个词做成的设施。"},{"word":"barrage","ipa":"/bəˈrɑːʒ/","tag":"same building image","definition":"a heavy continuous attack, or a dam across a river. It comes from French barrer 'to bar', so the image is again something laid across.","definitionCN":"密集连续的攻击，或横在河上的拦河坝。它来自法语 barrer“阻挡”，意象仍是横在中间的东西。"},{"word":"barrister","ipa":"/ˈbɑːrɪstə/","tag":"bar as a profession","definition":"a lawyer who argues in court. The bar is the rail separating judges from the public; a barrister is admitted to that bar.","definitionCN":"在法庭上辩护的律师。bar 是隔开法官与公众的围栏；barrister 就是获准进入那道围栏的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"obstacle","ipa":"/əˈstɑːkl/","tag":"general blockage","definition":"something that stands in the way and must be gone around or removed. It is broader and more abstract than barrier.","definitionCN":"挡在路上、必须绕过或清除的东西。它比 barrier 更宽泛、更抽象。"},{"word":"hurdle","ipa":"/ˈhɜːdl/","tag":"something to jump over","definition":"an obstacle in a race, or a difficulty to overcome. It suggests effort and forward motion, not a permanent wall.","definitionCN":"赛跑中的跨栏，或需要克服的困难。它暗示用力向前，而不是一堵永久的墙。"},{"word":"blockade","ipa":"/blɒˈkeɪd/","tag":"closing a route","definition":"the sealing of a port or road to stop movement. It is an active, organized closure, usually military.","definitionCN":"封锁港口或道路以阻止通行。它是有组织、主动的封锁，通常带军事色彩。"},{"word":"fence","ipa":"/fens/","tag":"specific structure","definition":"a barrier of posts and wire or wood around an area. Fence is a kind of barrier, but barrier is the general term.","definitionCN":"由柱子和铁丝或木头围成的屏障。fence 是 barrier 的一种，barrier 是总称。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: bar 'rod', -ier as 'thing associated with', and the English word bar itself.","cn":"只用真实成分与同族词：bar“横杆”、-ier 表示“相关之物”，以及英语本词 bar。"},"normal":[{"en":"Barrier is bar + -ier: literally 'a thing made of bars'.","cn":"barrier 是 bar + -ier：字面就是“用横杆做成的设施”。"},{"en":"The bar in barrier is the same bar in bar, barred, and behind bars.","cn":"barrier 里的 bar，就是 bar、barred、behind bars 里的那个 bar。"},{"en":"A trade barrier is a bar laid along a national border.","cn":"trade barrier 就是沿国境横放的一根杆。"},{"en":"The blood-brain barrier is a biological gate: it chooses which molecules may enter the brain.","cn":"血脑屏障是一道生物之门：它选择哪些分子可以进入大脑。"},{"en":"A barrier island is literally an island that bars the mainland from the open sea.","cn":"barrier island（障壁岛）字面就是“把大陆与外海隔开的岛”。"}],"abstract":[{"en":"Everything called a barrier shares one geometry: an opening, and something placed across it.","cn":"所有叫 barrier 的东西都共享一种几何：一个开口，以及横在开口上的东西。"},{"en":"Barriers do not have to be visible. A rule, a fear, or a missing skill can stand in exactly the same place.","cn":"屏障不必看得见。一条规则、一种恐惧、一项缺失的技能，都能站在完全相同的位置上。"},{"en":"To break a barrier is to change the geometry, not just to push harder against the bar.","cn":"打破屏障是改变几何关系，而不只是更用力地推那根横杆。"}]},"examples":[{"en":"The new bridge removed a natural barrier between the two villages.","cn":"新桥消除了两个村庄之间的天然屏障。"},{"en":"Cost is often the biggest barrier to treatment.","cn":"费用常常是治疗的最大障碍。"},{"en":"The course is designed to help students cross the language barrier.","cn":"这门课程旨在帮助学生跨越语言障碍。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“巴瑞尔”——巴瑞尔在路口拉起一根横杆，谁都过不去 → barrier 障碍、屏障","word":"barrier"},"root":"源自古法语 barriere“屏障、门、壁垒”，由 barre“横杆”加 -iere（相关之物）构成；核心是“一根横杆挡在开口处”。","sensesIntro":{"en":"Eight senses of barrier, all built on one geometry: a bar placed across an opening, so that movement cannot pass.","cn":"barrier 的八个义项都建立在同一种几何关系上：一根横杆横在开口处，通行因此过不去。"},"semanticMap":{"core":{"en":"CORE IMAGE: something laid across an opening, stopping passage.","cn":"核心意象：有东西横在开口处，阻断通行。"},"chain":["A BAR","LAID ACROSS","OPENING CLOSED","MOVEMENT STOPPED","ACCESS RESTRICTED","PROGRESS OR COMMUNICATION BLOCKED"],"branches":[{"senses":"S1 · S2 · S7","en":"PHYSICAL BLOCKS: built structures, natural terrain, and military defence lines.","cn":"实体阻挡：人造设施、天然地形和军事防线。"},{"senses":"S3","en":"PROGRESS: a condition that keeps a plan or project from moving forward.","cn":"进展：让计划或项目无法向前推进的条件。"},{"senses":"S4","en":"COMMUNICATION: language and culture stand between people like a wall across a road.","cn":"沟通：语言与文化像横在路上的墙，隔在人与人之间。"},{"senses":"S5","en":"MARKETS: tariffs and standards stop goods at the border.","cn":"市场：关税与标准把货物拦在国境线上。"},{"senses":"S6 · S8","en":"INNER AND BIOLOGICAL BOUNDARIES: a fear inside the mind, a membrane around an organ.","cn":"内在与生物边界：心智内部的恐惧，器官外围的膜。"}]},"affixes":{"intro":{"en":"Barrier itself is a French derivative of bar. English then builds compounds such as barrier-free and barrier island instead of adding new suffixes.","cn":"barrier 本身就是 bar 的法语派生词。英语后来主要造 barrier-free、barrier island 这类复合词，而不再加新后缀。"},"latinIntro":{"en":"There is no reliable classical Latin noun for barrier. The French word goes back to Vulgar Latin *barra, whose deeper origin is uncertain, so latinEntries is left empty rather than inventing a root.","cn":"barrier 没有可靠的古典拉丁语名词来源。这个法语词可追溯到通俗拉丁语 *barra，但其更深来源不确定，因此 latinEntries 留空，不编造词根。"},"items":[{"word":"bar","structure":"base noun / verb","meaning":"a rod that blocks or fastens; to block or forbid","meaningCN":"横杆；门闩；阻挡；禁止","example":"He barred the door before going to bed.","exampleCN":"他睡觉前闩上了门。"},{"word":"barred","structure":"bar + -ed (past participle / adjective)","meaning":"blocked, forbidden, or marked with bars","meaningCN":"被阻挡的；被禁止的；有条纹的","example":"The player was barred from the competition.","exampleCN":"这名选手被禁止参加比赛。"},{"word":"barring","structure":"bar + -ing (preposition / participle)","meaning":"except for; preventing","meaningCN":"除……之外；阻挡（-ing 构成介词或分词）","example":"Barring bad weather, we leave tomorrow.","exampleCN":"除非天气不好，我们明天出发。"},{"word":"debar","structure":"de- (away, down) + bar","meaning":"to exclude or forbid someone officially","meaningCN":"正式排除；禁止（de- 表示“除去”）","example":"The court debarred him from practising law.","exampleCN":"法院禁止他执业做律师。"},{"word":"barrier","structure":"bar + -ier (thing associated with)","meaning":"a structure or condition that blocks passage","meaningCN":"屏障；障碍（-ier 表示相关之物）","example":"The barrier at the entrance requires a ticket.","exampleCN":"入口的闸机需要刷票。"},{"word":"barriers","structure":"barrier + -s (plural)","meaning":"more than one barrier","meaningCN":"多道屏障；多重障碍","example":"The report lists the barriers to equal access.","exampleCN":"报告列出了平等获取的多重障碍。"},{"word":"barrier-free","structure":"barrier + free (without)","meaning":"designed so that people with disabilities can use it","meaningCN":"无障碍的（free 表示“没有”）","example":"The station has barrier-free access to every platform.","exampleCN":"该车站每个站台都有无障碍通道。"},{"word":"barrier reef","structure":"barrier + reef (compound noun)","meaning":"a coral reef running parallel to a coast and enclosing a lagoon","meaningCN":"堡礁：与海岸平行、围出海湖的珊瑚礁","example":"The Great Barrier Reef is visible from space.","exampleCN":"大堡礁从太空都能看见。"},{"word":"barrier island","structure":"barrier + island (compound noun)","meaning":"a long narrow island that protects the mainland from waves","meaningCN":"障壁岛：保护大陆免受海浪冲击的狭长岛屿","example":"The barrier island shifted after the hurricane.","exampleCN":"飓风过后，障壁岛的位置移动了。"}],"latinEntries":[]}},{"word":"basic","ipa_uk":"/ˈbeɪsɪk/","ipa_us":"/ˈbeɪsɪk/","definition_zh":"基本的；基础的；简单的；基本需要的","definition_en":"forming the foundation of something, simple and not advanced, or necessary at the most essential level","core_image":"房屋最底下那层基石","scene":"The shelter provides basic needs: clean water, food, and a dry place to sleep.","sceneCN":"这里 basic 是「最低限度的、最必需的」（第 3 个义项：基本需求）；句意：这个庇护所提供基本需求：干净的水、食物和干燥的睡觉处。场景要点：水桶、食物箱、简易床铺。","pos":[{"tag":"adj.","zh":"基本的；基础的；简单的；初级的"},{"tag":"n.","zh":"基础；基本要素（常用复数 basics）"}],"collocations":[{"phrase":"basic needs","zh":"基本需求"},{"phrase":"basic principles","zh":"基本原则"},{"phrase":"basic skills","zh":"基本技能"},{"phrase":"basic training","zh":"基础训练；新兵训练"},{"phrase":"get back to basics","zh":"回归基础"}],"forms":[{"label":"比较级（更多用 more 构成）","form":"more basic"},{"label":"最高级（更多用 most 构成）","form":"most basic"},{"label":"复数（名词 basics）","form":"basics"}],"derivatives":[{"word":"basically","pos":"adv.","zh":"基本上；大体而言"},{"word":"basics","pos":"n.","zh":"基础知识；基本要素"},{"word":"basicity","pos":"n.","zh":"碱度；碱性（化学）"},{"word":"basicness","pos":"n.","zh":"基本性（较少用）"}],"senses":[{"no":"01","title":"Fundamental and essential","titleCN":"根本的：构成基础","definition":"forming the base or foundation of a system, idea, or skill","definitionCN":"构成某个体系、观念或技能的基础","example":"Trust is a basic condition for any team.","exampleCN":"信任是任何团队的基本条件。","why":"Basic is base + -ic: 'of the base'. What is basic sits at the bottom and holds the rest up.","whyCN":"basic 是 base + -ic，意为“基石的”。basic 的东西位于最底下，托住其余部分。"},{"no":"02","title":"Simple and not advanced","titleCN":"简单的：尚未进阶","definition":"simple, plain, or at an introductory level rather than an advanced one","definitionCN":"简单、朴素，或处于入门水平而非高级水平","example":"The instructions are written in basic English.","exampleCN":"说明是用基础英语写的。","why":"A foundation comes before upper floors. Something at the bottom level is simpler than what is built on it, so basic also means 'elementary'.","whyCN":"地基先于上层。位于底层的东西比建在它上面的东西简单，所以 basic 也指“初级的”。"},{"no":"03","title":"The minimum needed to survive or function","titleCN":"最低限度的：维持生存或运转","definition":"necessary at the lowest level, without extras","definitionCN":"最低层级上必需的，没有额外附加","example":"The charity guarantees basic food and shelter for every family.","exampleCN":"该慈善机构为每个家庭保证基本的食物和住所。","why":"If you strip a structure down to its base, only what supports it remains. Basic needs are that supporting layer for a person.","whyCN":"把结构一路剥到底，只剩支撑它的部分。基本需求就是支撑一个人的那一层。"},{"no":"04","title":"Chemistry: alkaline","titleCN":"化学：碱性的","definition":"in chemistry, having a pH greater than 7 and reacting like a base","definitionCN":"化学上 pH 大于 7、像碱一样反应的","example":"Soap is basic and can irritate sensitive skin.","exampleCN":"肥皂呈碱性，可能刺激敏感皮肤。","why":"In chemistry a base is the substance that neutralizes an acid. Basic is the adjective meaning 'having the properties of a base'.","whyCN":"化学中的 base 是中和酸的物质。basic 就是“具有碱（base）性质”的形容词。"},{"no":"05","title":"Introductory training","titleCN":"入门训练：进入专业前的底子","definition":"describing the first stage of training before specialized work","definitionCN":"描述专业工作之前的第一阶段训练","example":"Recruits spend eight weeks in basic training.","exampleCN":"新兵要接受八周基础训练。","why":"Before a soldier can use advanced equipment, the base skills must be laid down; the first stage is therefore called basic.","whyCN":"士兵在使用高级装备之前，必须先打好底层技能；因此第一阶段叫 basic。"},{"no":"06","title":"The basics as a plural noun","titleCN":"基础要素：成组的基本知识","definition":"the most important simple facts or skills of a subject, used in the plural","definitionCN":"某学科最重要、最简单的知识或技能，用复数形式","example":"The course starts with the basics of accounting.","exampleCN":"课程从会计基础讲起。","why":"The plural turns the foundation into a set of separate supports: several basic facts laid side by side under a subject.","whyCN":"复数把“地基”变成一组分开的支柱：若干基本知识点并排放在一个学科下面。"},{"no":"07","title":"Base pay without extras","titleCN":"基本薪酬：不含附加部分","definition":"describing the fixed part of a salary before bonuses, overtime, or allowances","definitionCN":"描述工资中扣除奖金、加班费或补贴之前的固定部分","example":"The job pays a basic salary plus performance bonuses.","exampleCN":"这份工作付基本工资加绩效奖金。","why":"The base layer of a wage is the part that exists before anything is added on top. Basic marks that layer.","whyCN":"工资的底层部分是加任何东西之前就存在的部分。basic 标记的就是这一层。"},{"no":"08","title":"Fundamental research","titleCN":"基础研究：先问原理，不问用途","definition":"describing research done to understand principles rather than to solve an immediate practical problem","definitionCN":"描述以理解原理为目的、而非解决眼前实际问题研究","example":"Basic research on cells later led to a new class of drugs.","exampleCN":"对细胞的基础研究后来催生了一类新药。","why":"Research also has a base: work that establishes principles sits below applied work that uses them.","whyCN":"研究也有底层：确立原理的工作，位于使用这些原理的应用工作之下。"}],"etymology":{"intro":{"en":"Basic is a modern English adjective built on base, whose history runs back through Latin basis to Greek 'step, pedestal'. The word has stayed close to that image of a supporting bottom layer.","cn":"basic 是建立在现代英语 base 上的形容词，而 base 的历史经拉丁语 basis 追溯到希腊语“台阶、基座”。这个词一直贴近“托底的支撑层”这一意象。"},"items":[{"era":"1770S","en":"Basic is first recorded in the 1770s as 'relating to a base'. It was formed in English from base plus the adjective suffix -ic, not borrowed whole from Latin.","cn":"basic 最早记录于 1770 年代，意为“与基座有关的”。它是在英语中用 base 加形容词后缀 -ic 造出来的，并非整体借自拉丁语。"},{"era":"ENGLISH base","en":"Base came into English through Old French bas 'low' and Latin basis. In English it developed the physical sense 'bottom support' and then the abstract sense 'starting point'.","cn":"base 经古法语 bas“低的”和拉丁语 basis 进入英语。在英语中先发展出“底部支撑”的实体义，再发展出“起点、基础”的抽象义。"},{"era":"LATIN basis","en":"Latin basis meant 'foundation, pedestal, foot'. It was borrowed from Greek basis 'a step, pedestal', from bainein 'to go, step'.","cn":"拉丁语 basis 意为“地基、基座、脚”。它借自希腊语 basis“台阶、基座”，而后者来自 bainein“走、迈步”。"},{"era":"GREEK bainein","en":"The Greek verb bainein 'to go, step' supplied the image of something you stand on. A pedestal is literally a place where a foot is placed.","cn":"希腊语动词 bainein“走、迈步”提供了“站立之处”的意象。基座字面上就是放脚的地方。"},{"era":"SEMANTIC EXPANSION","en":"From 'relating to a base', basic moved to 'fundamental', then 'simple, introductory', and finally to technical senses such as alkaline chemistry.","cn":"从“与基座有关的”，basic 转向“根本的”，再转向“简单的、入门的”，最后进入化学碱性等技术义。"},{"era":"RELATED FAMILY","en":"Basis and base share the Greek root; basic is their English adjective. Basal is the anatomical adjective. The financial use of basis still means the underlying price level.","cn":"basis 与 base 共享希腊词根，basic 是它们的英语形容词，basal 是解剖学形容词。金融中的 basis 仍指底层价格水平。"}]},"similar":{"note":{"en":"The first group is built on base and basis; the second collects words for 'foundational' and 'elementary' with different shades.","cn":"第一组建立在 base 和 basis 上；第二组收“基础的、初级的”近义词，语义侧重不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"base","ipa":"/beɪs/","tag":"root noun","definition":"the bottom support of something, or the main part of a system. Basic is the adjective formed from it.","definitionCN":"某物的底部支撑，或体系的主要部分。basic 是由它构成的形容词。"},{"word":"basis","ipa":"/ˈbeɪsɪs/","tag":"same root, different ending","definition":"the underlying principle or starting point. It is the Latin form of the same Greek word behind base.","definitionCN":"底层原则或起点。它是 base 背后同一个希腊词的拉丁语形式。"},{"word":"basal","ipa":"/ˈbeɪsl/","tag":"derived adjective","definition":"relating to a base, especially the bottom layer of a cell or organ. It is a technical adjective beside basic.","definitionCN":"与基座有关的，尤指细胞或器官的底层。它是 basic 旁边的技术性形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fundamental","ipa":"/ˌfʌndəˈmentl/","tag":"deep foundation","definition":"forming the deepest and most necessary part of something. It is stronger and more formal than basic.","definitionCN":"构成某物最深、最必要的部分。它比 basic 更强、更正式。"},{"word":"elementary","ipa":"/ˌelɪˈmentri/","tag":"first stage","definition":"simple and introductory, suitable for beginners. It stresses the first level of learning rather than underlying structure.","definitionCN":"简单、入门的，适合初学者。它强调学习的第一层级，而不是底层结构。"},{"word":"essential","ipa":"/ɪˈsenʃl/","tag":"cannot be removed","definition":"absolutely necessary; something without which the thing cannot exist. Essential stresses necessity, basic stresses foundation.","definitionCN":"绝对必要的；缺了它事物就无法存在。essential 强调必要性，basic 强调基础地位。"},{"word":"rudimentary","ipa":"/ˌruːdɪˈmentri/","tag":"very early stage","definition":"basic in the sense of undeveloped or only partly formed. It often suggests something crude or incomplete.","definitionCN":"处于未发展或仅部分形成的初级状态。它常暗示粗糙或不完整。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: base + -ic, the Latin basis, and the technical adjective basal.","cn":"只用真实成分与同族词：base + -ic、拉丁语 basis，以及技术形容词 basal。"},"normal":[{"en":"Basic is base + -ic: it means 'of the base', just as historic means 'of history'.","cn":"basic 是 base + -ic，意为“基座的”，就像 historic 意为“历史的”。"},{"en":"The base of a building is the layer you never see but everything stands on. Basic knowledge works the same way.","cn":"建筑的基础是你看不见、但所有东西都踩在上面的那层。基础知识也是这样。"},{"en":"Basic training comes before advanced training, just as a foundation comes before the upper floors.","cn":"basic training 在高级训练之前，就像地基在上层楼之前。"},{"en":"In chemistry, a base neutralizes acid; the adjective basic describes a substance with that property.","cn":"化学中 base 能中和酸；形容词 basic 描述具有这种性质的物质。"},{"en":"The basics are the few supports you must lay down before you can build anything else.","cn":"the basics 是你造任何东西之前必须先铺下的那几根支柱。"}],"abstract":[{"en":"Picture a building with everything removed except the foundation. What remains is basic.","cn":"想象一栋楼被拆到只剩地基。剩下的那部分就是 basic。"},{"en":"Basic does not mean 'unimportant'. It means 'load-bearing': remove it, and the upper levels collapse.","cn":"basic 不等于“不重要”，而是“承重的”：抽掉它，上层就塌。"},{"en":"The word always implies a vertical relation: something below, something built on top.","cn":"这个词总暗示一种上下关系：有东西在下面，有东西建在上面。"}]},"examples":[{"en":"Clean water is a basic human need.","cn":"干净的水是人的基本需求。"},{"en":"You need basic math to understand the graph.","cn":"理解这张图需要基础数学。"},{"en":"The manual explains the basics of the machine in ten pages.","cn":"手册用十页讲清了这台机器的基础知识。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“贝斯克”——贝斯克把地基（base）砌好，上面才敢盖楼 → basic 基础的、基本的","word":"basic"},"root":"由英语 base“基座、基础”加 -ic 构成；base 经古法语与拉丁语 basis 追溯到希腊语 basis“台阶、基座”，核心是“托底的支撑层”。","sensesIntro":{"en":"Eight senses of basic, all built on one image: the bottom layer that everything else stands on, whether in a building, a subject, a diet, or a chemistry beaker.","cn":"basic 的八个义项都建立在一个意象上：其他东西都踩在其上的底层——无论是在建筑、学科、饮食还是化学烧杯里。"},"semanticMap":{"core":{"en":"CORE IMAGE: the foundation layer at the bottom, supporting everything above it.","cn":"核心意象：位于最底部的基座层，托住上面的一切。"},"chain":["BASE LAYER","SUPPORTS THE REST","COMES FIRST","STRIPPED OF EXTRAS","MINIMUM LEVEL","FOUNDATIONAL PRINCIPLE"],"branches":[{"senses":"S1 · S8","en":"FOUNDATION: principles and research that hold up everything built on them.","cn":"基础：托住其上一切的原则与研究。"},{"senses":"S2 · S6","en":"ENTRY LEVEL: simple knowledge and the set of facts called the basics.","cn":"入门层级：简单的知识，以及被称为 basics 的一组基本事实。"},{"senses":"S3 · S7","en":"MINIMUM: needs without extras, and the fixed part of pay before additions.","cn":"最低限度：没有附加的需求，以及工资中加项之前的固定部分。"},{"senses":"S4","en":"CHEMISTRY: a substance with the properties of a base, pH above 7.","cn":"化学：具有碱的性质、pH 大于 7 的物质。"},{"senses":"S5","en":"FIRST TRAINING: the stage that lays the base skills before specialization.","cn":"最初训练：在专业化之前铺设底层技能的阶段。"}]},"affixes":{"intro":{"en":"Basic is an English suffix formation: base + -ic. The productive suffixes around it are -ally, -ity, and the plural -s; the prefix un- is not used with basic.","cn":"basic 是英语后缀构词：base + -ic。它周围能产的后缀有 -ally、-ity 和复数 -s；basic 一般不加 un-。"},"latinIntro":{"en":"Greek basis entered Latin unchanged as basis 'foundation, pedestal'. Latin built few derivatives that English uses; the modern family comes from English base and French-derived bas.","cn":"希腊语 basis 原样进入拉丁语，仍作 basis“地基、基座”。拉丁语由此派生的词英语很少使用；现代词族主要来自英语 base 和经法语传来的 bas。"},"items":[{"word":"base","structure":"free noun / verb / adjective","meaning":"the bottom support; to found or station something","meaningCN":"底部支撑；以……为基础；驻扎","example":"The company is based in Shanghai.","exampleCN":"公司总部设在上海。"},{"word":"basics","structure":"basic + -s (plural noun)","meaning":"the simplest and most necessary facts or skills","meaningCN":"基础知识；基本要素（复数名词）","example":"Let us review the basics before the test.","exampleCN":"考试前我们先复习基础。"},{"word":"basically","structure":"basic + -ally (adverb)","meaning":"in the main; in simple terms","meaningCN":"基本上；大体说来（-ally 构成副词）","example":"Basically, the plan has two steps.","exampleCN":"基本上，这个计划分两步。"},{"word":"basicity","structure":"basic + -ity (state noun)","meaning":"the quality or degree of being alkaline","meaningCN":"碱性；碱度（-ity 表示性质或程度）","example":"The basicity of the solution was measured with a pH meter.","exampleCN":"溶液的碱度用 pH 计测量。"},{"word":"basal","structure":"base + -al (relating to)","meaning":"relating to a base or bottom layer","meaningCN":"基部的；底层的（-al 表示“与……有关”）","example":"Basal cells line the bottom of the skin's outer layer.","exampleCN":"基底细胞排列在皮肤外层的底部。"},{"word":"baseline","structure":"base + line (compound noun)","meaning":"a measured starting level for comparison","meaningCN":"基线；基准线（复合名词）","example":"We recorded the baseline before the experiment.","exampleCN":"实验前我们记录了基线数据。"},{"word":"baseless","structure":"base + -less (without)","meaning":"without foundation; unsupported","meaningCN":"无根据的；无基础的（-less 表示“没有”）","example":"The rumour turned out to be baseless.","exampleCN":"那个谣言最终证明没有根据。"},{"word":"debase","structure":"de- (down) + base","meaning":"to lower the value or quality of something","meaningCN":"贬低；降低价值或品质（de- 表示“向下”）","example":"Excessive advertising can debase a serious brand.","exampleCN":"过度广告会贬低一个严肃品牌的价值。"},{"word":"debasement","structure":"debase + -ment (process noun)","meaning":"the act of lowering value or quality","meaningCN":"贬低；降低（-ment 表示行为或结果）","example":"The debasement of the currency caused rapid inflation.","exampleCN":"货币贬值引发了快速通胀。"}],"latinEntries":[{"word":"basis","structure":"Greek basis 'step, pedestal', borrowed into Latin","meaning":"foundation, pedestal, base","meaningCN":"地基；基座；基础"}]}},{"word":"benefit","ipa_uk":"/ˈbenɪfɪt/","ipa_us":"/ˈbenɪfɪt/","definition_zh":"好处；益处；福利；使受益","definition_en":"an advantage or positive effect, a payment or right given to someone, or to help someone and be helped in turn","core_image":"一只手把“好事”递到另一只手里：bene 好 + facere 做","scene":"The new rail link will benefit thousands of commuters.","sceneCN":"这里 benefit 是动词「使受益」（第 5 个义项：帮助某人、给某人带来好处）；句意：新的铁路连接将使数千名通勤者受益。场景要点：新线路、通勤人群、时间与成本的节省。","pos":[{"tag":"n.","zh":"好处；益处；福利；津贴"},{"tag":"vt.","zh":"使受益；有益于"},{"tag":"vi.","zh":"受益；得到好处（benefit from）"}],"collocations":[{"phrase":"benefit from","zh":"从……中受益"},{"phrase":"for the benefit of","zh":"为了……的利益"},{"phrase":"employee benefits","zh":"员工福利"},{"phrase":"a benefit concert","zh":"慈善音乐会"},{"phrase":"benefit of the doubt","zh":"（在证据不足时）假定其无罪／假定其善意"}],"forms":[{"label":"复数（名词）","form":"benefits"},{"label":"三单（he/she/it）","form":"benefits"},{"label":"过去式（已经发生）","form":"benefited"},{"label":"过去分词（完成／被动）","form":"benefited"},{"label":"现在分词（进行体）","form":"benefiting"}],"derivatives":[{"word":"beneficial","pos":"adj.","zh":"有益的；有利的"},{"word":"beneficiary","pos":"n.","zh":"受益人；受惠者"},{"word":"benefactor","pos":"n.","zh":"捐助人；恩人"},{"word":"beneficence","pos":"n.","zh":"善行；仁慈"}],"senses":[{"no":"01","title":"An advantage or positive effect","titleCN":"好处：带来正面效果","definition":"a helpful or positive result that something produces","definitionCN":"某事物产生的有帮助的、正面的结果","example":"One benefit of cycling is better heart health.","exampleCN":"骑车的好处之一是心脏更健康。","why":"Benefit began as 'a good deed'. A good deed is expected to produce a good result, so the result itself came to be called the benefit.","whyCN":"benefit 最初是“善行”。善行理应有好结果，于是好结果本身也被叫作 benefit。"},{"no":"02","title":"A welfare payment","titleCN":"福利金：国家给的钱","definition":"money paid by the state to someone who is ill, unemployed, or in need","definitionCN":"国家支付给生病、失业或贫困者的钱","example":"She applied for unemployment benefit after losing her job.","exampleCN":"失业后她申请了失业救济金。","why":"The state's good deed is institutionalized as a payment. The abstract 'advantage' becomes a specific sum of money.","whyCN":"国家的“善行”被制度化为一笔付款。抽象的“好处”于是变成具体的金额。"},{"no":"03","title":"An employee perk","titleCN":"员工福利：工资之外的给予","definition":"a right or advantage offered by an employer in addition to salary","definitionCN":"雇主在工资之外提供的权利或好处","example":"Health insurance is the benefit most employees value.","exampleCN":"医疗保险是员工最看重的福利。","why":"The good thing done for an employee is added on top of pay; it is a benefit rather than a wage.","whyCN":"为员工做的“好事”加在工资之上；它是 benefit，而不是工资。"},{"no":"04","title":"A charitable event","titleCN":"慈善活动：为别人筹好处","definition":"a performance or event whose proceeds go to a cause or person in need","definitionCN":"收益用于某项事业或需要帮助者的演出或活动","example":"The actors staged a benefit for the flood victims.","exampleCN":"演员们为洪灾受害者举办了一场义演。","why":"The event exists to produce a good deed for someone else. The whole occasion is named after the benefit it creates.","whyCN":"这场活动的存在，就是为了给他人做一件好事。整个活动以它所产生的 benefit 命名。"},{"no":"05","title":"To help or profit someone","titleCN":"使受益：把好处给对方","definition":"to be good for someone or to improve their situation","definitionCN":"对某人有利，或改善其处境","example":"The scholarship benefited students from low-income families.","exampleCN":"这项奖学金使低收入家庭的学生受益。","why":"The verb turns the noun into an action: a good is done to someone, and that person receives the advantage.","whyCN":"动词把名词变成动作：对某人做一件好事，那个人因此得到好处。"},{"no":"06","title":"To gain from something","titleCN":"受益：从某处得到好处","definition":"to receive an advantage from an experience, policy, or substance","definitionCN":"从某种经历、政策或物质中获得好处","example":"Children benefit from reading with their parents.","exampleCN":"孩子从与父母一起阅读中受益。","why":"Here the good deed is not performed by you but received by you. The same transfer is seen from the receiver's side.","whyCN":"这里的“好事”不是由你做出，而是由你接收。同一个转移过程，从接受者的角度去看。"},{"no":"07","title":"An insurance payout","titleCN":"保险给付：合同承诺的钱","definition":"a sum paid by an insurer when a specified event occurs","definitionCN":"保险合同约定的特定事件发生时，由保险人支付的金额","example":"The policy pays a death benefit to the named family member.","exampleCN":"这份保单向指定的家庭成员支付身故保险金。","why":"An insurance contract promises a good turn at a bad time. That promised payment is the benefit.","whyCN":"保险合约承诺在糟糕时刻给你一份好处。那笔承诺的付款就是 benefit。"},{"no":"08","title":"For someone's advantage","titleCN":"为了某人的利益","definition":"in the phrase for the benefit of, meaning for the advantage or good of a person or group","definitionCN":"在短语 for the benefit of 中，表示为某人或某群体的利益或好处","example":"The rules were changed for the benefit of small businesses.","exampleCN":"这些规则是为小企业的利益而修改的。","why":"The phrase names the person who is meant to receive the good; benefit marks the direction in which the advantage flows.","whyCN":"这个短语点明“好事” intended 的接收者；benefit 标记好处的流向。"},{"no":"09","title":"Benefit of the doubt","titleCN":"疑罪从无：把善意先给对方","definition":"in the phrase benefit of the doubt, the choice to believe someone's innocent or good explanation when the evidence is unclear","definitionCN":"在短语 benefit of the doubt 中，证据不明时选择相信对方无辜或善意的解释","example":"Since no one saw the accident, we gave the driver the benefit of the doubt.","exampleCN":"因为没人看见事故，我们选择相信司机没有过错。","why":"The good deed here is a presumption: you hand someone the advantage of being believed before proof arrives.","whyCN":"这里的“好事”是一份推定：在证据到来之前，先把“被相信”这一好处递给对方。"}],"etymology":{"intro":{"en":"Benefit goes back to Latin 'to do well'. Its journey from a good deed to a welfare cheque is a story of a moral word becoming an economic one.","cn":"benefit 可追溯到拉丁语“做好事”。它从“善行”走到“福利金”的过程，是一个道德词变成经济词的故事。"},"items":[{"era":"LATE 14C.","en":"Benefit is first recorded in English as 'a good or noble deed'. The source is Latin benefactum, not a native English formation.","cn":"benefit 在英语中最早记录为“善行、高尚之举”。其来源是拉丁语 benefactum，并非英语本族构词。"},{"era":"LATIN benefactum","en":"Benefactum meant 'a good deed', from bene facere 'to do good'. The same phrase gives English benefaction and benefactor.","cn":"benefactum 意为“善行”，来自 bene facere“做好事”。同一个短语也给了英语 benefaction 和 benefactor。"},{"era":"LATIN bene + facere","en":"Bene is an adverb 'well, rightly'; facere is 'to do, make'. A benefit is literally something done well for someone.","cn":"bene 是副词“好地、正确地”；facere 是“做、造”。benefit 字面上就是“为某人做得好的一件事”。"},{"era":"OLD FRENCH bienfait","en":"French had bienfait 'a good deed, kindness', which reinforced the Latin-derived word in English. The form benefit shows the Latin noun ending, not the French participle.","cn":"法语 bienfait“善行、恩惠”强化了英语中这个拉丁来源的词。英语形式 benefit 保留了拉丁名词词尾，而不是法语分词形式。"},{"era":"15C.–16C. SHIFT","en":"By the 15th century benefit meant 'advantage, profit'; by the 16th it was also a verb. The good deed and the good result had merged.","cn":"到 15 世纪，benefit 已指“好处、利润”；到 16 世纪又可作动词。“善行”与“好结果”已经合并。"},{"era":"MODERN ENGLISH","en":"Modern English extends the word to state welfare, employee perks, insurance payouts, charity events, and the idiom benefit of the doubt. The moral core survives as the idea of a good transferred to someone.","cn":"现代英语把这个词扩展到国家福利、员工福利、保险给付、慈善活动和习语 benefit of the doubt。其道德内核留存为“把好处转移给某人”的观念。"}]},"similar":{"note":{"en":"The first group shares the Latin bene/facere family; the second collects words for an advantage, each with a different emphasis.","cn":"第一组共享拉丁语 bene/facere 词族；第二组收表示“好处”的词，各自侧重不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"beneficial","ipa":"/ˌbenɪˈfɪʃl/","tag":"derived adjective","definition":"producing a good effect. It is the adjective from benefit, built with -ial.","definitionCN":"产生良好效果的。它是 benefit 加 -ial 构成的形容词。"},{"word":"beneficiary","ipa":"/ˌbenɪˈfɪʃəri/","tag":"same root, person","definition":"a person who receives money or an advantage, especially from a will or insurance policy. The suffix -ary marks the receiver.","definitionCN":"收到钱或好处的人，尤指遗嘱或保单的受益人。-ary 标记接受者。"},{"word":"benefactor","ipa":"/ˈbenɪfæktə/","tag":"same root, giver","definition":"a person who gives money or help to a cause. The -or suffix marks the doer of the good deed.","definitionCN":"向某项事业捐钱或提供帮助的人。-or 标记“做好事的人”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"advantage","ipa":"/ədˈvɑːntɪdʒ/","tag":"competitive edge","definition":"a condition that puts someone in a better position than others. It stresses relative superiority, while benefit stresses a good received.","definitionCN":"使某人处于比别人更有利位置的条件。它强调相对优势，benefit 强调收到的好处。"},{"word":"profit","ipa":"/ˈprɒfɪt/","tag":"money gain","definition":"financial gain after costs. It is narrower and strictly monetary, whereas benefit can be non-financial.","definitionCN":"扣除成本后的经济收益。它更窄、严格指钱；benefit 可以是非金钱的。"},{"word":"gain","ipa":"/ɡeɪn/","tag":"increase","definition":"an increase in amount, value, or advantage. Gain is broader and more neutral than benefit.","definitionCN":"数量、价值或优势的增加。gain 比 benefit 更宽泛、更中性。"},{"word":"perk","ipa":"/pɜːk/","tag":"job extra","definition":"an informal extra advantage attached to a job. It is the colloquial word for an employee benefit.","definitionCN":"工作附带的非正式额外好处。它是“员工福利”的口语说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: bene 'well', facere 'do', and the family benefactor, beneficial, beneficiary.","cn":"只用真实成分与同族词：bene“好”、facere“做”，以及 benefactor、beneficial、beneficiary 词族。"},"normal":[{"en":"Bene means 'well' and facere means 'do': a benefit is a well-done thing handed to someone.","cn":"bene 是“好”，facere 是“做”：benefit 就是“做得好、递给别人的一件事”。"},{"en":"Benefactor and beneficiary are the two ends of one transfer: the -or gives, the -ary receives.","cn":"benefactor 与 beneficiary 是同一次转移的两端：-or 给予，-ary 接收。"},{"en":"Beneficial is the adjective: a beneficial policy is one that produces a benefit.","cn":"beneficial 是形容词：a beneficial policy 就是会产生 benefit 的政策。"},{"en":"Employee benefits are the good things added on top of salary, not the salary itself.","cn":"employee benefits 是加在工资之上的好处，不是工资本身。"},{"en":"Benefit of the doubt gives the other person the advantage of being believed first.","cn":"benefit of the doubt 先把“被相信”这一好处给对方。"}],"abstract":[{"en":"Picture a transfer: something good leaves one hand and arrives in another. The giver performs the deed, the receiver holds the benefit.","cn":"想象一次转移：好的东西从一只手离开，到达另一只手。给予者做出行为，接受者持有 benefit。"},{"en":"The same word covers the deed, the result, and the payment because English treats them as one chain of goodness.","cn":"同一个词同时覆盖行为、结果和付款，因为英语把它们看成同一条“好处链”。"},{"en":"A benefit is defined by direction: it must land on someone. Remove the receiver, and the word loses its meaning.","cn":"benefit 由方向定义：它必须落在某人身上。去掉接受者，这个词就失去意义。"}]},"examples":[{"en":"The medicine benefits patients with chronic pain.","cn":"这种药使慢性疼痛患者受益。"},{"en":"Employees receive benefits including health cover and paid leave.","cn":"员工享有包括医疗保险和带薪休假在内的福利。"},{"en":"The new policy is expected to benefit the poorest households most.","cn":"新政策预计最有利于最贫困的家庭。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“本尼菲特”——本尼把好处（fit 合适的东西）递给你，你也合适了 → benefit 好处、使受益","word":"benefit"},"root":"源自拉丁语 benefactum“善行”，由 bene“好地”+ facere“做”构成；核心是“为某人做一件好事，好处落到对方手里”。","sensesIntro":{"en":"Nine senses of benefit, all built on one transfer: something good is done for someone, and that person receives the advantage.","cn":"benefit 的九个义项都建立在同一次转移上：为某人做一件好事，好处落到那个人手里。"},"semanticMap":{"core":{"en":"CORE IMAGE: a good done by one party and received by another.","cn":"核心意象：一方做出的好事，被另一方接收。"},"chain":["GOOD DEED","GOOD RESULT","ADVANTAGE RECEIVED","MONEY OR RIGHT GIVEN","HELP SOMEONE","GAIN FROM SOMETHING"],"branches":[{"senses":"S1 · S8","en":"ADVANTAGE: the positive result itself, or the direction 'for someone's good'.","cn":"好处：正面结果本身，或“为了某人的利益”这一方向。"},{"senses":"S2 · S3 · S7","en":"INSTITUTIONAL PAYMENTS: state welfare, employee perks, and insurance payouts.","cn":"制度化给付：国家福利、员工福利和保险金。"},{"senses":"S4","en":"CHARITY: an event whose whole purpose is to produce a good for others.","cn":"慈善：整场活动的目的就是为他人制造好处。"},{"senses":"S5 · S6","en":"THE VERB: to give an advantage, or to receive one from a source.","cn":"动词：给予好处，或从某个来源得到好处。"},{"senses":"S9","en":"BENEFIT OF THE DOUBT: the good handed over is a presumption of innocence.","cn":"疑罪从无：递过去的好处是“先假定无辜”。"}]},"affixes":{"intro":{"en":"Benefit is a Latin noun borrowed through French. English builds its family with -ial, -ary, -or, -ence, and -ed/-ing on the verb.","cn":"benefit 是经法语借入的拉丁名词。英语用 -ial、-ary、-or、-ence，以及动词上的 -ed/-ing 来扩展词族。"},"latinIntro":{"en":"The Latin base is bene facere 'to do well'. Benefactum is the deed, beneficium the favour or benefit, benefactor the doer, and beneficium the kindness received.","cn":"拉丁语基础是 bene facere“做好事”。benefactum 是行为，beneficium 是恩惠或好处，benefactor 是做好事的人，beneficium 也是被接受的善意。"},"items":[{"word":"benefits","structure":"benefit + -s (plural / third person)","meaning":"advantages, payments, or 'it benefits'","meaningCN":"多项好处或福利；或动词第三人称单数","example":"The job offers generous benefits.","exampleCN":"这份工作提供丰厚的福利。"},{"word":"benefited","structure":"benefit + -ed (past tense / participle)","meaning":"helped or gained an advantage","meaningCN":"受益了；使受益了（-ed 构成过去式或分词）","example":"The town benefited from the new hospital.","exampleCN":"这座小镇从新医院中受益。"},{"word":"benefiting","structure":"benefit + -ing (participle)","meaning":"helping or gaining at the present time","meaningCN":"正在受益；正在使受益（-ing 构成现在分词）","example":"Students are benefiting from the free tutoring.","exampleCN":"学生们正从免费辅导中受益。"},{"word":"beneficial","structure":"benefit + -ial (relating to)","meaning":"producing a good effect","meaningCN":"有益的；产生好效果的（-ial 表示“与……有关”）","example":"Regular exercise is beneficial to health.","exampleCN":"规律运动有益健康。"},{"word":"beneficially","structure":"beneficial + -ly (adverb)","meaning":"in a way that produces a good effect","meaningCN":"有益地；有利地","example":"The land was used beneficially for community gardens.","exampleCN":"这块地被有益地用于社区菜园。"},{"word":"beneficiary","structure":"benefit + -iary (person who receives)","meaning":"a person who receives money or an advantage","meaningCN":"受益人；受惠者（-iary 表示接受者）","example":"She named her sister as the beneficiary of the policy.","exampleCN":"她指定姐姐为保单受益人。"},{"word":"benefactor","structure":"bene + fact(or) (one who does)","meaning":"a person who gives help or money","meaningCN":"捐助人；恩人（-or 表示行为者）","example":"An anonymous benefactor paid for the new library.","exampleCN":"一位匿名捐助人出资建了新图书馆。"},{"word":"benefaction","structure":"bene + fact + -ion (act noun)","meaning":"the act of doing good or giving help","meaningCN":"善行；捐助行为（-ion 表示行为）","example":"The museum thanked the family for its benefaction.","exampleCN":"博物馆感谢这家人的捐助。"},{"word":"beneficence","structure":"bene + fic + -ence (state noun)","meaning":"the quality of being kind and doing good","meaningCN":"仁慈；行善（-ence 表示状态或性质）","example":"The doctor's beneficence was remembered by the village.","exampleCN":"村里人记得这位医生的仁慈。"},{"word":"beneficent","structure":"bene + fic + -ent (adjective)","meaning":"kind and doing good","meaningCN":"仁慈的；行善的（-ent 构成形容词）","example":"A beneficent fund supported the students.","exampleCN":"一项慈善基金资助了这些学生。"}],"latinEntries":[{"word":"benefactum","structure":"bene (well) + factum (deed)","meaning":"a good deed","meaningCN":"善行；好事"},{"word":"beneficium","structure":"bene (well) + ficium (doing)","meaning":"a kindness, favour, benefit","meaningCN":"恩惠；善举；好处"},{"word":"facere","structure":"Latin verb","meaning":"to do, make","meaningCN":"做；制造"}]}},{"word":"bias","ipa_uk":"/ˈbaɪəs/","ipa_us":"/ˈbaɪəs/","definition_zh":"偏见；偏向；偏差；使有偏见","definition_en":"an unfair preference or a systematic slant in judgment, data, or design, or to influence something unfairly","core_image":"保龄球被做偏的一侧：球滚着滚着自己拐向一边","scene":"The study was criticized for a bias that favoured the sponsor's product.","sceneCN":"这里 bias 是「研究中的系统性偏差」（第 2 个义项：数据或方法偏向一方）；句意：这项研究因偏向赞助商产品而受到批评。场景要点：研究报告、赞助商标志、一边倒的数据图表。","pos":[{"tag":"n.","zh":"偏见；偏向；偏差；斜线"},{"tag":"vt.","zh":"使有偏见；使偏向"}],"collocations":[{"phrase":"a bias against","zh":"对……的偏见"},{"phrase":"a bias towards","zh":"对……的偏向"},{"phrase":"confirmation bias","zh":"确认偏误"},{"phrase":"unconscious bias","zh":"无意识偏见"},{"phrase":"on the bias","zh":"斜着；沿斜纹方向（裁剪用语）"}],"forms":[{"label":"复数（名词）","form":"biases"},{"label":"三单（he/she/it）","form":"biases"},{"label":"过去式（已经发生）","form":"biased"},{"label":"过去分词（完成／被动）","form":"biased"},{"label":"现在分词（进行体）","form":"biasing（英式亦作 biassing）"}],"derivatives":[{"word":"biased","pos":"adj.","zh":"有偏见的；偏向的"},{"word":"unbiased","pos":"adj.","zh":"无偏见的；公正的"},{"word":"debias","pos":"v.","zh":"消除偏差；去偏"},{"word":"bias-free","pos":"adj.","zh":"无偏差的；无偏见的"}],"senses":[{"no":"01","title":"Prejudice for or against a group","titleCN":"偏见：对某群体先有立场","definition":"an unfair preference or dislike for a person or group based on identity rather than evidence","definitionCN":"基于身份而非证据，对某人或某群体不公平的偏好或厌恶","example":"The hiring panel was accused of gender bias.","exampleCN":"招聘小组被指存在性别偏见。","why":"The original bias was a weight placed off-centre on a bowling ball. The ball therefore curves one way; a mind with bias curves toward one group.","whyCN":"最初的 bias 是保龄球上偏置的配重。球因此向一边拐；有 bias 的心也会向某个群体拐。"},{"no":"02","title":"Systematic distortion in data or research","titleCN":"系统性偏差：数据整体偏了一边","definition":"a systematic error that makes results consistently differ from the truth in one direction","definitionCN":"使结果持续朝一个方向偏离真实情况的系统性误差","example":"The survey suffered from selection bias because it only reached smartphone users.","exampleCN":"这项调查存在选择偏差，因为它只触及智能手机用户。","why":"A bowling ball with an off-centre weight does not make random errors; it curves the same way every time. Statistical bias is that consistent curve.","whyCN":"偏置配重的保龄球不是随机出错，而是每次都朝同一边弯。统计偏差就是这种持续一致的弯曲。"},{"no":"03","title":"A personal leaning or tendency","titleCN":"个人偏向：心里更倾向某一边","definition":"a preference or inclination that shapes how someone thinks or acts","definitionCN":"影响一个人思考或行动方式的偏好或倾向","example":"He has a bias for simple solutions over complicated ones.","exampleCN":"他偏向简单方案，而不是复杂方案。","why":"The curve need not be hostile; any off-centre weight makes the ball drift. In the same way, a mild preference is already a bias.","whyCN":"这种弯曲不必带敌意；只要配重偏离中心，球就会漂。同样，温和的偏好也已经是一种 bias。"},{"no":"04","title":"An oblique line or grain","titleCN":"斜线：布料或裁剪的斜向","definition":"a slanting direction, especially the diagonal grain of woven fabric or a cut made across it","definitionCN":"倾斜的方向，尤指织物的斜纹或横过布纹的裁剪","example":"The dress was cut on the bias so that it would drape softly.","exampleCN":"这条裙子沿斜纹裁剪，因此垂坠柔和。","why":"This is the oldest concrete sense: biais in Old French meant 'slant, oblique'. The line runs across the straight grain.","whyCN":"这是最古老的实体义：古法语 biais 就是“倾斜、斜的”。这条线横过笔直的布纹。"},{"no":"05","title":"To influence unfairly","titleCN":"使有偏见：把判断推向一边","definition":"to cause someone or something to favour one side unfairly","definitionCN":"使某人或某事物不公平地偏向一边","example":"The editor was accused of biasing the report against the opposition.","exampleCN":"编辑被指让报道对反对派产生偏见。","why":"The verb applies the off-centre weight: a force is added to one side, so the result rolls that way.","whyCN":"动词就是加上偏置配重：往一边施力，结果便朝那边滚。"},{"no":"06","title":"Electronics: a steady voltage or current","titleCN":"电子学：偏置电压或电流","definition":"a fixed voltage or current applied to a device to set its operating point","definitionCN":"施加于器件、用来设定其工作点的固定电压或电流","example":"The transistor needs a small bias voltage to conduct.","exampleCN":"晶体管需要一个小偏置电压才能导通。","why":"The electrical sense keeps the geometry: the operating point is pushed away from the centre to one side so the device responds correctly.","whyCN":"电子义保留了这种几何：工作点被从中心推向一边，器件才能正确响应。"},{"no":"07","title":"Cognitive bias","titleCN":"认知偏误：思维自己走捷径","definition":"in psychology, a repeatable pattern in which judgment departs from logic or evidence","definitionCN":"心理学中判断反复偏离逻辑或证据的模式","example":"Confirmation bias makes people notice evidence that supports what they already believe.","exampleCN":"确认偏误使人更容易注意到支持自己既有信念的证据。","why":"The mind's default path is the off-centre weight. It saves effort but curves every judgment in the same direction.","whyCN":"心智的默认路径就是那块偏置配重。它省力，却让每个判断都朝同一方向弯。"},{"no":"08","title":"Algorithmic or AI bias","titleCN":"算法偏见：模型学进了偏差","definition":"a systematic unfairness in a model or system, usually learned from biased data or design choices","definitionCN":"模型或系统中系统性的不公平，通常来自有偏差的数据或设计选择","example":"The chatbot showed bias because its training data underrepresented certain dialects.","exampleCN":"这个聊天机器人表现出偏见，因为训练数据对某些方言代表性不足。","why":"A model repeats the curve it was trained on. If the data leaned one way, the machine leans the same way at scale.","whyCN":"模型会重复它被训练时见到的弯曲。数据偏向一边，机器就会大规模地朝同一边偏。"},{"no":"09","title":"Media bias","titleCN":"媒体偏向：报道框架有倾斜","definition":"a tendency in news reporting to present events from one perspective or to favour one side","definitionCN":"新闻报道倾向于从某一视角呈现事件或偏袒某一方","example":"Readers complained about the paper's political bias.","exampleCN":"读者抱怨这家报纸有政治偏向。","why":"Selection and framing act like an off-centre weight on the whole report: some facts are pushed forward, others are pushed out of view.","whyCN":"选择与框架就像给整篇报道加了偏置配重：有些事实被推向前面，另一些被推出视野。"}],"etymology":{"intro":{"en":"Bias began as a word for a slanting line and became the name of a weighted bowling ball. From that curved roll came the modern senses of prejudice and systematic distortion.","cn":"bias 最初指一条斜线，后来成为偏置保龄球的名称。从那种弯曲的滚动，长出了现代“偏见”和“系统性偏差”的含义。"},"items":[{"era":"1520S","en":"Bias enters English in the 1520s as 'an oblique or diagonal line'. The earliest uses are about cuts, slopes, and geometry.","cn":"bias 在 1520 年代进入英语，意为“斜线、对角线”。最早用法与裁剪、斜面、几何有关。"},{"era":"1560S BOWLING","en":"By the 1560s a bias was also a weight placed on one side of a bowling ball so that it curved as it rolled. The bowl had a bias; the path showed it.","cn":"到 1560 年代，bias 也指保龄球一侧的配重，使球滚动时弯曲。球本身“有 bias”，轨迹把这一点显示出来。"},{"era":"OLD FRENCH biais","en":"The English word comes from Old French biais 'slant, slope, oblique'. French already used it for both a diagonal line and a leaning tendency.","cn":"英语这个词来自古法语 biais“倾斜、斜面、斜的”。法语中它已经既指斜线，也指倾向。"},{"era":"ORIGIN UNCERTAIN","en":"The deeper origin of biais is not settled. One suggestion traces it through Vulgar Latin *(e)bigassius to Greek epikarsios 'athwart, crosswise', from epi- 'upon' + karsios 'oblique'; this is a hypothesis, not an attested chain.","cn":"biais 更深层的来源尚无定论。一种说法认为它经通俗拉丁语 *(e)bigassius 追溯到希腊语 epikarsios“横向的、斜穿过去的”，由 epi-“在上”+ karsios“斜的”构成；这只是假说，不是有文献链的结论。"},{"era":"1570S FIGURATIVE","en":"By the 1570s bias was used for a leaning of the mind. A ball that curves became a judgment that curves; the weight moved from the bowl to the person.","cn":"到 1570 年代，bias 被用于表示心智的倾向。会弯的球变成了会弯的判断；配重从球上移到了人身上。"},{"era":"MODERN ENGLISH","en":"Statistics, psychology, electronics, media studies, and AI all use the same geometry: a system pushed off-centre, so that its output consistently leans one way.","cn":"统计学、心理学、电子学、媒体研究和人工智能都使用同一种几何：系统被推离中心，于是输出持续偏向一边。"}]},"similar":{"note":{"en":"The first group is built on the same bias; the second collects words for unfair leaning, each naming a different kind of tilt.","cn":"第一组建立在同一个 bias 上；第二组收“不公平倾向”的词，各自命名不同类型的倾斜。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"biased","ipa":"/ˈbaɪəst/","tag":"derived adjective","definition":"showing an unfair preference. It is the past participle of bias used as an adjective.","definitionCN":"表现出不公平偏好的。它是 bias 的过去分词转作形容词。"},{"word":"unbiased","ipa":"/ʌnˈbaɪəst/","tag":"negative form","definition":"fair and without preference. Un- 'not' + biased removes the off-centre weight.","definitionCN":"公正、无偏好的。un-“不”+ biased，去掉偏置配重。"},{"word":"biases","ipa":"/ˈbaɪəsɪz/","tag":"inflected form","definition":"plural of bias, or the third-person singular of the verb. It is not a different root.","definitionCN":"bias 的复数，或动词第三人称单数。它不是另一个词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"prejudice","ipa":"/ˈpredʒədɪs/","tag":"pre-judgment of people","definition":"an opinion formed before knowing the facts, especially about a group. It is usually social and emotional; bias can be statistical and neutral in tone.","definitionCN":"在了解事实之前形成的看法，尤指对某群体。它通常带社会性和情绪性；bias 可以是统计性的、语气中性的。"},{"word":"partiality","ipa":"/ˌpɑːʃiˈæləti/","tag":"favouritism","definition":"unfair support for one person or side. It stresses favouring a particular party rather than a distorted system.","definitionCN":"对某人或某一方的不公平支持。它强调偏袒特定一方，而不是系统被扭曲。"},{"word":"slant","ipa":"/slɑːnt/","tag":"angled presentation","definition":"a particular point of view imposed on information, or a sloping direction. Slant is often used for media framing.","definitionCN":"强加于信息的特定视角，或倾斜方向。slant 常用于媒体框架。"},{"word":"tendency","ipa":"/ˈtendənsi/","tag":"general inclination","definition":"a general inclination to behave in a certain way. It is broader and can be neutral, while bias implies unfairness in most modern uses.","definitionCN":"以某种方式行事的一般倾向。它更宽泛，可以中性；bias 在现代用法中多含不公平意味。"}]}]},"mnemonics":{"normalIntro":{"en":"Real image and relatives: a bowling ball with an off-centre weight, the adjective biased, and the modern debias.","cn":"只用真实意象与同族词：一侧加配重的保龄球、形容词 biased，以及现代词 debias。"},"normal":[{"en":"A bowling ball with a weight on one side curves as it rolls. That curve is the original bias.","cn":"一侧加配重的保龄球滚起来会弯。那道弯曲就是最初的 bias。"},{"en":"Biased is the adjective: a biased report has a weight on one side of its scale.","cn":"biased 是形容词：a biased report 的天平一侧被加了重量。"},{"en":"Unbiased removes the weight, so the result can roll straight.","cn":"unbiased 去掉了那块配重，结果才能直着滚。"},{"en":"To debias a model is to find and remove the off-centre weight in its training data.","cn":"debias 一个模型，就是找出并移除训练数据里的偏置配重。"},{"en":"On the bias means diagonally across the grain of cloth, the oldest concrete sense.","cn":"on the bias 指沿斜纹横过布纹，这是最古老的实体义。"}],"abstract":[{"en":"Bias is not the same as being wrong. It is a consistent direction of error, like a ball that always curves left.","cn":"bias 不等于“错了”，而是一种持续一致的错误方向，像永远向左弯的球。"},{"en":"The weight can sit in a person, a dataset, a question, a newsroom, or a circuit. The geometry is identical.","cn":"配重可以放在一个人、一份数据、一道问题、一间新闻编辑室或一个电路里。几何关系完全相同。"},{"en":"Removing bias is not the same as having no perspective; it means no hidden weight is steering the result without being declared.","cn":"消除 bias 不等于没有视角；它意味着没有隐藏的配重在不声明的情况下操纵结果。"}]},"examples":[{"en":"The judge was asked to step aside because of a perceived bias.","cn":"由于被认为存在偏见，法官被要求回避。"},{"en":"The test was redesigned to remove cultural bias.","cn":"这项测试被重新设计，以消除文化偏差。"},{"en":"Social media algorithms can amplify political bias.","cn":"社交媒体算法会放大政治偏向。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“拜厄斯”——拜厄斯看人总先挑一边站，像偏心的保龄球 → bias 偏见、偏向","word":"bias"},"root":"源自古法语 biais“倾斜、斜面”；最初指斜线，16 世纪又指保龄球一侧的配重，球因此弯曲滚动，核心是“偏离中心、持续倒向一边”。更深词源不确定。","sensesIntro":{"en":"Nine senses of bias, all built on one geometry: a weight placed off-centre, making the path curve consistently toward one side.","cn":"bias 的九个义项都建立在同一种几何上：配重偏离中心，使路径持续朝一边弯曲。"},"semanticMap":{"core":{"en":"CORE IMAGE: an off-centre weight that makes a ball, a judgment, or a system lean one way.","cn":"核心意象：偏离中心的配重，让球、判断或系统倒向一边。"},"chain":["OFF-CENTRE WEIGHT","PATH CURVES","CONSISTENT DIRECTION","PREFERENCE FOR ONE SIDE","UNFAIR JUDGMENT","SYSTEMATIC DISTORTION"],"branches":[{"senses":"S1 · S3 · S9","en":"SOCIAL AND MEDIA LEANING: prejudice toward a group, a personal preference, a newsroom's framing.","cn":"社会与媒体倾向：对群体的偏见、个人偏好、新闻编辑室的框架。"},{"senses":"S2 · S7 · S8","en":"SYSTEMATIC ERROR: selection bias, cognitive shortcuts, and learned algorithmic unfairness.","cn":"系统性误差：选择偏差、认知捷径，以及算法学到的系统性不公。"},{"senses":"S4","en":"GEOMETRY: the original slant of a line or the diagonal grain of cloth.","cn":"几何：最初的斜线，或布料的斜纹。"},{"senses":"S5","en":"THE VERB: to add the off-centre weight and push a result toward one side.","cn":"动词：加上偏置配重，把结果推向一边。"},{"senses":"S6","en":"ELECTRONICS: a fixed voltage that sets an operating point away from centre.","cn":"电子学：把工作点设定在偏离中心的固定电压。"}]},"affixes":{"intro":{"en":"Bias is a borrowed French noun. English adds -ed, un-, -es, and -ing; modern technical English coins de- and -free compounds.","cn":"bias 是借入的法语名词。英语加 -ed、un-、-es、-ing；现代技术英语又造出 de- 和 -free 复合词。"},"latinIntro":{"en":"There is no reliable classical Latin word for bias. The suggested Vulgar Latin *(e)bigassius, linked to Greek epikarsios, is a hypothesis, so latinEntries is left empty rather than presenting a speculative root as fact.","cn":"bias 没有可靠的古典拉丁语来源。所谓的通俗拉丁语 *(e)bigassius（与希腊语 epikarsios 相联系）只是假说，因此 latinEntries 留空，不把推测词根当作事实。"},"items":[{"word":"biases","structure":"bias + -es (plural / third person)","meaning":"more than one bias, or 'it biases'","meaningCN":"多种偏见；或动词第三人称单数","example":"The report identifies several hidden biases.","exampleCN":"报告指出了几处隐藏的偏见。"},{"word":"biased","structure":"bias + -ed (past participle / adjective)","meaning":"influenced unfairly; showing a preference","meaningCN":"有偏见的；偏向的（-ed 构成分词或形容词）","example":"The sample was biased toward younger voters.","exampleCN":"样本偏向年轻选民。"},{"word":"unbiased","structure":"un- (not) + biased","meaning":"fair and without a leaning","meaningCN":"无偏见的；公正的（un- 表示否定）","example":"We need an unbiased review of the evidence.","exampleCN":"我们需要对证据进行公正的审查。"},{"word":"biasing","structure":"bias + -ing (participle)","meaning":"influencing something toward one side","meaningCN":"使产生偏向；正在加偏置（-ing 构成分词）","example":"The wording of the question was biasing the answers.","exampleCN":"问题的措辞正在使答案产生偏向。"},{"word":"biassing","structure":"bias + -ing (British spelling variant)","meaning":"the same as biasing, with doubled s","meaningCN":"与 biasing 同义，英式拼写双写 s","example":"British journals often print biassing.","exampleCN":"英国期刊常印作 biassing。"},{"word":"debias","structure":"de- (remove) + bias","meaning":"to remove a known bias from data or a process","meaningCN":"去偏；从数据或流程中消除偏差（de- 表示去除）","example":"The team tried to debias the training set.","exampleCN":"团队试图去除训练集的偏差。"},{"word":"debiasing","structure":"de- + bias + -ing","meaning":"the process of removing bias","meaningCN":"去偏过程；消除偏差","example":"Debiasing is easier when the source of the skew is known.","exampleCN":"当偏差来源已知时，去偏会更容易。"},{"word":"bias-free","structure":"bias + free (without)","meaning":"designed or tested to contain no bias","meaningCN":"无偏差的；无偏见的（free 表示“没有”）","example":"The company promised a bias-free hiring process.","exampleCN":"公司承诺采用无偏见的招聘流程。"},{"word":"overbias","structure":"over- (too much) + bias","meaning":"to apply excessive bias in electronics or modelling","meaningCN":"过偏；施加过大的偏置（over- 表示“过度”，技术用语）","example":"The amplifier was overbiased and overheated.","exampleCN":"放大器偏置过大，导致过热。"}],"latinEntries":[]}},{"word":"biological","ipa_uk":"/ˌbaɪəˈlɒdʒɪkl/","ipa_us":"/ˌbaɪəˈlɑːdʒɪkl/","definition_zh":"生物的；生物学的；有血缘关系的","definition_en":"relating to living organisms or to the science of biology, or connected by blood rather than adoption","core_image":"一株从细胞长出的生命树","scene":"The child was raised by adoptive parents but later met her biological mother.","sceneCN":"这里 biological 是「有血缘关系的」（第 3 个义项：生物学意义上的亲生关系）；句意：孩子由养父母抚养长大，后来见到了亲生母亲。场景要点：母女相认、两份家庭照片、血缘与抚养的对照。","pos":[{"tag":"adj.","zh":"生物的；生物学的；有血缘关系的"}],"collocations":[{"phrase":"biological parent","zh":"亲生父母"},{"phrase":"biological clock","zh":"生物钟"},{"phrase":"biological diversity","zh":"生物多样性"},{"phrase":"biological warfare","zh":"生物战"},{"phrase":"biological science","zh":"生物科学"}],"forms":[{"label":"比较级（更多用 more 构成）","form":"more biological"},{"label":"最高级（更多用 most 构成）","form":"most biological"}],"derivatives":[{"word":"biology","pos":"n.","zh":"生物学"},{"word":"biologist","pos":"n.","zh":"生物学家"},{"word":"biologically","pos":"adv.","zh":"生物学上；从生物学角度"},{"word":"biologics","pos":"n.","zh":"生物制剂（复数，医药用语）"}],"senses":[{"no":"01","title":"Relating to living organisms","titleCN":"与生物有关的：属于生命体","definition":"concerning living things and the processes that keep them alive","definitionCN":"涉及生命体以及维持其生存的过程","example":"The reef supports enormous biological richness.","exampleCN":"这片珊瑚礁养育着极其丰富的生物资源。","why":"Biological is built on Greek bios 'life'. Its widest sense simply marks anything that belongs to living matter rather than to machines or minerals.","whyCN":"biological 建立在希腊语 bios“生命”上。它最宽的义项只是标记某物属于生命物质，而不是机器或矿物。"},{"no":"02","title":"Relating to the science of biology","titleCN":"生物学的：属于这门学科","definition":"concerning the academic study of living things","definitionCN":"涉及对生命体的学术研究","example":"The paper was published in a biological journal.","exampleCN":"这篇论文发表在一份生物学杂志上。","why":"Once biology became the name of a science, its adjective marked whatever belonged to that discipline: journals, methods, theories.","whyCN":"当 biology 成为一门学科的名称后，它的形容词就标记属于该学科的一切：期刊、方法、理论。"},{"no":"03","title":"Related by blood","titleCN":"血缘的：生物学意义上的亲属","definition":"genetically related, as opposed to related by adoption or marriage","definitionCN":"有基因联系的，相对于收养或婚姻关系而言","example":"She traced her biological father through a DNA test.","exampleCN":"她通过 DNA 检测找到了亲生父亲。","why":"Modern medicine separates social kinship from genetic kinship. Biological marks the kinship carried in the body rather than created by law or care.","whyCN":"现代医学把社会亲属关系与基因亲属关系分开。biological 标记的是身体里携带的亲属关系，而不是法律或抚养建立的。"},{"no":"04","title":"Innate or rooted in body chemistry","titleCN":"本能的：写在身体里的","definition":"arising from the body's natural processes rather than from learning or choice","definitionCN":"来自身体自然过程，而非学习或选择","example":"Humans have a biological drive to sleep.","exampleCN":"人类有睡眠的生物驱动力。","why":"If a behaviour comes from the organism's own machinery, it is biological rather than cultural. The word points down to the body as the cause.","whyCN":"如果一种行为来自生命体自身的机制，它就是 biological 而非文化的。这个词把原因指向身体。"},{"no":"05","title":"Using living organisms","titleCN":"利用生物的：以活体为工具","definition":"describing a method that uses living organisms to do work, such as pest control or waste treatment","definitionCN":"描述利用活体完成工作的方式，如害虫防治或废物处理","example":"Biological control reduced the aphid population without pesticides.","exampleCN":"生物防治在不使用农药的情况下减少了蚜虫数量。","why":"The adjective marks the means, not just the subject: the agent doing the work is itself alive.","whyCN":"这个形容词标记的是手段而不只是主题：执行工作的主体本身就是活的。"},{"no":"06","title":"Describing biological weapons","titleCN":"生物武器的：用病原体作战","definition":"relating to weapons or warfare that use pathogens or toxins to harm people, animals, or plants","definitionCN":"涉及使用病原体或毒素伤害人、动物或植物的武器或战争","example":"The treaty bans the development of biological weapons.","exampleCN":"该条约禁止开发生物武器。","why":"The life sciences are turned toward destruction. Biological here names the material used as a weapon: living pathogens.","whyCN":"生命科学被转向破坏。这里 biological 命名的是被当作武器的材料：活的病原体。"},{"no":"07","title":"Biological clock or rhythm","titleCN":"生物钟：体内的周期节律","definition":"describing the internal timing system that regulates daily or seasonal rhythms","definitionCN":"描述调节昼夜或季节节律的体内计时系统","example":"Night shifts disrupted his biological clock.","exampleCN":"夜班打乱了他的生物钟。","why":"A clock is a mechanism that keeps time. The body has one built from biological processes, so the metaphor takes the adjective literally.","whyCN":"钟是计时的机制。身体有一套由生物过程构成的钟，因此这个比喻其实把形容词用得很字面。"},{"no":"08","title":"Biological sample or specimen","titleCN":"生物样本：用于研究的活体材料","definition":"describing material taken from a living organism for scientific testing","definitionCN":"描述从生命体取出、用于科学检测的材料","example":"The lab stores biological samples at very low temperatures.","exampleCN":"实验室在极低温度下保存生物样本。","why":"Research needs material that still carries the marks of life. Biological marks the origin of the sample in an organism.","whyCN":"研究需要仍带有生命痕迹的材料。biological 标记样本来源于生命体。"}],"etymology":{"intro":{"en":"Biological is the adjective of biology, a word coined at the beginning of the 19th century from two Greek elements. Its history shows a new science naming itself and then lending its adjective to blood relation, weapons, clocks, and samples.","cn":"biological 是 biology 的形容词，而 biology 是 19 世纪初用两个希腊成分新造的词。它的历史显示：一门新科学先给自己命名，再把形容词借给血缘、武器、生物钟和样本。"},"items":[{"era":"AROUND 1800","en":"Biology was coined independently around 1802 by the French naturalist Lamarck and the German naturalist Treviranus. The adjective biological followed as the science acquired a name.","cn":"biology 约在 1802 年由法国博物学家拉马克和德国博物学家特雷维拉努斯分别提出。随着这门科学有了名字，形容词 biological 也随后出现。"},{"era":"GREEK bios","en":"Bios meant 'life, course of life'. It is generally traced to a PIE root meaning 'to live', though the deeper reconstruction is not directly attested.","cn":"bios 意为“生命、生命历程”。它一般被追溯到表示“活着”的原始印欧语词根，但更深层的重构缺乏直接文献证据。"},{"era":"GREEK -logia","en":"-logia meant 'the study of', from logos 'word, reason, account'. Biology is literally 'the account of life'.","cn":"-logia 意为“对……的研究”，来自 logos“言说、理性、论述”。biology 字面就是“关于生命的论述”。"},{"era":"NEW LATIN biologia","en":"The compound was formed in scientific Latin as biologia before passing into French, German, and English. The elements are Greek, but the coinage is modern.","cn":"这个复合词先在科学拉丁语中形成 biologia，再传入法语、德语和英语。成分是希腊语，但造词本身是现代的。"},{"era":"19C.–20C. EXPANSION","en":"Biological first meant 'of the science of life'. It then widened to 'of living things in general', and in the 20th century acquired the sense 'related by blood'.","cn":"biological 最初意为“生命科学的”。随后扩展到“一般生命体的”，并在 20 世纪获得“有血缘关系的”这一义项。"},{"era":"RELATED FAMILY","en":"Biography, biosphere, biodiversity, and antibiotic all use bios 'life'. Symbiosis uses bios twice: 'living together'. Biology and biological share the same root but differ in part of speech.","cn":"biography、biosphere、biodiversity、antibiotic 都使用 bios“生命”。symbiosis 用了两次 bios：“共同生活”。biology 与 biological 同根，只是词性不同。"}]},"similar":{"note":{"en":"The first group is the biology word family; the second collects adjectives that also describe what is alive, built-in, or inherited.","cn":"第一组是 biology 词族；第二组收同样描述“活的、内置的、遗传的”的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"biology","ipa":"/baɪˈɒlədʒi/","tag":"base noun","definition":"the science of living things. Biological is its adjective.","definitionCN":"研究生命体的科学。biological 是它的形容词。"},{"word":"biologist","ipa":"/baɪˈɒlədʒɪst/","tag":"person noun","definition":"a scientist who studies living things. The -ist suffix marks the person.","definitionCN":"研究生命体的科学家。-ist 后缀标记从事者。"},{"word":"biologically","ipa":"/ˌbaɪəˈlɒdʒɪkli/","tag":"derived adverb","definition":"in biological terms; from the point of view of biology. It is the adverb of biological.","definitionCN":"从生物学角度；在生物学上。它是 biological 的副词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"organic","ipa":"/ɔːˈɡænɪk/","tag":"living matter","definition":"relating to carbon-based living matter, or grown without chemicals. It overlaps with biological when describing material, but not when describing blood relation.","definitionCN":"与碳基生命物质有关的，或不用化学品培育的。描述物质时与 biological 重叠，但描述血缘时不重叠。"},{"word":"living","ipa":"/ˈlɪvɪŋ/","tag":"currently alive","definition":"not dead; currently alive. Living is a plain state word, while biological names the scientific frame.","definitionCN":"未死的；活着的。living 是朴素的状态词，biological 则点明科学框架。"},{"word":"innate","ipa":"/ɪˈneɪt/","tag":"inborn","definition":"present from birth rather than learned. It overlaps with biological in the sense 'built into the body'.","definitionCN":"出生即有的，而非习得的。它与 biological 的“写进身体里”这一义项重叠。"},{"word":"genetic","ipa":"/dʒəˈnetɪk/","tag":"inherited through genes","definition":"relating to genes or heredity. It is narrower than biological: all genetic relations are biological, but not all biological facts are genetic.","definitionCN":"与基因或遗传有关的。它比 biological 更窄：所有遗传关系都是生物性的，但并非所有生物事实都是遗传的。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: bios 'life', -logia 'study', -ical 'relating to', and the pair biology/biologist.","cn":"只用真实成分与同族词：bios“生命”、-logia“研究”、-ical“与……有关”，以及 biology/biologist 这对词。"},"normal":[{"en":"Bios means 'life' and -logia means 'study': biology is the study of life, and biological means 'relating to it'.","cn":"bios 是“生命”，-logia 是“研究”：biology 是研究生命，biological 是“与之相关的”。"},{"en":"The adjective adds -ical to biology, just as historic adds -al to history.","cn":"这个形容词是 biology 加 -ical，就像 historic 是 history 加 -al。"},{"en":"Biological parent marks the parent connected by genes, while adoptive parent marks the parent connected by care and law.","cn":"biological parent 是由基因连接的父母，adoptive parent 是由抚养与法律连接的父母。"},{"en":"A biological clock is literally a clock made of biological processes, not a machine.","cn":"biological clock 字面上是由生物过程构成的钟，而不是机器。"},{"en":"Biological warfare uses living pathogens as weapons; the adjective names the material, not the science.","cn":"biological warfare 把活的病原体当武器；形容词命名的是材料，而不是学科。"}],"abstract":[{"en":"The word draws a line between what is given by the body and what is made by culture, law, or learning.","cn":"这个词划出一条线：一边是身体给定的，一边是文化、法律或学习造就的。"},{"en":"Biology is a modern science, but its adjective now reaches far beyond the laboratory — into family, instincts, and weapons.","cn":"biology 是一门现代科学，但它的形容词早已越出实验室——进入家庭、本能和武器。"},{"en":"Whenever biological is used, something is being explained by referring down to the organism rather than up to society.","cn":"每当使用 biological，都是在把解释指向下面的生命体，而不是上面的社会。"}]},"examples":[{"en":"The lake's biological health improved after the clean-up.","cn":"清理之后，湖泊的生物健康状况改善了。"},{"en":"Some behaviours are biological, but they are still shaped by culture.","cn":"有些行为是生物性的，但仍受文化塑造。"},{"en":"The laboratory handles biological material under strict safety rules.","cn":"实验室在严格的安全规则下处理生物材料。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“拜欧逻辑扣”——拜欧用逻辑扣住生命（bio）的每个细节 → biological 生物的、生物学的","word":"biological"},"root":"由 biology 加 -ical 构成；biology 由希腊语 bios“生命”+ -logia“研究”组成，核心是“与生命或生命科学有关”。","sensesIntro":{"en":"Eight senses of biological, all radiating from bios 'life': the science of life, living matter, blood relation, inborn drives, living tools, pathogens as weapons, internal clocks, and laboratory samples.","cn":"biological 的八个义项都从 bios“生命”辐射出来：生命科学、生命物质、血缘、先天驱力、活体工具、病原体武器、体内时钟和实验室样本。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tree of life growing out of a single cell, with one adjective naming everything connected to it.","cn":"核心意象：从单个细胞长出的生命树，一个形容词命名与它相连的一切。"},"chain":["BIOS = LIFE","STUDY OF LIFE","LIVING MATTER","BODY-BASED CAUSE","BLOOD CONNECTION","LIFE USED AS TOOL OR WEAPON"],"branches":[{"senses":"S1 · S2","en":"LIFE AND THE SCIENCE: living organisms in general, and the academic discipline that studies them.","cn":"生命与科学：一般生命体，以及研究它们的学科。"},{"senses":"S3","en":"KINSHIP: relation carried in genes rather than created by adoption.","cn":"亲属：由基因携带、而非收养建立的关系。"},{"senses":"S4 · S7","en":"BODY MACHINERY: innate drives and the internal clock that times them.","cn":"身体机制：先天驱力，以及为其计时的体内时钟。"},{"senses":"S5 · S8","en":"LIFE AS MATERIAL: organisms used to do work, and samples taken for research.","cn":"作为材料的生命：被用来工作的生物，以及用于研究的样本。"},{"senses":"S6","en":"LIFE AS WEAPON: pathogens and toxins directed at people, animals, or crops.","cn":"作为武器的生命：指向人、动物或作物的病原体与毒素。"}]},"affixes":{"intro":{"en":"Biological is biology + -ical. The productive pattern is bio- 'life' plus a stem, then -logy, -logist, -logical, or -ically.","cn":"biological 是 biology + -ical。能产的模式是 bio-“生命”加词干，再加 -logy、-logist、-logical 或 -ically。"},"latinIntro":{"en":"The elements are Greek, but the compound was coined in New Latin as biologia. Latin and Greek bios is the shared source of the whole family.","cn":"这些成分是希腊语，但复合词是在新拉丁语中造出的 biologia。拉丁语与希腊语的 bios 是整个词族的共同来源。"},"items":[{"word":"biology","structure":"bio- (life) + -logy (study)","meaning":"the science of living things","meaningCN":"生物学（-logy 表示学科）","example":"She studied biology at university.","exampleCN":"她在大学学习生物学。"},{"word":"biologist","structure":"bio- + -logist (person who studies)","meaning":"a scientist who studies living things","meaningCN":"生物学家（-logist 表示研究者）","example":"The biologist tagged the birds for tracking.","exampleCN":"生物学家给鸟戴上标签以便追踪。"},{"word":"biologically","structure":"biological + -ly (adverb)","meaning":"from a biological point of view","meaningCN":"生物学上；从生物学角度","example":"Biologically, the two species are closely related.","exampleCN":"从生物学上看，这两个物种关系很近。"},{"word":"biologic","structure":"bio- + -logic (adjective / noun)","meaning":"biological; also a drug made from living material","meaningCN":"生物的；也可作名词指生物制剂","example":"The patient responded well to the biologic.","exampleCN":"患者对这种生物制剂反应良好。"},{"word":"biologics","structure":"biologic + -s (plural noun)","meaning":"medicines produced from living cells","meaningCN":"生物制剂（复数，医药用语）","example":"Biologics are often more expensive than small-molecule drugs.","exampleCN":"生物制剂通常比小分子药物更贵。"},{"word":"biomedicine","structure":"bio- + medicine","meaning":"medicine based on biology and physiology","meaningCN":"生物医学（bio- 表示生命）","example":"The institute focuses on biomedicine.","exampleCN":"该研究所专注于生物医学。"},{"word":"biodiversity","structure":"bio- + diversity","meaning":"the variety of living things in a place","meaningCN":"生物多样性","example":"The forest is a hotspot of biodiversity.","exampleCN":"这片森林是生物多样性热点地区。"},{"word":"biosphere","structure":"bio- + sphere","meaning":"the zone of the earth where life exists","meaningCN":"生物圈（生命存在的地球区域）","example":"Carbon moves through the biosphere.","exampleCN":"碳在生物圈中循环。"},{"word":"microbiology","structure":"micro- (small) + biology","meaning":"the study of microscopic organisms","meaningCN":"微生物学（micro- 表示“微小”）","example":"Microbiology explains how the infection spreads.","exampleCN":"微生物学解释了感染如何传播。"},{"word":"antibiotic","structure":"anti- (against) + bio- (life) + -tic","meaning":"a substance that kills or stops bacteria","meaningCN":"抗生素（anti- 表示“对抗”，bio- 表示“生命”）","example":"The doctor prescribed an antibiotic.","exampleCN":"医生开了抗生素。"}],"latinEntries":[{"word":"biologia","structure":"New Latin: Greek bios (life) + -logia (study)","meaning":"the study of life; biology","meaningCN":"生物学（新拉丁语造词，成分来自希腊语）"}]}},{"word":"biology","ipa_uk":"/baɪˈɒlədʒi/","ipa_us":"/baɪˈɑːlədʒi/","definition_zh":"生物学；生物；生命机理","definition_en":"the scientific study of living things, the organisms of a place, or the bodily mechanisms of an organism","core_image":"显微镜下的细胞与整片生态圈同框","scene":"Marine biology explains how coral reefs survive in nutrient-poor water.","sceneCN":"这里 biology 是「生物学这门学科的一个分支」（第 1 个义项：研究生命的科学）；句意：海洋生物学解释了珊瑚礁如何在贫营养水域存活。场景要点：珊瑚礁、显微镜视野、研究者的记录板。","pos":[{"tag":"n.","zh":"生物学；生物；生命机理"}],"collocations":[{"phrase":"molecular biology","zh":"分子生物学"},{"phrase":"marine biology","zh":"海洋生物学"},{"phrase":"cell biology","zh":"细胞生物学"},{"phrase":"the biology of a species","zh":"某物种的生物学特性"},{"phrase":"a degree in biology","zh":"生物学学位"}],"forms":[{"label":"复数（名词，较少用）","form":"biologies"}],"derivatives":[{"word":"biologist","pos":"n.","zh":"生物学家"},{"word":"biological","pos":"adj.","zh":"生物的；生物学的"},{"word":"biologically","pos":"adv.","zh":"生物学上"},{"word":"biologism","pos":"n.","zh":"生物决定论（较少用）"}],"senses":[{"no":"01","title":"The science of living things","titleCN":"生物学：研究生命的学科","definition":"the branch of science that studies living organisms, their structure, growth, and interactions","definitionCN":"研究生命体的结构、生长与相互作用的科学分支","example":"Biology has transformed our understanding of inheritance.","exampleCN":"生物学改变了我们对遗传的理解。","why":"Biology is literally 'the account of life': bios 'life' + -logia 'study'. The first sense is the discipline that gives that account.","whyCN":"biology 字面是“关于生命的论述”：bios“生命”+ -logia“研究”。第一个义项就是做这种论述的学科。"},{"no":"02","title":"A school or university subject","titleCN":"生物课：作为教学科目","definition":"the subject taught in schools and universities about living things","definitionCN":"中小学和大学里教授生命知识的科目","example":"Biology is compulsory in the first year of the programme.","exampleCN":"生物学是该课程第一年的必修课。","why":"A discipline becomes a subject when it is organized for teaching. The same word names the course rather than the whole field.","whyCN":"一门学科被组织成教学单元时就成了科目。同一个词这时指课程，而不是整个领域。"},{"no":"03","title":"The living organisms of a place","titleCN":"某地的生物：一个区域的生命集合","definition":"the plants, animals, and microbes living in a particular habitat","definitionCN":"生活在特定栖息地的植物、动物和微生物","example":"The biology of the lake changed after the dam was built.","exampleCN":"大坝建成后，湖里的生物构成发生了变化。","why":"Instead of the study, biology can mean what is studied: the whole living population of a place.","whyCN":"biology 可以不是“研究”，而是“被研究的对象”：一个地方的全部生命群体。"},{"no":"04","title":"The bodily workings of an organism","titleCN":"生命机理：身体如何运转","definition":"the physiological processes and mechanisms of a living thing","definitionCN":"生命体的生理过程与机制","example":"The biology of ageing involves many interacting systems.","exampleCN":"衰老的生物学涉及许多相互作用的系统。","why":"This sense looks inside one organism: not the science, not the population, but the machinery that keeps it alive.","whyCN":"这个义项看进一个生命体内部：不是学科，也不是种群，而是维持它活着的机制。"},{"no":"05","title":"The biology of a disease or condition","titleCN":"疾病机理：病症背后的生命过程","definition":"the biological mechanisms that explain why a disease or condition occurs","definitionCN":"解释疾病或状况为何发生的生物机制","example":"Researchers are studying the biology of the virus.","exampleCN":"研究人员正在研究这种病毒的生物学机制。","why":"A disease has its own internal life process. Calling it the biology of the disease means explaining it through cells and molecules.","whyCN":"疾病有自己的内部生命过程。称之为 the biology of the disease，就是用细胞和分子来解释它。"},{"no":"06","title":"Molecular biology","titleCN":"分子生物学：在分子层面研究生命","definition":"the branch of biology that studies the molecules and mechanisms inside cells","definitionCN":"研究细胞内部分子与机制的生物学分支","example":"Molecular biology made gene editing possible.","exampleCN":"分子生物学使基因编辑成为可能。","why":"A subfield adds its level of analysis to the word: molecular biology studies life at the molecular scale.","whyCN":"分支学科在词前加上分析层级：分子生物学在分子尺度研究生命。"},{"no":"07","title":"Evolutionary biology","titleCN":"进化生物学：研究生命如何变化","definition":"the branch of biology that studies how species change over time","definitionCN":"研究物种如何随时间变化的生物学分支","example":"Evolutionary biology explains why some traits spread.","exampleCN":"进化生物学解释为什么某些特征会扩散。","why":"Here the added word names the dimension of change. The living world is studied through its history.","whyCN":"这里加在前面的词命名“变化”这一维度：通过历史来研究生命世界。"},{"no":"08","title":"A biological explanation of behaviour","titleCN":"行为生物学：用生命机制解释行为","definition":"the biological basis of a behaviour or social phenomenon","definitionCN":"某种行为或社会现象的生物学基础","example":"The biology of cooperation is studied in ants and bees.","exampleCN":"合作行为的生物学在蚂蚁和蜜蜂中被研究。","why":"When behaviour is explained by genes, hormones, and neurons, the word biology marks the explanatory level rather than a school subject.","whyCN":"当行为用基因、激素和神经元来解释时，biology 标记的是解释层级，而不是学校科目。"}],"etymology":{"intro":{"en":"Biology is a modern coinage with Greek parts: bios 'life' and -logia 'study'. It was named around 1802, at the moment when the life sciences began to organize themselves as one discipline.","cn":"biology 是用希腊成分构成的现代新词：bios“生命”+ -logia“研究”。它约在 1802 年被命名，正值生命科学开始整合为一门学科。"},"items":[{"era":"AROUND 1802","en":"The French form biologie was used by Lamarck, and the German Biologie by Treviranus, almost at the same time. English biology followed soon after.","cn":"拉马克使用法语 biologie，特雷维拉努斯使用德语 Biologie，时间几乎相同。英语 biology 随后出现。"},{"era":"GREEK bios","en":"Bios meant 'life, manner of living'. The word was already used in Greek compounds such as biography, 'life writing'.","cn":"bios 意为“生命、生活方式”。这个词早已用于希腊语复合词，如 biography“书写生命”。"},{"era":"GREEK -logia","en":"-logia meant 'study, account, discourse', from logos. Biology therefore means 'the account of life', not simply 'life knowledge'.","cn":"-logia 意为“研究、论述、言说”，来自 logos。因此 biology 是“关于生命的论述”，而不只是“生命知识”。"},{"era":"SCIENCE REFORMS THE WORD","en":"In the early 19th century the life sciences were split among natural history, physiology, and medicine. The new word was meant to unify them under one study of life.","cn":"19 世纪初，生命科学分散在博物学、生理学和医学中。这个新词意在把它们统一到一门“生命研究”之下。"},{"era":"SEMANTIC EXPANSION","en":"Biology moved from the discipline to the subject taught, then to the organisms of a place, then to the internal mechanisms of a single organism.","cn":"biology 从学科义扩展到教学科目义，再扩展到某地的生物集合义，又扩展到单个生命体的内部机制义。"},{"era":"RELATED FAMILY","en":"Biography, biosphere, biodiversity, antibiotic, and symbiosis all contain bios. Biology and biological are the noun/adjective pair of the same root; biologist adds -ist for the person.","cn":"biography、biosphere、biodiversity、antibiotic、symbiosis 都含有 bios。biology 与 biological 是同根的名词/形容词对；biologist 再加 -ist 表示人。"}]},"similar":{"note":{"en":"The first group shares the bios family; the second collects neighbouring life sciences and words for 'life knowledge'.","cn":"第一组共享 bios 词族；第二组收邻近的生命科学和“生命知识”类词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"biography","ipa":"/baɪˈɒɡrəfi/","tag":"same bios, different second element","definition":"the written life of a person. It uses bios 'life' + graphein 'write', not -logia 'study'.","definitionCN":"一个人一生的书面记录。它用 bios“生命”+ graphein“书写”，而不是 -logia“研究”。"},{"word":"biologist","ipa":"/baɪˈɒlədʒɪst/","tag":"person noun","definition":"a person who studies biology. The -ist suffix marks the practitioner.","definitionCN":"研究生物学的人。-ist 后缀标记从业者。"},{"word":"biological","ipa":"/ˌbaɪəˈlɒdʒɪkl/","tag":"derived adjective","definition":"relating to biology or living things. It is the adjective of biology, not a separate root.","definitionCN":"与生物学或生命体有关的。它是 biology 的形容词，不是另一个词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"life science","ipa":"/ˈlaɪf saɪəns/","tag":"umbrella term","definition":"the group of sciences that study living things, including biology. It is broader and often used in industry and policy.","definitionCN":"研究生命体的科学群，包括生物学。它更宽泛，常用于产业与政策语境。"},{"word":"ecology","ipa":"/ɪˈkɒlədʒi/","tag":"organisms and environment","definition":"the study of how organisms interact with each other and their surroundings. Ecology is a branch of biology with a specific focus.","definitionCN":"研究生物之间及其与环境如何互动的学科。生态学是生物学的一个分支，焦点明确。"},{"word":"physiology","ipa":"/ˌfɪziˈɒlədʒi/","tag":"body functions","definition":"the study of how the bodies of living things work. It is narrower than biology and closer to medicine.","definitionCN":"研究生命体身体如何运作的学科。它比 biology 更窄，更接近医学。"},{"word":"botany","ipa":"/ˈbɒtəni/","tag":"plant science","definition":"the study of plants. It is one branch of biology, named by its subject matter rather than by 'life'.","definitionCN":"研究植物的学科。它是生物学的一个分支，以研究对象而非“生命”命名。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: bios 'life', -logia 'study', and the pair biologist/biological.","cn":"只用真实成分与同族词：bios“生命”、-logia“研究”，以及 biologist/biological 这对派生词。"},"normal":[{"en":"Bios + logia = 'the account of life'. Biology is not just life, but life studied and described.","cn":"bios + logia =“关于生命的论述”。biology 不只是生命，而是被研究和描述的生命。"},{"en":"Biography uses the same bios but writes a single life; biology studies life in general.","cn":"biography 用同一个 bios，但书写的是一个人的一生；biology 研究的是普遍的生命。"},{"en":"A biologist is the person; biological is the adjective; biology is the field.","cn":"biologist 是人，biological 是形容词，biology 是领域。"},{"en":"Molecular biology studies life at the molecular scale; evolutionary biology studies it across time.","cn":"分子生物学在分子尺度研究生命；进化生物学在时间维度研究生命。"},{"en":"The biology of a lake means the living population of that lake, not a course about lakes.","cn":"the biology of a lake 指湖里的生命群体，而不是一门关于湖泊的课程。"}],"abstract":[{"en":"Biology names both the lens and what the lens looks at: the science, and the living world it studies.","cn":"biology 既命名镜头，也命名镜头所看的东西：这门科学，以及它所研究的生命世界。"},{"en":"The word was invented to unify separate studies of life. Its history is an argument that life is one subject.","cn":"这个词被发明出来，是为了统一分散的生命研究。它的历史本身就在论证：生命是一个整体课题。"},{"en":"When we say 'the biology of X', we are choosing to explain X from below — through cells, chemistry, and inheritance.","cn":"当说“X 的 biology”时，我们选择从下面解释 X——通过细胞、化学和遗传。"}]},"examples":[{"en":"Biology explains how cells divide and pass on information.","cn":"生物学解释细胞如何分裂并传递信息。"},{"en":"She teaches biology at a secondary school.","cn":"她在一所中学教生物。"},{"en":"The biology of the deep sea is still poorly understood.","cn":"深海的生物情况仍知之甚少。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“拜欧乐记”——拜欧乐记笔记，记的全是生命（bio）的研究 → biology 生物学","word":"biology"},"root":"由希腊语 bios“生命”+ -logia“研究、论述”构成，字面是“关于生命的论述”，核心是“研究生命体的学科”。","sensesIntro":{"en":"Eight senses of biology, all radiating from 'the account of life': the discipline, the course, a place's organisms, an organism's machinery, a disease's mechanism, and three named levels of study.","cn":"biology 的八个义项都从“关于生命的论述”辐射出来：学科、课程、某地生物、生命体机制、疾病机制，以及三个命名的研究层级。"},"semanticMap":{"core":{"en":"CORE IMAGE: a microscope view of cells placed beside a whole living landscape — one word for the study and for life itself.","cn":"核心意象：显微镜下的细胞与整片生命景观并置——一个词同时指向研究与生命本身。"},"chain":["BIOS = LIFE","LOGIA = STUDY","THE DISCIPLINE","THE SUBJECT TAUGHT","THE ORGANISMS OF A PLACE","THE MACHINERY OF LIFE"],"branches":[{"senses":"S1 · S2","en":"THE FIELD: the science of life and its form as a school or university subject.","cn":"领域：研究生命的科学，以及它作为学校科目的形态。"},{"senses":"S3","en":"A PLACE'S LIFE: all the organisms living in one habitat.","cn":"某地的生命：一个栖息地里的全部生物。"},{"senses":"S4 · S5","en":"INNER MECHANISMS: the workings of one organism, or the biological basis of a disease.","cn":"内部机制：单个生命体的运作，或疾病的生物学基础。"},{"senses":"S6 · S7","en":"NAMED LEVELS: molecular biology studies molecules; evolutionary biology studies change over time.","cn":"命名层级：分子生物学研究分子；进化生物学研究时间中的变化。"},{"senses":"S8","en":"EXPLANATION: the biological account of behaviour, chosen as a level of explanation.","cn":"解释：对行为给出的生物学说明，被选作一种解释层级。"}]},"affixes":{"intro":{"en":"Biology is a compound of two Greek elements. English expands it with bio- compounds and with the suffixes -ist, -ical, and -ically.","cn":"biology 是两个希腊成分的复合词。英语用 bio- 复合词以及 -ist、-ical、-ically 后缀扩展它。"},"latinIntro":{"en":"The modern scientific Latin form is biologia, coined from Greek elements. Latin itself did not have this word; the family is a modern scientific construction.","cn":"现代科学拉丁语形式是 biologia，由希腊成分造出。拉丁语本身没有这个词；这个词族是现代科学构词。"},"items":[{"word":"biologist","structure":"bio- (life) + -logist (person who studies)","meaning":"a scientist who studies living things","meaningCN":"生物学家（-logist 表示研究者）","example":"The biologist recorded the migration route.","exampleCN":"生物学家记录了迁徙路线。"},{"word":"biological","structure":"biology + -ical (relating to)","meaning":"relating to biology or living things","meaningCN":"生物的；生物学的（-ical 表示“与……有关”）","example":"The biological effects of the chemical were tested.","exampleCN":"这种化学物质的生物效应被检测过。"},{"word":"biologically","structure":"biological + -ly (adverb)","meaning":"in biological terms","meaningCN":"生物学上；从生物学角度","example":"Biologically, the two populations are distinct.","exampleCN":"从生物学上看，这两个种群是不同的。"},{"word":"microbiology","structure":"micro- (small) + biology","meaning":"the study of microscopic life","meaningCN":"微生物学（micro- 表示“微小”）","example":"Microbiology is essential to food safety.","exampleCN":"微生物学对食品安全至关重要。"},{"word":"neurobiology","structure":"neuro- (nerve) + biology","meaning":"the biology of the nervous system","meaningCN":"神经生物学（neuro- 表示“神经”）","example":"Neurobiology studies how neurons communicate.","exampleCN":"神经生物学研究神经元如何交流。"},{"word":"astrobiology","structure":"astro- (star) + biology","meaning":"the study of possible life beyond Earth","meaningCN":"天体生物学（astro- 表示“星体”）","example":"Astrobiology asks whether life exists on other planets.","exampleCN":"天体生物学探讨其他行星是否存在生命。"},{"word":"biotechnology","structure":"bio- + technology","meaning":"technology that uses living systems","meaningCN":"生物技术","example":"Biotechnology produced the new vaccine.","exampleCN":"生物技术生产出了这种新疫苗。"},{"word":"biodiversity","structure":"bio- + diversity","meaning":"the variety of life in a place","meaningCN":"生物多样性","example":"The survey measured biodiversity in the river.","exampleCN":"这项调查测量了河流的生物多样性。"},{"word":"biosphere","structure":"bio- + sphere","meaning":"the part of Earth where life exists","meaningCN":"生物圈","example":"The biosphere exchanges carbon with the atmosphere.","exampleCN":"生物圈与大气交换碳。"},{"word":"biologism","structure":"biology + -ism (doctrine)","meaning":"the tendency to explain human life only by biology","meaningCN":"生物决定论（-ism 表示主义、倾向，较少用）","example":"Critics warned against biologism in social theory.","exampleCN":"批评者警告社会理论中不要陷入生物决定论。"}],"latinEntries":[{"word":"biologia","structure":"New Latin: Greek bios (life) + -logia (study)","meaning":"biology, the study of life","meaningCN":"生物学；关于生命的研究（新拉丁语造词）"}]}},{"word":"boundary","ipa_uk":"/ˈbaʊndəri/","ipa_us":"/ˈbaʊndəri/","definition_zh":"边界；界限；分界线；范围","definition_en":"a line or limit that separates two areas, marks the edge of something, or sets the extent of a subject or activity","core_image":"地面上一条清晰的分界线，两侧各插一面旗","scene":"A fence marks the boundary between the two farms.","sceneCN":"这里 boundary 是「两块土地之间的分界线」（第 1 个义项：实体边界）；句意：一道栅栏标出两个农场之间的边界。场景要点：栅栏、两侧不同的作物、界桩。","pos":[{"tag":"n.","zh":"边界；界限；分界线；范围"}],"collocations":[{"phrase":"a national boundary","zh":"国界"},{"phrase":"set boundaries","zh":"设定界限"},{"phrase":"push the boundaries","zh":"推动界限；突破极限"},{"phrase":"boundary between A and B","zh":"A 与 B 之间的界限"},{"phrase":"personal boundaries","zh":"个人边界"}],"forms":[{"label":"复数（名词）","form":"boundaries"}],"derivatives":[{"word":"bound","pos":"n./v.","zh":"界限；限制；以……为界"},{"word":"boundless","pos":"adj.","zh":"无边无际的"},{"word":"bounded","pos":"adj.","zh":"有界的；受限制的"},{"word":"boundaryless","pos":"adj.","zh":"无边界的（组织管理用语）"}],"senses":[{"no":"01","title":"A physical border between areas","titleCN":"实体边界：两地之间的线","definition":"a line, fence, wall, or natural feature that separates two areas","definitionCN":"分隔两个区域的一条线、栅栏、墙或自然地貌","example":"The river forms the boundary between the two provinces.","exampleCN":"这条河构成两省之间的边界。","why":"Boundary is bound 'limit' + -ary 'relating to'. The first sense is the physical line where one area stops and the next begins.","whyCN":"boundary 是 bound“界限”+ -ary“与……有关的”。第一个义项就是一块区域结束、另一块开始的实体线。"},{"no":"02","title":"A property line","titleCN":"地界：产权范围的边","definition":"the line marking the edge of a piece of land owned by a person or organization","definitionCN":"标示个人或组织所有土地边缘的线","example":"The neighbours disputed the boundary of their gardens.","exampleCN":"邻居们就花园的地界发生了争执。","why":"Ownership needs a stopping point. The boundary is the line at which one person's land ends and another's begins.","whyCN":"所有权需要一个终止点。boundary 就是某人的土地结束、另一人的土地开始的那条线。"},{"no":"03","title":"The limit of a subject or activity","titleCN":"学科或活动的界限：能走多远","definition":"the edge of what a subject, method, or activity covers","definitionCN":"某学科、方法或活动所覆盖范围的边缘","example":"The study crosses the boundary between biology and chemistry.","exampleCN":"这项研究跨越了生物学与化学的界限。","why":"A subject is treated as a territory. The boundary marks how far it extends and where another territory takes over.","whyCN":"一个学科被当成一片领土。boundary 标记它延伸到哪里，以及另一片领土从哪里接手。"},{"no":"04","title":"A personal boundary","titleCN":"个人边界：允许别人走到哪里","definition":"in psychology, a limit a person sets on what others may do or ask","definitionCN":"心理学中，一个人对他人可以做什么、要求什么所设定的限界","example":"She set clear boundaries with her clients about late-night calls.","exampleCN":"她就深夜来电与客户设定了明确界限。","why":"The territory is now the self. A personal boundary is the line past which another person's behaviour is not allowed to enter.","whyCN":"这里的领土是自我。个人边界就是别人的行为不允许越入的那条线。"},{"no":"05","title":"The edge of a sports field","titleCN":"场地边线：球场的范围","definition":"the line marking the edge of a playing area, beyond which the ball or player is out","definitionCN":"标示比赛区域边缘的线，越线即出界","example":"The ball crossed the boundary for four runs.","exampleCN":"球越过边线，得了四分。","why":"A game needs a place where play stops. The boundary is that line: inside is play, outside is out.","whyCN":"比赛需要一个“停止”的位置。boundary 就是那条线：线内是比赛，线外是出界。"},{"no":"06","title":"A tectonic plate boundary","titleCN":"板块边界：地壳相接处","definition":"the zone where two tectonic plates meet, often producing earthquakes and volcanoes","definitionCN":"两个构造板块相接的地带，常引发地震和火山","example":"The Pacific plate boundary is ringed by volcanoes.","exampleCN":"太平洋板块边界环绕着火山。","why":"The earth's crust is divided into plates; the boundary is the seam where two of them meet and grind against each other.","whyCN":"地壳被分成板块；boundary 就是两个板块相接、相互摩擦的接缝。"},{"no":"07","title":"A boundary condition","titleCN":"边界条件：数学与物理的限定","definition":"a condition that a solution must satisfy at the edge of a region","definitionCN":"解在某个区域边缘必须满足的条件","example":"The equation needs boundary conditions before it can be solved.","exampleCN":"这个方程需要边界条件才能求解。","why":"In mathematics, the region has an edge, and the behaviour at that edge constrains what can happen inside.","whyCN":"数学中，区域有边缘，边缘处的行为约束了内部可以发生什么。"},{"no":"08","title":"An organizational boundary","titleCN":"组织边界：公司管到哪儿","definition":"the limit of what an organization controls, owns, or is responsible for","definitionCN":"一个组织所控制、拥有或负责的范围界限","example":"Outsourcing moves work across the boundary of the firm.","exampleCN":"外包把工作移到公司的边界之外。","why":"A firm is a territory of decisions. Its boundary marks where its authority ends and a supplier's or partner's begins.","whyCN":"公司是一片决策领土。它的 boundary 标记其权限到哪里结束、供应商或伙伴的权限从哪里开始。"}],"etymology":{"intro":{"en":"Boundary is an English formation from bound 'limit' plus the suffix -ary. Its history also contains a warning: bound 'limit' and bound 'leap' look identical but are unrelated.","cn":"boundary 是英语构词，由 bound“界限”加后缀 -ary 构成。它的历史里还有一个提醒：bound“界限”与 bound“跳跃”拼写相同，却毫无亲缘关系。"},"items":[{"era":"1620S","en":"Boundary is first recorded in the 1620s as 'that which marks the limits of something'. It was formed inside English, not borrowed whole.","cn":"boundary 最早记录于 1620 年代，意为“标示某物界限的东西”。它是在英语内部构成的，不是整体借入。"},{"era":"BOUND n. 'LIMIT'","en":"Bound meaning 'limit' goes back to late 13th-century English, from Old French bonde 'limit, boundary marker'.","cn":"表示“界限”的 bound 可追溯到 13 世纪后期的英语，来自古法语 bonde“界限、界桩”。"},{"era":"MEDIEVAL LATIN bodina","en":"Old French bonde came from Medieval Latin bodina, a boundary marker. The deeper origin of bodina is uncertain and may be Gaulish.","cn":"古法语 bonde 来自中世纪拉丁语 bodina，指界桩。bodina 的更深来源不确定，可能来自高卢语。"},{"era":"SUFFIX -ARY","en":"-ary is a suffix forming adjectives and nouns 'relating to'. Boundary therefore means 'the thing relating to a bound'.","cn":"-ary 是构成形容词和名词的后缀，表示“与……有关”。因此 boundary 意为“与界限有关的东西”。"},{"era":"FALSE FRIEND","en":"Bound meaning 'to leap' comes from Old French bondir and is a different word. A boundary has nothing to do with jumping; only the spelling coincides.","cn":"表示“跳跃”的 bound 来自古法语 bondir，是另一个词。boundary 与跳跃毫无关系，只是拼写碰巧相同。"},{"era":"MODERN EXPANSION","en":"From land borders, boundary expanded to subjects, personal limits, sports lines, tectonic plates, mathematical conditions, and organizational scope.","cn":"从土地边界出发，boundary 扩展到学科、个人界限、运动场边线、构造板块、数学条件和组织范围。"}]},"similar":{"note":{"en":"The first group shares bound and the -ary/-less family; the second collects limit words that differ in scale and tone.","cn":"第一组共享 bound 与 -ary/-less 词族；第二组收“界限”类词，规模和语气不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bound","ipa":"/baʊnd/","tag":"root word","definition":"a limit, or to limit; also 'to leap' as an unrelated homograph. Boundary is the noun built from the first meaning.","definitionCN":"界限，或限制；另有一个同形异义词表示“跳跃”。boundary 是由第一个义项构成的名词。"},{"word":"boundless","ipa":"/ˈbaʊndləs/","tag":"same family, no limit","definition":"having no limits. Bound + -less removes the boundary entirely.","definitionCN":"没有界限的。bound + -less 把边界完全去掉。"},{"word":"bounded","ipa":"/ˈbaʊndɪd/","tag":"derived adjective","definition":"limited or enclosed by a boundary. It is the past participle of bound used as an adjective.","definitionCN":"有界的；受边界限制的。它是 bound 的过去分词转作形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"border","ipa":"/ˈbɔːdə/","tag":"political edge","definition":"the line between countries or regions. It is more political and geographical than boundary.","definitionCN":"国家或地区之间的线。它比 boundary 更政治化、更地理化。"},{"word":"frontier","ipa":"/ˈfrʌntɪə/","tag":"outer edge","definition":"the outer limit of settled or known territory. It suggests something still open and expanding.","definitionCN":"已开发或已知领土的外缘。它暗示仍然开放、仍在扩展的地带。"},{"word":"limit","ipa":"/ˈlɪmɪt/","tag":"general cap","definition":"the point beyond which something cannot or may not go. It is broader and can be numerical or abstract.","definitionCN":"某物不能或不允许越过的点。它更宽泛，可以是数字的或抽象的。"},{"word":"edge","ipa":"/edʒ/","tag":"outer rim","definition":"the outer line or side of an object or area. Edge is often physical and literal, while boundary implies separation.","definitionCN":"物体或区域的外沿线或外侧。edge 多为字面、物理的；boundary 暗示分隔。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: bound 'limit', -ary 'relating to', and the derived words boundless and bounded.","cn":"只用真实成分与同族词：bound“界限”、-ary“与……有关”，以及派生词 boundless、bounded。"},"normal":[{"en":"Boundary is bound + -ary: the thing that relates to a limit.","cn":"boundary 是 bound + -ary：与界限有关的东西。"},{"en":"Bound meaning 'limit' and bound meaning 'leap' are different words. Do not connect boundary with jumping.","cn":"表示“界限”的 bound 与表示“跳跃”的 bound 是两个词。不要把 boundary 和跳跃联系起来。"},{"en":"A boundary marker is literally a bound: a stone or post that shows where land stops.","cn":"boundary marker 字面上就是一根 bound：标明土地到哪里为止的石块或桩。"},{"en":"Boundless means the boundary is gone; bounded means the boundary is holding.","cn":"boundless 表示边界消失；bounded 表示边界仍然约束着。"},{"en":"Personal boundaries are the same line moved from land to the self.","cn":"个人边界就是把同一条线从土地移到自我身上。"}],"abstract":[{"en":"A boundary is not a thing; it is a relation between two sides. Remove one side, and the line has nothing to separate.","cn":"边界不是一件东西，而是两边之间的关系。去掉一边，这条线就没有可分隔的对象了。"},{"en":"Every boundary creates an inside and an outside at the same moment.","cn":"每条边界都在同一瞬间制造出“里面”和“外面”。"},{"en":"The word can be physical, social, mathematical, or organizational because separation itself has the same shape everywhere.","cn":"这个词可以是实体的、社会的、数学的或组织的，因为“分隔”本身在任何地方都是同一种形状。"}]},"examples":[{"en":"The boundary between the two countries runs through the mountains.","cn":"两国的边界穿过群山。"},{"en":"Good fences make clear boundaries between neighbours.","cn":"好的栅栏在邻居之间划出清晰的地界。"},{"en":"Scientists continue to push the boundaries of what is known.","cn":"科学家不断推进已知世界的边界。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“邦德里”——邦德里在田边插一排旗子，标出两家的地界 → boundary 边界、界限","word":"boundary"},"root":"由 bound“界限”+ -ary“与……有关的”构成；bound 来自古法语 bonde“界限、界桩”，再往前为中世纪拉丁语 bodina，更深来源不确定。核心是“把两边分开的那条线”。","sensesIntro":{"en":"Eight senses of boundary, all built on one relation: a line at which one side stops and another begins.","cn":"boundary 的八个义项都建立在同一种关系上：一条线，一边到此为止，另一边从此开始。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line drawn between two sides, with a marker on it.","cn":"核心意象：在两边之间画出的一条线，线上有一个标记。"},"chain":["A LIMIT","MARKED LINE","TWO SIDES SEPARATED","INSIDE AND OUTSIDE","EXTENT DEFINED","SCOPE OR RESPONSIBILITY LIMITED"],"branches":[{"senses":"S1 · S2 · S5","en":"PHYSICAL LINES: regional borders, property lines, and the edge of a playing field.","cn":"实体线：地区边界、地界和运动场边线。"},{"senses":"S3 · S7","en":"FORMAL LIMITS: the edge of a subject, and a mathematical condition at the edge of a region.","cn":"形式界限：学科的边缘，以及区域边缘上的数学条件。"},{"senses":"S4","en":"THE SELF: the line past which other people's behaviour may not go.","cn":"自我：他人行为不允许越过的那条线。"},{"senses":"S6","en":"THE EARTH: the seam where two tectonic plates meet.","cn":"地球：两个构造板块相接的接缝。"},{"senses":"S8","en":"ORGANIZATION: the limit of a firm's authority, ownership, and responsibility.","cn":"组织：公司权限、所有权与责任的界限。"}]},"affixes":{"intro":{"en":"Boundary is bound + -ary. English extends the family with -less and -ed, and with compounds such as boundary line and boundary stone.","cn":"boundary 是 bound + -ary。英语用 -less、-ed，以及 boundary line、boundary stone 这类复合词扩展词族。"},"latinIntro":{"en":"The nearest documented source is Medieval Latin bodina 'boundary marker', but its own origin is uncertain and possibly Gaulish. latinEntries records it with that caution rather than inventing a classical root.","cn":"目前可考的更早来源是中世纪拉丁语 bodina“界桩”，但它自身的来源不确定，可能来自高卢语。latinEntries 如实记录它，并保留这一保留意见，而不编造古典词根。"},"items":[{"word":"bound","structure":"base noun / verb","meaning":"a limit; to form the boundary of something","meaningCN":"界限；以……为界；限制","example":"The field is bounded by a low wall.","exampleCN":"这块田以一道矮墙为界。"},{"word":"boundaries","structure":"boundary + -ies (plural)","meaning":"more than one boundary","meaningCN":"多条边界；多重界限","example":"The map shows the boundaries of the old estates.","exampleCN":"地图标出了旧庄园的地界。"},{"word":"boundless","structure":"bound + -less (without)","meaning":"without limits","meaningCN":"无边无际的；无限的（-less 表示“没有”）","example":"The child had boundless energy.","exampleCN":"那个孩子精力无限。"},{"word":"bounded","structure":"bound + -ed (past participle / adjective)","meaning":"limited or enclosed","meaningCN":"有界的；受限制的","example":"The problem is defined on a bounded region.","exampleCN":"这个问题定义在一个有界区域上。"},{"word":"unbounded","structure":"un- (not) + bounded","meaning":"having no limits","meaningCN":"无界的；没有限制的","example":"The model assumes an unbounded market.","exampleCN":"该模型假设一个无界市场。"},{"word":"boundaryless","structure":"boundary + -less","meaning":"without organizational boundaries","meaningCN":"无边界的（组织管理用语）","example":"The firm experimented with a boundaryless structure.","exampleCN":"这家公司尝试了无边界结构。"},{"word":"boundary line","structure":"boundary + line (compound noun)","meaning":"the line that marks a boundary","meaningCN":"边界线；分界线","example":"The treaty fixed the boundary line for the first time.","exampleCN":"该条约首次确定了边界线。"},{"word":"boundary stone","structure":"boundary + stone (compound noun)","meaning":"a stone marker showing where a boundary runs","meaningCN":"界石；标明边界的石块","example":"An old boundary stone still stands at the corner.","exampleCN":"角落里仍立着一块旧界石。"},{"word":"boundary condition","structure":"boundary + condition (compound noun)","meaning":"a condition required at the edge of a mathematical region","meaningCN":"边界条件（数学或物理用语）","example":"The simulation needs a boundary condition at each wall.","exampleCN":"模拟需要在每个壁面设置边界条件。"}],"latinEntries":[{"word":"bodina","structure":"Medieval Latin noun","meaning":"a boundary marker; deeper origin uncertain, possibly Gaulish","meaningCN":"界桩；界限标记（更深来源不确定，可能来自高卢语）"}]}},{"word":"brief","ipa_uk":"/briːf/","ipa_us":"/briːf/","definition_zh":"简短的；短暂的；简要介绍；辩护状","definition_en":"lasting or using only a short time or few words, or a short written statement that gives the main points","core_image":"被压到最短的一小段文字","scene":"The lawyer handed the judge a two-page brief before the hearing.","sceneCN":"这里 brief 是「提交法庭的辩护状」（第 5 个义项：法律文书）；句意：开庭前，律师向法官递交了一份两页的辩护状。场景要点：法庭、两页文件、律师与法官。","pos":[{"tag":"adj.","zh":"简短的；短暂的；简慢的"},{"tag":"n.","zh":"摘要；指示；辩护状；（复数）内裤"},{"tag":"vt.","zh":"向……简要介绍；给……指示"}],"collocations":[{"phrase":"a brief summary","zh":"简要总结"},{"phrase":"a brief pause","zh":"短暂的停顿"},{"phrase":"in brief","zh":"简而言之"},{"phrase":"brief someone on something","zh":"向某人简要介绍某事"},{"phrase":"hold no brief for","zh":"不为……辩护；不支持"}],"forms":[{"label":"比较级（更简短）","form":"briefer"},{"label":"最高级（最简短）","form":"briefest"},{"label":"复数（名词）","form":"briefs"},{"label":"三单（he/she/it）","form":"briefs"},{"label":"过去式（已经发生）","form":"briefed"},{"label":"过去分词（完成／被动）","form":"briefed"},{"label":"现在分词（进行体）","form":"briefing"}],"derivatives":[{"word":"briefly","pos":"adv.","zh":"简短地；短暂地"},{"word":"briefing","pos":"n.","zh":"简报会；情况介绍"},{"word":"brevity","pos":"n.","zh":"简短；简洁"},{"word":"abbreviate","pos":"v.","zh":"缩写；缩短"}],"senses":[{"no":"01","title":"Short in duration","titleCN":"短暂的：时间很短","definition":"lasting only a short time","definitionCN":"只持续很短时间","example":"There was a brief silence after the question.","exampleCN":"问题提出后有一段短暂的沉默。","why":"Brief comes from Latin brevis 'short'. The first sense measures time: a small span between two moments.","whyCN":"brief 来自拉丁语 brevis“短的”。第一个义项量的是时间：两个时刻之间的一小段。"},{"no":"02","title":"Short in wording","titleCN":"简短的：话说得少","definition":"expressed in few words; not long or detailed","definitionCN":"用很少的词表达；不长、不详细","example":"He gave a brief account of what had happened.","exampleCN":"他简短地叙述了发生了什么。","why":"The same measure is applied to language: few words instead of many, a short stretch of text.","whyCN":"同一个尺度被用到语言上：词少而不是多，一段短文本。"},{"no":"03","title":"Curt or abrupt in manner","titleCN":"简慢的：短到显得冷淡","definition":"using very few words in a way that seems rude or impatient","definitionCN":"用很少的词，显得无礼或不耐烦","example":"Her brief reply suggested that the conversation was over.","exampleCN":"她简短的回答暗示谈话结束了。","why":"When brevity is applied to social behaviour, shortness can become coldness: too few words leave no warmth in them.","whyCN":"当“简短”被用到社交行为上，短就可能变成冷：话太少，里面就没有温度。"},{"no":"04","title":"A summary or set of instructions","titleCN":"摘要或指示：把要点压短","definition":"a short written or spoken statement giving the main points or instructions","definitionCN":"给出要点或指示的简短书面或口头陈述","example":"The manager gave the team a brief on the new project.","exampleCN":"经理向团队简要介绍了新项目。","why":"A brief is literally a short writing: the long material is compressed into its main points.","whyCN":"a brief 字面上就是一份短文书：把长材料压缩成要点。"},{"no":"05","title":"A legal brief","titleCN":"辩护状：写给法庭的要点文件","definition":"a written legal document that sets out the facts and arguments of a case","definitionCN":"陈述案件事实与论点的书面法律文件","example":"The defence filed a brief arguing that the evidence was inadmissible.","exampleCN":"辩方提交了一份辩护状，主张证据不可采纳。","why":"Law also compresses a case into a short document for the court. The word keeps its 'short statement' sense inside a legal setting.","whyCN":"法律同样把案件压缩成一份给法庭的短文件。这个词在法律场景里保留了“简短陈述”的意思。"},{"no":"06","title":"A papal brief","titleCN":"教皇简谕：教廷的短文书","definition":"in Catholic history, a short official letter from the pope on a matter of lesser importance than a bull","definitionCN":"天主教历史中，教皇就较次要事务发出的简短正式文书","example":"The papal brief granted the order a new privilege.","exampleCN":"这份教皇简谕授予该修会一项新特权。","why":"The papal document is named by its physical shortness: a breve scriptum, a short writing, as opposed to a longer bull.","whyCN":"这份教皇文书以篇幅短小命名：breve scriptum，一篇短文书，相对于更长的教皇诏书。"},{"no":"07","title":"Briefs as underwear","titleCN":"内裤：短小的贴身衣物","definition":"short, close-fitting underpants, used in the plural","definitionCN":"短小贴身的内裤，用复数形式","example":"He packed two pairs of briefs for the trip.","exampleCN":"他旅行带了两条内裤。","why":"The clothing sense also works by shortness: briefs are the short version of underwear, as opposed to longer boxer shorts.","whyCN":"服装义同样靠“短”：briefs 是内裤的短款，相对于更长的平角裤。"},{"no":"08","title":"To inform or instruct briefly","titleCN":"简要介绍：把情况压短告知","definition":"to give someone the essential information or instructions about something","definitionCN":"向某人提供关于某事的关键信息或指示","example":"The pilot was briefed on the weather before take-off.","exampleCN":"起飞前，飞行员听取了天气简报。","why":"The verb turns the noun into an action: you give someone a short account of what they need to know.","whyCN":"动词把名词变成动作：你把对方需要知道的内容压成简短说明交给他。"},{"no":"09","title":"In brief","titleCN":"简而言之：把话压到最短","definition":"in the phrase in brief, meaning 'in a few words' or 'in summary'","definitionCN":"在短语 in brief 中，表示“用几句话”或“总之”","example":"In brief, the plan is too expensive and too slow.","exampleCN":"简而言之，这个计划太贵也太慢。","why":"The phrase uses the noun's core sense directly: the whole matter is put into a short form.","whyCN":"这个短语直接使用名词的核心义：把整件事放进一个短形式里。"},{"no":"10","title":"Hold no brief for","titleCN":"不为……辩护：不支持某立场","definition":"in the idiom hold no brief for, meaning not to support or defend someone or something","definitionCN":"在习语 hold no brief for 中，表示不支持、不为某人或某物辩护","example":"I hold no brief for the company's past behaviour.","exampleCN":"我不为公司过去的行为辩护。","why":"A brief was a legal argument for a client. To hold no brief for someone is to refuse to take that client's case.","whyCN":"brief 曾是为当事人准备的辩护论点。hold no brief for 某人，就是拒绝接这个“当事人的案子”。"}],"etymology":{"intro":{"en":"Brief is a short word about shortness, borrowed from Latin brevis through French. Every sense — time, words, law, clothing, papal letters — is a variation on 'short'.","cn":"brief 是一个关于“短”的短词，经法语借自拉丁语 brevis。时间、措辞、法律、服装、教皇文书——每个义项都是“短”的变体。"},"items":[{"era":"C. 1300","en":"English borrowed brief from Old French, where it was both an adjective 'short' and a noun 'short writing'. The adjective appears first.","cn":"英语约在 1300 年从古法语借入 brief，在那里它既是形容词“短的”，也是名词“短文书”。形容词义先出现。"},{"era":"LATIN brevis","en":"Latin brevis meant 'short, low, little, shallow'. It is the source of the adjective and of the noun breve 'a short writing'.","cn":"拉丁语 brevis 意为“短的、低的、小的、浅的”。它是形容词的来源，也是名词 breve“短文书”的来源。"},{"era":"PIE *mregh-u-","en":"Brevis is generally traced to a PIE root *mregh-u- 'short'. The reconstruction is widely accepted but, like all PIE roots, not directly attested.","cn":"brevis 一般被追溯到原始印欧语词根 *mregh-u-“短”。这一重构被广泛接受，但和所有原始印欧语词根一样，没有直接文献证据。"},{"era":"LEGAL AND PAPAL","en":"In law, a brief became the written argument handed to the court; in the papal chancery, a brief was a short letter. Both are named for the physical shortness of the document.","cn":"在法律中，brief 成为递交给法庭的书面论证；在教皇文书处，brief 是简短书信。两者都以文书的短小篇幅命名。"},{"era":"20C. CLOTHING","en":"Briefs for short underpants appears in the 20th century, again by contrast with longer garments.","cn":"briefs 表示短款内裤的用法出现在 20 世纪，同样是与更长的衣物相对而言。"},{"era":"RELATED FAMILY","en":"Brevity, abbreviate, abbreviation, and abridge all come from brevis. Brief and breve are doublets of the same Latin root: one through French, one directly.","cn":"brevity、abbreviate、abbreviation、abridge 都来自 brevis。brief 与 breve 是同一拉丁词根的双形：一个经法语，一个直接借入。"}]},"similar":{"note":{"en":"The first group shares the Latin brevis root; the second collects short-in-time or short-in-words words with different tones.","cn":"第一组共享拉丁语 brevis 词根；第二组收“时间短”或“话短”的词，语气不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"brevity","ipa":"/ˈbrevəti/","tag":"same root, state noun","definition":"the quality of being short or concise. It is the noun of brief's core quality.","definitionCN":"简短、简洁的性质。它是 brief 核心性质的名词形式。"},{"word":"abbreviate","ipa":"/əˈbrevɪeɪt/","tag":"same root, verb","definition":"to shorten a word or text. Ab- 'to' + brevis 'short' + -ate gives 'make short'.","definitionCN":"缩短一个词或文本。ab-“向”+ brevis“短”+ -ate，表示“使变短”。"},{"word":"briefing","ipa":"/ˈbriːfɪŋ/","tag":"derived noun","definition":"a meeting or document that gives essential information. It is the noun from the verb brief.","definitionCN":"提供关键信息的会议或文件。它是动词 brief 的名词派生。"}]},{"heading":"NEAR MEANING","entries":[{"word":"short","ipa":"/ʃɔːt/","tag":"plain length word","definition":"measuring little in length or time. It is the everyday word; brief is more formal and often implies compression.","definitionCN":"长度或时间很小的。它是日常词；brief 更正式，常暗示压缩。"},{"word":"concise","ipa":"/kənˈsaɪs/","tag":"few words, full meaning","definition":"giving much information in few words. Concise is positive; brief can also mean incomplete or curt.","definitionCN":"用很少的词给出大量信息。concise 是褒义；brief 也可能表示不完整或简慢。"},{"word":"fleeting","ipa":"/ˈfliːtɪŋ/","tag":"very short in time","definition":"lasting only a moment. It applies mainly to time, not to wording.","definitionCN":"只持续一瞬的。它主要用于时间，不用于措辞。"},{"word":"summary","ipa":"/ˈsʌməri/","tag":"condensed account","definition":"a short statement of the main points. It overlaps with brief as a noun, but summary stresses selecting main points rather than sheer shortness.","definitionCN":"主要内容的简短陈述。它作名词时与 brief 重叠，但 summary 强调选取要点，而非单纯短。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: Latin brevis 'short', the doublet breve, and the family brevity/abbreviate/abridge.","cn":"只用真实成分与同族词：拉丁语 brevis“短”、双形 breve，以及 brevity/abbreviate/abridge 词族。"},"normal":[{"en":"Everything called brief is short: a short time, a short text, short pants, a short legal document.","cn":"所有叫 brief 的东西都短：短时间、短文本、短内裤、短法律文书。"},{"en":"Brevity is the noun for shortness; abbreviate is the verb 'to make short'.","cn":"brevity 是“简短”的名词；abbreviate 是“使变短”的动词。"},{"en":"A legal brief is not a short lawyer; it is a short written argument for the court.","cn":"a legal brief 不是“矮个子律师”，而是写给法庭的简短书面论证。"},{"en":"In brief means 'in a few words' — the noun's shortness used as a phrase.","cn":"in brief 意为“用几句话”——名词的“短”被用作短语。"},{"en":"Briefs as underwear are named by contrast with longer boxer shorts.","cn":"briefs 指内裤，是与更长的平角裤对比而得名。"}],"abstract":[{"en":"Brief is a measure word: it always implies that something longer has been cut down or that a span is small.","cn":"brief 是一个尺度词：它总暗示某个更长的东西被截短了，或某段跨度很小。"},{"en":"The same shortening can be respectful (concise) or rude (curt), depending on how much warmth the few words carry.","cn":"同样的“缩短”可以是尊重（简洁），也可以是无礼（简慢），取决于这几个字里带了多少温度。"},{"en":"A brief tries to keep the essential and drop the rest; what counts as essential depends on who is listening.","cn":"brief 试图留下必要部分、丢掉其余；什么算“必要”，取决于听的人是谁。"}]},"examples":[{"en":"The meeting was brief but productive.","cn":"会议很短，但很有成效。"},{"en":"Please keep your answer brief and to the point.","cn":"请回答简短、切中要点。"},{"en":"The officer was briefed on the security arrangements.","cn":"这名警官听取了安保安排的简报。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“布里夫”——布里夫说话像被剪短的布，几句就完 → brief 简短的、摘要","word":"brief"},"root":"源自拉丁语 brevis“短的”，经古法语进入英语；核心是“被截短、只留要点”，并由此派生出时间短、文书短、衣物短等义。","sensesIntro":{"en":"Ten senses of brief, all built on one measure: shortness — in time, in words, in clothing, or in the length of a document.","cn":"brief 的十个义项都建立在同一个尺度上：短——时间短、措辞短、衣物短，或文书篇幅短。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long thing cut down to the shortest useful form.","cn":"核心意象：把长东西截到最短的有用形式。"},"chain":["BREVIS = SHORT","SHORT TIME","FEW WORDS","COMPRESSED STATEMENT","SHORT OFFICIAL DOCUMENT","SHORT GARMENT"],"branches":[{"senses":"S1 · S2","en":"SHORTNESS: a brief pause and a brief account are the same measure applied to time and words.","cn":"短：短暂停顿与简短叙述，是同一尺度用在时间和语言上。"},{"senses":"S3","en":"SOCIAL COLDNESS: too few words can turn shortness into curtness.","cn":"社交冷淡：话太少，可能把“简短”变成“简慢”。"},{"senses":"S4 · S8 · S9","en":"COMPRESSED INFORMATION: a summary, the act of informing, and the phrase in brief.","cn":"压缩信息：摘要、告知动作，以及短语 in brief。"},{"senses":"S5 · S6","en":"OFFICIAL DOCUMENTS: a legal brief and a papal brief are both short formal writings.","cn":"正式文书：法律辩护状与教皇简谕都是简短的正式文书。"},{"senses":"S7 · S10","en":"SHORT FORMS: briefs as short underwear, and holding no brief as refusing a legal case.","cn":"短形式：briefs 是短内裤；hold no brief 是拒绝接案。"}]},"affixes":{"intro":{"en":"Brief is a borrowed adjective and noun. English adds -ly, -ness, -ing, and -ed, and forms abbreviations from the same Latin root.","cn":"brief 是借入的形容词兼名词。英语加 -ly、-ness、-ing、-ed，并从同一拉丁词根构成缩写词族。"},"latinIntro":{"en":"The Latin root is brevis 'short', with the noun breve 'a short writing'. Brevity and abbreviate were built in Latin; brief and breve reached English by different routes.","cn":"拉丁词根是 brevis“短的”，名词 breve 指“短文书”。brevity 与 abbreviate 是在拉丁语中构成的；brief 与 breve 经不同路径进入英语。"},"items":[{"word":"briefly","structure":"brief + -ly (adverb)","meaning":"for a short time or in few words","meaningCN":"短暂地；简短地（-ly 构成副词）","example":"She explained the rule briefly.","exampleCN":"她简短地解释了规则。"},{"word":"briefness","structure":"brief + -ness (quality noun)","meaning":"the quality of being short","meaningCN":"简短；短暂（-ness 表示性质）","example":"The briefness of the visit disappointed the fans.","exampleCN":"访问时间之短让粉丝失望。"},{"word":"briefing","structure":"brief + -ing (process noun)","meaning":"a meeting or document giving essential information","meaningCN":"简报会；情况介绍（-ing 构成名词）","example":"The morning briefing lasted ten minutes.","exampleCN":"早间简报持续了十分钟。"},{"word":"briefed","structure":"brief + -ed (past participle)","meaning":"given essential information","meaningCN":"已听取简报的；已被告知的","example":"The staff were briefed on the new safety rules.","exampleCN":"员工已听取新安全规则的简报。"},{"word":"brevity","structure":"brev(is) + -ity (state noun)","meaning":"shortness of speech or writing; conciseness","meaningCN":"简短；简洁（-ity 表示状态）","example":"The brevity of the note made it seem cold.","exampleCN":"这张便条太简短，显得冷淡。"},{"word":"breve","structure":"Latin breve, borrowed directly","meaning":"a short written note; also a mark in music and phonetics","meaningCN":"短文书；也指音乐与语音学中的短音符","example":"The scribe recorded the order in a breve.","exampleCN":"书记员用一份短文书记录了这道命令。"},{"word":"breviary","structure":"brevi(are) + -ary (book)","meaning":"a book containing the daily prayers of the Catholic clergy","meaningCN":"日课经；天主教神职人员每日祈祷用书（-ary 表示书册）","example":"The monk opened his breviary before dawn.","exampleCN":"天没亮，修士就翻开了日课经。"},{"word":"abbreviate","structure":"ab- (to) + brevi(s) + -ate (verb)","meaning":"to shorten a word or text","meaningCN":"缩写；缩短（-ate 构成动词）","example":"We abbreviate 'kilogram' as 'kg'.","exampleCN":"我们把 kilogram 缩写为 kg。"},{"word":"abbreviation","structure":"ab- + brevi(s) + -ation (process noun)","meaning":"a shortened form of a word, or the act of shortening","meaningCN":"缩写形式；缩短行为（-ation 表示过程）","example":"'Dr.' is an abbreviation of 'doctor'.","exampleCN":"Dr. 是 doctor 的缩写。"},{"word":"abridge","structure":"a- + bridge (from Old French abregier, from brevis)","meaning":"to shorten a book or speech while keeping the main content","meaningCN":"删节；缩短（保留主要内容）","example":"The publisher abridged the novel for younger readers.","exampleCN":"出版社为年轻读者删节了这部小说。"},{"word":"unabridged","structure":"un- (not) + abridged","meaning":"not shortened; complete","meaningCN":"未删节的；完整的（un- 表示否定）","example":"The library owns the unabridged dictionary.","exampleCN":"图书馆藏有未删节版词典。"},{"word":"briefs","structure":"brief + -s (plural)","meaning":"short underpants, or multiple short documents","meaningCN":"短内裤；多份简报（复数）","example":"He bought three pairs of briefs.","exampleCN":"他买了三条内裤。"}],"latinEntries":[{"word":"brevis","structure":"Latin adjective","meaning":"short, brief, low, little","meaningCN":"短的；简短的；低的；小的"},{"word":"breve","structure":"Latin noun (neuter of brevis)","meaning":"a short writing, a brief note","meaningCN":"短文书；简短记录"}]}},{"word":"capable","ipa_uk":"/ˈkeɪpəbl/","ipa_us":"/ˈkeɪpəbl/","definition_zh":"有能力的；能胜任的；有……可能的","definition_en":"having the ability or skill to do something, or having the potential to be or do something","core_image":"一只稳稳抓住工具的手：能拿得住、做得到","scene":"She is capable of running the whole department on her own.","sceneCN":"这里 capable 是「有能力做到」（第 3 个义项：capable of + 名词/动名词，表示具备潜力）；句意：她有能力独自管理整个部门。场景要点：办公室、一叠文件、独自主持会议的人。","pos":[{"tag":"adj.","zh":"有能力的；能胜任的；能……的"}],"collocations":[{"phrase":"capable of doing something","zh":"有能力做某事"},{"phrase":"a capable manager","zh":"能干的经理"},{"phrase":"perfectly capable","zh":"完全有能力"},{"phrase":"capable of growth","zh":"有增长潜力"},{"phrase":"legally capable","zh":"有法律行为能力的"}],"forms":[{"label":"比较级（更多用 more 构成）","form":"more capable"},{"label":"最高级（更多用 most 构成）","form":"most capable"}],"derivatives":[{"word":"capability","pos":"n.","zh":"能力；才能；性能"},{"word":"capably","pos":"adv.","zh":"能干地；有能力地"},{"word":"incapable","pos":"adj.","zh":"无能力的；不能胜任的"},{"word":"incapacity","pos":"n.","zh":"无能力；法律上的无行为能力"}],"senses":[{"no":"01","title":"Able to do something well","titleCN":"有能力的：做得到","definition":"having enough skill, strength, or knowledge to do a task","definitionCN":"具备完成任务所需的技能、力量或知识","example":"She is a capable driver in difficult conditions.","exampleCN":"她在复杂路况下也能安全驾驶。","why":"Capable comes from Latin capere 'to take, hold'. A capable person can take hold of a task and carry it.","whyCN":"capable 来自拉丁语 capere“拿住、握住”。有能力的人能抓住一项任务并把它做下去。"},{"no":"02","title":"Competent in a role","titleCN":"能胜任的：放在岗位上放心","definition":"effective and reliable in a particular job or position","definitionCN":"在特定工作或职位上有效、可靠","example":"The company needs a capable operations director.","exampleCN":"公司需要一位能干的运营主管。","why":"The ability is now measured against a role. A capable manager is one who can hold the responsibilities of that position.","whyCN":"这里的能力是相对于一个职位来衡量的。capable manager 就是能接住该职位责任的人。"},{"no":"03","title":"Having the potential to do something","titleCN":"有潜力：具备做某事的条件","definition":"having the qualities or conditions needed to do something, whether or not one actually does it","definitionCN":"具备做某事所需的性质或条件，不论是否实际去做","example":"The material is capable of storing large amounts of heat.","exampleCN":"这种材料能储存大量热量。","why":"Capable of marks possibility held inside the thing. The ability may not yet be used; it is the capacity to take something on.","whyCN":"capable of 标记事物内部蕴含的可能性。这种能力未必已被使用；它是“接得住”的容量。"},{"no":"04","title":"Capable of something bad","titleCN":"做得出坏事：能力不分善恶","definition":"having the ability or willingness to do something harmful or shocking","definitionCN":"有能力或意愿做出有害、令人震惊的事","example":"The court asked whether he was capable of such violence.","exampleCN":"法庭问他是否做得出这种暴力行为。","why":"The word measures ability, not morality. If someone can take hold of an action at all, they are capable of it, even when the action is terrible.","whyCN":"这个词衡量的是能力，不是道德。只要一个人抓得住某个行动，他就有能力做它，哪怕这个行动很可怕。"},{"no":"05","title":"Capable of being changed or used","titleCN":"可被……的：技术上具备条件","definition":"in technical contexts, able to undergo a specified process or treatment","definitionCN":"技术语境中，能够经历某种过程或处理","example":"The alloy is capable of being formed at low temperature.","exampleCN":"这种合金可以在低温下成型。","why":"The passive construction 'capable of being' treats the object as something that can be taken and worked on.","whyCN":"被动结构 capable of being 把对象当作可以被拿住、被加工的东西。"},{"no":"06","title":"Legally competent","titleCN":"法律上有行为能力的","definition":"having the legal mental capacity to make decisions or enter contracts","definitionCN":"具有做出决定或签订合同的法律心智能力","example":"A lawyer must confirm that the client is capable.","exampleCN":"律师必须确认委托人有行为能力。","why":"Law asks whether a person can hold the consequences of a decision. Capable here means able to take legal responsibility.","whyCN":"法律要问一个人能否承担决定的后果。这里的 capable 指能接住法律责任。"},{"no":"07","title":"Capable of growth or improvement","titleCN":"有成长空间：还能变得更好","definition":"having room to develop or improve","definitionCN":"有发展或改善的空间","example":"The business is capable of much faster growth.","exampleCN":"这家企业有能力实现快得多的增长。","why":"The thing can take more into itself: more growth, more output, more responsibility. The root image is a container with room.","whyCN":"该事物能往自己里面装更多：更多增长、更多产出、更多责任。词根意象是一个还有空间的容器。"},{"no":"08","title":"Receptive to impressions","titleCN":"能感受的：哲学上的接受能力","definition":"in philosophy, able to receive impressions or experiences","definitionCN":"哲学中，能够接受印象或经验","example":"The mind is capable of receiving sensations but not of creating them.","exampleCN":"心智能够接受感觉，但不能创造感觉。","why":"This older sense returns to the Latin image of taking in: the mind is a receiver that can hold what comes to it.","whyCN":"这个较旧的义项回到拉丁语“接进来”的意象：心智是一个能接住外来内容的接收器。"}],"etymology":{"intro":{"en":"Capable came into English from French, but its root is Latin capere 'to take, hold'. The word describes not what someone has done, but what they can take hold of.","cn":"capable 从法语进入英语，但词根是拉丁语 capere“拿住、握住”。这个词描述的不是一个人做过什么，而是他能接住什么。"},"items":[{"era":"1560S","en":"Capable is first recorded in the 1560s, meaning 'able to comprehend'. It came from French capable or directly from Late Latin capabilis.","cn":"capable 最早记录于 1560 年代，意为“能够理解”。它来自法语 capable，或直接来自晚期拉丁语 capabilis。"},{"era":"LATE LATIN capabilis","en":"Capabilis meant 'able to take in'. It was formed from Latin capere 'to take, hold' plus -abilis 'able to be'.","cn":"capabilis 意为“能够接进来”。它由拉丁语 capere“拿住、握住”加 -abilis“能被……的”构成。"},{"era":"LATIN capere","en":"Capere meant 'to take, seize, grasp, hold'. It is the source of capture, captive, capacity, and capable.","cn":"capere 意为“拿、抓、握、持”。它是 capture、captive、capacity、capable 的共同来源。"},{"era":"SEMANTIC BROADENING","en":"From 'able to take in' came 'able to hold a task', then 'competent', then the general 'able to do'. The metaphor is a hand that can grip.","cn":"从“能接进来”生出“能接住一项任务”，再到“胜任”，最后到一般性的“能做到”。比喻核心是一只能握住东西的手。"},{"era":"LEGAL AND TECHNICAL","en":"Law uses capable for mental competence; engineering uses capable of being for what a material can undergo. Both keep the 'can take/hold' image.","cn":"法律用 capable 指心智能力；工程用 capable of being 指材料能经历什么。两者都保留“能拿住、能承受”的意象。"},{"era":"RELATED FAMILY","en":"Capable, capacity, and capture share capere. Capital is different: it comes from caput 'head', so capital and capable are not root relatives.","cn":"capable、capacity、capture 共享 capere。capital 不同：它来自 caput“头”，因此 capital 与 capable 并非同根词。"}]},"similar":{"note":{"en":"The first group shares the capere root; the second collects words for ability and competence with different strengths.","cn":"第一组共享 capere 词根；第二组收“能力、胜任”类词，强度不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"capability","ipa":"/ˌkeɪpəˈbɪləti/","tag":"derived noun","definition":"the ability or power to do something. It is the noun from capable.","definitionCN":"做某事的能力或力量。它是 capable 的名词派生。"},{"word":"incapable","ipa":"/ɪnˈkeɪpəbl/","tag":"negative form","definition":"not able to do something. In- 'not' + capable removes the ability to take hold.","definitionCN":"没有能力做某事。in-“不”+ capable，去掉“拿住”的能力。"},{"word":"capacious","ipa":"/kəˈpeɪʃəs/","tag":"same root, space","definition":"having a lot of room; spacious. It shares capere but describes how much can be held, not skill.","definitionCN":"空间很大的；宽敞的。它共享 capere，但描述能装多少，而不是技能。"}]},{"heading":"NEAR MEANING","entries":[{"word":"able","ipa":"/ˈeɪbl/","tag":"general ability","definition":"having the power or skill to do something. It is the broad everyday word; capable often adds competence or potential.","definitionCN":"有力量或技能做某事。它是最宽泛的日常词；capable 常附带“胜任”或“潜力”。"},{"word":"competent","ipa":"/ˈkɒmpɪtənt/","tag":"good enough for a role","definition":"having enough skill to do a job properly. It stresses meeting a standard, while capable can mean either competent or merely potential.","definitionCN":"具备足够技能把工作做好。它强调达到标准；capable 既可指胜任，也可仅指有潜力。"},{"word":"skilled","ipa":"/skɪld/","tag":"trained ability","definition":"having trained ability in a particular activity. It is narrower and more specific than capable.","definitionCN":"在某项活动中受过训练、有能力。它比 capable 更窄、更具体。"},{"word":"qualified","ipa":"/ˈkwælɪfaɪd/","tag":"formally entitled","definition":"having the official requirements for a job or activity. It stresses credentials rather than raw ability.","definitionCN":"具备某项工作或活动的正式条件。它强调资质，而不是原始能力。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: capere 'take, hold', -abilis 'able to be', and the family capacity/capture.","cn":"只用真实成分与同族词：capere“拿、握”、-abilis“能被……的”，以及 capacity/capture 词族。"},"normal":[{"en":"Capable is 'able to take hold': the hand can grip the task.","cn":"capable 是“能拿住”：手能抓住任务。"},{"en":"Capacity and capture share the same root: one is how much you can hold, the other is the act of taking.","cn":"capacity 与 capture 同根：一个是能装多少，一个是拿取的动作。"},{"en":"Capital is not from capere; it is from caput 'head'. Do not group capital with capable.","cn":"capital 不是来自 capere，而是来自 caput“头”。不要把 capital 归进 capable 的词族。"},{"en":"Incapable is in- + capable: the ability to take hold is removed.","cn":"incapable 是 in- + capable：拿住的能力被去掉了。"},{"en":"Legally capable means able to hold the consequences of one's decisions.","cn":"legally capable 指能承担自己决定的后果。"}],"abstract":[{"en":"Capable is about the handle, not the action: it asks whether something can be grasped at all.","cn":"capable 讲的是“把手”，不是动作：它问的是某物究竟能不能被抓住。"},{"en":"Ability can be latent. A material capable of storing heat may never have stored any.","cn":"能力可以是潜在的。一种能储热的材料，可能从未储存过热。"},{"en":"The word is morally neutral: the same capability can produce a cure or a weapon.","cn":"这个词在道德上是中性的：同一种能力可以造出解药，也可以造出武器。"}]},"examples":[{"en":"She is capable of handling the pressure of the job.","cn":"她有能力承受这份工作的压力。"},{"en":"The team is capable but needs better equipment.","cn":"团队很能干，但需要更好的设备。"},{"en":"This material is capable of withstanding extreme heat.","cn":"这种材料能承受极端高温。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“凯帕波”——凯帕波一把抓住（cap）任务，说“我拿得住” → capable 有能力的、能胜任的","word":"capable"},"root":"源自拉丁语 capere“拿住、握住”加 -abilis“能被……的”，经法语进入英语；核心是“能接住、能握住一项任务或条件”。","sensesIntro":{"en":"Eight senses of capable, all built on one gesture: a hand that can take hold of a task, a role, a material, a consequence, or an impression.","cn":"capable 的八个义项都建立在同一个动作上：一只手能抓住任务、职位、材料、后果或印象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand that can grip what is put in front of it.","cn":"核心意象：一只能够握住眼前之物的手。"},"chain":["CAPERE = TAKE","ABLE TO HOLD","ABLE TO DO","COMPETENT IN A ROLE","HAVING POTENTIAL","ABLE TO RECEIVE"],"branches":[{"senses":"S1 · S2","en":"ABILITY AND COMPETENCE: can do the task, and can hold the responsibilities of a position.","cn":"能力与胜任：做得到任务，也接得住职位的责任。"},{"senses":"S3 · S7","en":"POTENTIAL: what a material or business can take on, including room to grow.","cn":"潜力：材料或企业能承接什么，包括成长空间。"},{"senses":"S4","en":"MORAL NEUTRALITY: the ability to do something terrible is still an ability.","cn":"道德中性：做可怕事情的能力仍然是一种能力。"},{"senses":"S5","en":"TECHNICAL PASSIVE: capable of being formed, stored, or treated.","cn":"技术被动：能够被成型、储存或处理。"},{"senses":"S6 · S8","en":"RESPONSIBILITY AND RECEPTION: legal capacity to decide, and the mind's ability to receive impressions.","cn":"责任与接受：做决定的法律能力，以及心智接受印象的能力。"}]},"affixes":{"intro":{"en":"Capable is a borrowed adjective with the suffix -able. English builds nouns with -ity, adverbs with -ly, and the negative with in-.","cn":"capable 是带 -able 后缀的借入形容词。英语用 -ity 构名词、-ly 构副词，用 in- 构否定。"},"latinIntro":{"en":"Latin capere 'to take, hold' produced capabilis 'able to take in', capacitas 'capacity', and captura 'a taking'. English took all three branches.","cn":"拉丁语 capere“拿、握”派生出 capabilis“能接进来”、capacitas“容量”和 captura“拿取”。英语把这三支都借入了。"},"items":[{"word":"capability","structure":"capable + -ity (state noun)","meaning":"the ability or power to do something","meaningCN":"能力；才能（-ity 表示性质或状态）","example":"The system has the capability to learn from data.","exampleCN":"这个系统具备从数据中学习的能力。"},{"word":"capabilities","structure":"capability + -ies (plural)","meaning":"more than one ability or feature","meaningCN":"多项能力；功能（复数）","example":"The report lists the capabilities of the new model.","exampleCN":"报告列出了新模型的多项功能。"},{"word":"capably","structure":"capable + -ly (adverb)","meaning":"in a competent way","meaningCN":"能干地；有能力地（-ly 构成副词）","example":"She capably managed the crisis.","exampleCN":"她干练地处理了这场危机。"},{"word":"incapable","structure":"in- (not) + capable","meaning":"not able to do something","meaningCN":"无能力的；不能胜任的（in- 表示否定）","example":"The patient was incapable of consenting.","exampleCN":"病人无法作出同意。"},{"word":"incapability","structure":"in- + capability","meaning":"lack of ability","meaningCN":"无能力；不能（较少用）","example":"The audit revealed an incapability to meet the deadline.","exampleCN":"审计显示其无力按期完成。"},{"word":"incapacity","structure":"in- + capacity","meaning":"lack of physical or legal capacity","meaningCN":"无能力；法律上的无行为能力（in- 表示否定）","example":"The court declared incapacity to manage finances.","exampleCN":"法院宣布其无管理财务的能力。"},{"word":"incapacitate","structure":"in- + capaci(tas) + -ate (verb)","meaning":"to make someone unable to act","meaningCN":"使丧失能力；使无法行动","example":"The injury incapacitated him for weeks.","exampleCN":"伤势使他数周无法行动。"},{"word":"capacious","structure":"capac(itas) + -ious (adjective)","meaning":"roomy; able to hold much","meaningCN":"宽敞的；容量大的（-ious 构成形容词）","example":"The van has a capacious cargo area.","exampleCN":"这辆货车有宽敞的货厢。"},{"word":"capacity","structure":"capac(itas) + -ity (state noun)","meaning":"the amount that can be held, or the ability to do something","meaningCN":"容量；能力（-ity 表示状态）","example":"The stadium has a capacity of 60,000.","exampleCN":"体育场容量为六万人。"},{"word":"capture","structure":"capt(us) + -ure (act noun / verb)","meaning":"to take or seize; the act of taking","meaningCN":"捕获；夺取（-ure 表示行为）","example":"The camera captured the moment perfectly.","exampleCN":"相机完美地捕捉了那一刻。"}],"latinEntries":[{"word":"capere","structure":"Latin verb","meaning":"to take, seize, grasp, hold","meaningCN":"拿；抓；握住；占据"},{"word":"capabilis","structure":"capere + -abilis (able to be)","meaning":"able to take in, capable","meaningCN":"能接进来的；有能力的"}]}},{"word":"capacity","ipa_uk":"/kəˈpæsəti/","ipa_us":"/kəˈpæsəti/","definition_zh":"容量；能力；产能；职位","definition_en":"the amount something can hold, the ability to do something, the maximum output of a system, or a role a person fills","core_image":"一只被灌到刻线为止的容器：能装多少，一眼可见","scene":"The stadium has a seating capacity of 60,000.","sceneCN":"这里 capacity 是「场所最多容纳的人数」（第 2 个义项：空间的最大承载量）；句意：这座体育场可容纳六万名观众。场景要点：看台、满座的观众、入口计数牌。","pos":[{"tag":"n.","zh":"容量；能力；产能；职位"}],"collocations":[{"phrase":"seating capacity","zh":"座位容量"},{"phrase":"capacity for work","zh":"工作能力"},{"phrase":"production capacity","zh":"生产能力；产能"},{"phrase":"at full capacity","zh":"满负荷；满员"},{"phrase":"in the capacity of","zh":"以……的身份"}],"forms":[{"label":"复数（名词）","form":"capacities"}],"derivatives":[{"word":"capacious","pos":"adj.","zh":"容量大的；宽敞的"},{"word":"capacitance","pos":"n.","zh":"电容（电学）"},{"word":"capacitor","pos":"n.","zh":"电容器"},{"word":"incapacity","pos":"n.","zh":"无能力；无行为能力"}],"senses":[{"no":"01","title":"The volume a container can hold","titleCN":"容积：容器能装多少","definition":"the amount of liquid, gas, or material that a container can hold","definitionCN":"一个容器能装下的液体、气体或材料的量","example":"The tank has a capacity of 500 litres.","exampleCN":"这个罐子容量为五百升。","why":"Capacity comes from Latin capere 'to hold, take in'. The first sense is the inside room of a container — how much it can take in before it is full.","whyCN":"capacity 来自拉丁语 capere“装、接进来”。第一个义项就是容器的内部空间——装满之前能接进多少。"},{"no":"02","title":"The maximum number of people a place can hold","titleCN":"承载量：一个场所最多容纳多少","definition":"the largest number of people that a building, vehicle, or venue can hold","definitionCN":"建筑、交通工具或场所最多能容纳的人数","example":"The hall was filled beyond its stated capacity.","exampleCN":"大厅里的人数超过了标称容量。","why":"People replace liquid: the building is a container, and its capacity is the safe maximum it can take in.","whyCN":"人替换了液体：建筑是容器，capacity 是它能安全接进来的上限。"},{"no":"03","title":"The ability to do something","titleCN":"能力：能承担多少","definition":"the ability or power to do a task or deal with a demand","definitionCN":"完成任务或应对需求的能力或力量","example":"She has a great capacity for hard work.","exampleCN":"她有很强的吃苦能力。","why":"A person is also a container: capacity is how much effort, responsibility, or work they can take on.","whyCN":"人也是一个容器：capacity 是一个人能接住多少努力、责任或工作。"},{"no":"04","title":"Mental ability","titleCN":"心智容量：脑子能装多少","definition":"the ability of the mind to understand, remember, or learn","definitionCN":"心智理解、记忆或学习的能力","example":"Children have a remarkable capacity for language.","exampleCN":"儿童有惊人的语言能力。","why":"The mind is treated as a vessel that can take in knowledge. Capacity measures how much it can hold and process.","whyCN":"心智被当成一个能接进知识的容器。capacity 衡量它能装下、处理多少。"},{"no":"05","title":"Production or operating capacity","titleCN":"产能：系统最多能产出多少","definition":"the maximum amount a factory, machine, or system can produce or handle","definitionCN":"工厂、机器或系统能生产或处理的最大数量","example":"The plant is running at 90 percent capacity.","exampleCN":"工厂正以九成产能运转。","why":"A factory has a maximum intake and output. Beyond that point it cannot hold any more work, so its capacity is fixed.","whyCN":"工厂有最大投入与产出。超过那个点就装不下更多工作，所以它的 capacity 是固定的。"},{"no":"06","title":"Legal capacity or competence","titleCN":"法律能力：能承担法律后果","definition":"the legal ability to make decisions, sign contracts, or be responsible","definitionCN":"做出决定、签署合同或承担责任的法律能力","example":"The contract is void because the signer lacked capacity.","exampleCN":"该合同无效，因为签署人没有行为能力。","why":"Law asks whether a person can hold the consequences of an act. Capacity is that legal ability to take responsibility.","whyCN":"法律要问一个人能否接住行为的后果。capacity 就是这种承担法律责任的能力。"},{"no":"07","title":"A role or position","titleCN":"身份职位：以某种角色出现","definition":"a particular role or official position in which someone acts","definitionCN":"某人行事时所处的特定角色或正式职位","example":"She attended the meeting in her capacity as adviser.","exampleCN":"她以顾问身份出席了会议。","why":"A role is a slot a person can occupy. To act in that capacity is to act from inside that position.","whyCN":"职位是一个人能占据的槽位。以该 capacity 行事，就是从那个位置内部行动。"},{"no":"08","title":"Storage capacity in computing","titleCN":"存储容量：硬盘能装多少数据","definition":"the amount of data a storage device or system can hold","definitionCN":"存储设备或系统能容纳的数据量","example":"The drive offers two terabytes of capacity.","exampleCN":"这个硬盘提供两太字节的容量。","why":"Digital storage repeats the container image: data is poured in until the device is full.","whyCN":"数字存储重复了容器意象：数据被灌进去，直到设备装满。"},{"no":"09","title":"Battery or energy capacity","titleCN":"电池容量：能存多少电","definition":"the amount of electrical energy a battery or storage system can hold","definitionCN":"电池或储能系统能储存的电能量","example":"The battery capacity drops in cold weather.","exampleCN":"低温下电池容量会下降。","why":"A battery is a container for charge. Capacity is how much charge it can take in and give back.","whyCN":"电池是装电荷的容器。capacity 是它能接进并放回多少电荷。"},{"no":"10","title":"At full capacity","titleCN":"满负荷：装到不能再装","definition":"in the phrases at capacity or to capacity, meaning completely full or using all available power","definitionCN":"在短语 at capacity 或 to capacity 中，表示完全满员或用尽全部能力","example":"The hospital is already at capacity.","exampleCN":"医院已经满负荷运转。","why":"The phrase marks the exact point where the container can take nothing more. Capacity becomes a boundary, not just an amount.","whyCN":"这个短语标记容器再也装不下的那个点。capacity 在这里成了边界，而不只是一个数量。"}],"etymology":{"intro":{"en":"Capacity is the noun of holding. Latin capacitas named roominess, and English extended it from jars to stadiums, minds, factories, batteries, and legal responsibility.","cn":"capacity 是“装得下”的名词。拉丁语 capacitas 命名“宽敞、容量”，英语把它从罐子扩展到体育场、心智、工厂、电池和法律责任。"},"items":[{"era":"15C.","en":"Capacity is recorded in English in the 15th century, first as physical roominess and soon as ability of the mind.","cn":"capacity 在 15 世纪记录于英语，最初指物理上的容纳空间，很快又指心智能力。"},{"era":"LATIN capacitas","en":"Capacitas meant 'capacity, ability, roominess'. It was formed from capax 'able to hold much' plus the state suffix -itas.","cn":"capacitas 意为“容量、能力、宽敞”。它由 capax“能装很多的”加状态后缀 -itas 构成。"},{"era":"LATIN capax","en":"Capax came from capere 'to take, hold, seize'. A capacious thing is one that can take a great deal into itself.","cn":"capax 来自 capere“拿、装、抓”。容量大的东西，就是能往自己里面装很多的东西。"},{"era":"LATIN capere","en":"Capere is the shared root of capable, capture, captive, and capacity. The core gesture is a hand closing around something.","cn":"capere 是 capable、capture、captive、capacity 的共同词根。核心动作是一只手合拢、抓住某物。"},{"era":"SEMANTIC EXPANSION","en":"From containers came buildings, then minds, then machines and factories, then batteries and data drives. The image of an inside with a limit stayed constant.","cn":"从容器到建筑，再到心智、机器与工厂，再到电池与数据盘。内部空间有上限这一意象始终不变。"},{"era":"LEGAL AND ORGANIZATIONAL","en":"Law added the sense of legal ability, and organizations added 'role' in the phrase in the capacity of. Both treat a person as occupying a defined place.","cn":"法律增加了“法律能力”义，组织语境增加了 in the capacity of 中的“职位”义。两者都把一个人看作占据一个被定义的位置。"}]},"similar":{"note":{"en":"The first group shares the capere root; the second collects amount and ability words with different scopes.","cn":"第一组共享 capere 词根；第二组收“数量”与“能力”类词，范围不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"capacious","ipa":"/kəˈpeɪʃəs/","tag":"same root, adjective","definition":"roomy; able to hold much. It describes the container, while capacity names the amount.","definitionCN":"宽敞的；容量大的。它描述容器本身，capacity 则命名容量。"},{"word":"capacitance","ipa":"/kəˈpæsɪtəns/","tag":"technical relative","definition":"the ability of a system to store electric charge, measured in farads. It is the electrical specialization of capacity.","definitionCN":"系统储存电荷的能力，用法拉计量。它是 capacity 在电学中的专门化。"},{"word":"capacitor","ipa":"/kəˈpæsɪtə/","tag":"device noun","definition":"a component that stores electric charge. It is named from capacity, not from a different root.","definitionCN":"储存电荷的元件。它由 capacity 命名，不是另一个词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"volume","ipa":"/ˈvɒljuːm/","tag":"three-dimensional amount","definition":"the amount of space an object occupies. It overlaps with capacity for containers, but volume is the space itself, not the ability to hold.","definitionCN":"物体占据的空间量。描述容器时与 capacity 重叠，但 volume 是空间本身，不是容纳能力。"},{"word":"ability","ipa":"/əˈbɪləti/","tag":"general power","definition":"the power or skill to do something. It is broader and more personal than capacity, which often implies a limit or a maximum.","definitionCN":"做某事的力量或技能。它比 capacity 更宽泛、更个人化；capacity 常暗示上限或最大值。"},{"word":"capability","ipa":"/ˌkeɪpəˈbɪləti/","tag":"potential ability","definition":"the ability or potential to do something, often a feature of a system. It is close to capacity but less tied to a measurable maximum.","definitionCN":"做某事的能力或潜力，常指系统的功能。它接近 capacity，但较少绑定于可测量的上限。"},{"word":"throughput","ipa":"/ˈθruːpʊt/","tag":"rate of processing","definition":"the amount of work or data processed in a given time. It is a rate, while capacity is a maximum holding or output limit.","definitionCN":"单位时间内处理的工作或数据量。它是速率；capacity 是最大容纳或产出上限。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: capere 'hold', capax 'able to hold much', and the family capable/capture/capacitor.","cn":"只用真实成分与同族词：capere“装”、capax“能装很多”，以及 capable/capture/capacitor 词族。"},"normal":[{"en":"Capacity is how much a container can take in before it is full.","cn":"capacity 是一个容器装满之前能接进多少。"},{"en":"The same word measures a jar, a stadium, a mind, a factory, a battery, and a hard drive.","cn":"同一个词测量罐子、体育场、心智、工厂、电池和硬盘。"},{"en":"At capacity means the container can take nothing more.","cn":"at capacity 表示容器再也装不下了。"},{"en":"In the capacity of means acting from inside a particular role.","cn":"in the capacity of 表示从某个职位内部行事。"},{"en":"Capable and capacity share capere: one says 'can hold', the other names 'how much can be held'.","cn":"capable 与 capacity 共享 capere：一个说“能装”，一个命名“能装多少”。"}],"abstract":[{"en":"Capacity always implies a boundary: something inside, something outside, and a limit where the inside stops.","cn":"capacity 总暗示一条边界：里面有东西，外面有东西，内部停止处有一个上限。"},{"en":"A person's capacity is not fixed by one number; it changes with health, training, and demand.","cn":"一个人的 capacity 不由一个固定数字决定；它随健康、训练和需求变化。"},{"en":"To work at full capacity is to have no unused room left — efficient, but also fragile.","cn":"以满容量运转，就是没有剩余空间——高效，但也脆弱。"}]},"examples":[{"en":"The new reservoir will double the city's water capacity.","cn":"新水库将使城市供水能力翻倍。"},{"en":"He acted in his capacity as company secretary.","cn":"他以公司秘书的身份行事。"},{"en":"The factory is operating below capacity this month.","cn":"本月工厂开工不足。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“卡帕西提”——卡帕西提拿一只大桶，一直装到刻度线 → capacity 容量、能力","word":"capacity"},"root":"源自拉丁语 capacitas“容量、能力”，再由 capax“能装很多的”追溯到 capere“拿住、装下”；核心是“容器内部能接进多少”。","sensesIntro":{"en":"Ten senses of capacity, all built on one container image: an inside with a measurable limit on how much it can take in.","cn":"capacity 的十个义项都建立在一个容器意象上：内部空间，以及它能接进多少的可测上限。"},"semanticMap":{"core":{"en":"CORE IMAGE: a vessel filled to a marked line; capacity is the amount at that line.","cn":"核心意象：一只被灌到刻线的容器；capacity 就是刻线处的量。"},"chain":["CAPERE = HOLD","INSIDE SPACE","MAXIMUM INTAKE","MEASURABLE LIMIT","ABILITY TO TAKE ON","ROLE OR LEGAL STANDING"],"branches":[{"senses":"S1 · S2 · S8 · S9","en":"CONTAINERS: tanks, venues, hard drives, and batteries each hold a measurable amount.","cn":"容器：罐子、场馆、硬盘和电池都各自容纳可测的量。"},{"senses":"S3 · S4","en":"HUMAN ABILITY: how much work the body can take on, and how much the mind can understand.","cn":"人的能力：身体能承担多少工作，心智能理解多少。"},{"senses":"S5","en":"PRODUCTION: the maximum output a plant or system can sustain.","cn":"生产：工厂或系统能维持的最大产出。"},{"senses":"S6 · S7","en":"LEGAL AND ORGANIZATIONAL: ability to bear consequences, and a defined role.","cn":"法律与组织：承担后果的能力，以及被定义的角色。"},{"senses":"S10","en":"THE LIMIT POINT: at capacity means nothing more can be taken in.","cn":"临界点：at capacity 表示再也接不进更多。"}]},"affixes":{"intro":{"en":"Capacity is a Latin-derived noun with -ity. English builds technical relatives with -ance and -or, and the negative with in-.","cn":"capacity 是带 -ity 的拉丁来源名词。英语用 -ance、-or 造技术亲属词，用 in- 造否定。"},"latinIntro":{"en":"Latin capacitas came from capax, from capere. The family includes capabilis 'capable' and captura 'a taking'; English borrowed all three branches.","cn":"拉丁语 capacitas 来自 capax，再来自 capere。词族包括 capabilis“有能力的”和 captura“拿取”；英语把三支都借入了。"},"items":[{"word":"capacities","structure":"capacity + -ies (plural)","meaning":"more than one capacity or ability","meaningCN":"多种容量；多项能力（复数）","example":"The two models differ in their storage capacities.","exampleCN":"这两个型号的存储容量不同。"},{"word":"capacious","structure":"capac(itas) + -ious (adjective)","meaning":"roomy; able to hold much","meaningCN":"宽敞的；容量大的（-ious 构成形容词）","example":"The car has a capacious boot.","exampleCN":"这辆车的后备箱很宽敞。"},{"word":"capaciously","structure":"capacious + -ly (adverb)","meaning":"in a roomy way","meaningCN":"宽敞地；容量大地","example":"The hall was capaciously designed.","exampleCN":"大厅设计得很宽敞。"},{"word":"capacitance","structure":"capacity + -ance (technical noun)","meaning":"the ability to store electric charge","meaningCN":"电容；储存电荷的能力（-ance 构成名词）","example":"The circuit's capacitance is measured in farads.","exampleCN":"电路的电容用法拉计量。"},{"word":"capacitor","structure":"capacity + -or (device)","meaning":"a device that stores electric charge","meaningCN":"电容器（-or 表示装置）","example":"A capacitor smooths the voltage.","exampleCN":"电容器使电压平稳。"},{"word":"capacitate","structure":"capac(itas) + -ate (verb)","meaning":"to make able or capable","meaningCN":"使有能力；使具备条件（技术用语）","example":"The treatment capacitates the cells to divide.","exampleCN":"这种处理使细胞具备分裂能力。"},{"word":"incapacity","structure":"in- (not) + capacity","meaning":"lack of ability or legal competence","meaningCN":"无能力；法律上的无行为能力（in- 表示否定）","example":"The illness caused a temporary incapacity to work.","exampleCN":"疾病导致暂时无法工作。"},{"word":"overcapacity","structure":"over- (too much) + capacity","meaning":"capacity greater than what is needed or can be used","meaningCN":"产能过剩；容量过量（over- 表示“过度”）","example":"The industry suffers from overcapacity.","exampleCN":"该行业存在产能过剩。"},{"word":"undercapacity","structure":"under- (below) + capacity","meaning":"operating below the maximum possible level","meaningCN":"产能不足；低于容量运转","example":"The plant is running undercapacity.","exampleCN":"工厂开工不足。"},{"word":"capacity-building","structure":"capacity + building (compound noun)","meaning":"the process of developing skills and systems so an organization can do more","meaningCN":"能力建设（组织发展用语）","example":"The grant supports capacity-building in local charities.","exampleCN":"这笔拨款支持本地慈善机构的能力建设。"}],"latinEntries":[{"word":"capacitas","structure":"capax + -itas (state noun)","meaning":"capacity, roominess, ability","meaningCN":"容量；宽敞；能力"},{"word":"capax","structure":"capere + -ax (tending to)","meaning":"able to hold much; capacious","meaningCN":"能装很多的；容量大的"},{"word":"capere","structure":"Latin verb","meaning":"to take, hold, seize","meaningCN":"拿；装；握；抓"}]}},{"word":"capital","ipa_uk":"/ˈkæpɪtl/","ipa_us":"/ˈkæpɪtl/","definition_zh":"首都；资本；大写字母；死刑的","definition_en":"the city where a government sits, money used to produce more wealth, a large letter, or punishable by death","core_image":"一颗头（caput）被放在城市、账簿与字母表的最上方","scene":"The company needs more capital to open a second factory.","sceneCN":"这里 capital 是「用于投资的资本」（第 2 个义项：投入生产以获取更多财富的钱）；句意：公司需要更多资本来开第二家工厂。场景要点：账簿、厂房蓝图、投资协议。","pos":[{"tag":"n.","zh":"首都；资本；大写字母；柱头"},{"tag":"adj.","zh":"死刑的；首位的；主要的"}],"collocations":[{"phrase":"capital city","zh":"首都"},{"phrase":"raise capital","zh":"筹集资本"},{"phrase":"capital punishment","zh":"死刑"},{"phrase":"capital letter","zh":"大写字母"},{"phrase":"human capital","zh":"人力资本"}],"forms":[{"label":"复数（名词）","form":"capitals"}],"derivatives":[{"word":"capitalism","pos":"n.","zh":"资本主义"},{"word":"capitalist","pos":"n./adj.","zh":"资本家；资本主义的"},{"word":"capitalize","pos":"v.","zh":"资本化；把……大写"},{"word":"capitalization","pos":"n.","zh":"资本总额；大写"},{"word":"capitol","pos":"n.","zh":"（美国）州议会大厦；国会大厦"}],"senses":[{"no":"01","title":"The seat of government","titleCN":"首都：政府所在之城","definition":"the city where a country's or region's government is based","definitionCN":"国家或地区政府所在地的城市","example":"Paris is the capital of France.","exampleCN":"巴黎是法国的首都。","why":"Capital comes from Latin caput 'head'. The capital city is the head of the political body, the place from which the rest is directed.","whyCN":"capital 来自拉丁语 caput“头”。首都就是政治体的“头”，是发号施令、带动其余部分的地方。"},{"no":"02","title":"Money used to create more wealth","titleCN":"资本：用来生钱的钱","definition":"money or assets invested in production rather than spent on consumption","definitionCN":"投入生产而非用于消费的钱或资产","example":"The start-up raised capital from private investors.","exampleCN":"这家初创公司从私人投资者那里筹集了资本。","why":"In medieval Latin, capitale meant the principal sum of a debt or fund, as opposed to interest. It is the 'head' amount from which later gains grow.","whyCN":"在中世纪拉丁语中，capitale 指债务或资金的本金，相对于利息。它是那个“头”数，后来的收益从它长出来。"},{"no":"03","title":"Financial capital as a factor of production","titleCN":"金融资本：与劳动相对的生产要素","definition":"in economics, the money and assets used alongside labour to produce goods and services","definitionCN":"经济学中与劳动一起用来生产商品和服务的钱与资产","example":"The model compares returns to capital and returns to labour.","exampleCN":"该模型比较资本回报与劳动回报。","why":"Economics turns the head-sum into an abstract factor: capital is the accumulated means of production, the standing stock from which output flows.","whyCN":"经济学把“头”数抽象为一个要素：资本是积累起来的生产手段，是产出由之流出的存量。"},{"no":"04","title":"A capital letter","titleCN":"大写字母：字母表里的“头”","definition":"the large form of a letter, used at the start of sentences and for proper names","definitionCN":"字母的大写形式，用于句首和专有名词","example":"Write the first word with a capital letter.","exampleCN":"第一个词要用大写字母。","why":"The large letter was called capitalis because it stood at the head of a word or line, just as a head tops a body.","whyCN":"大写字母被称为 capitalis，因为它站在词或行的“头部”，就像头在身体顶端。"},{"no":"05","title":"Punishable by death","titleCN":"死刑的：涉及夺去头颅","definition":"in law, describing an offence or punishment that involves the death penalty","definitionCN":"法律中描述涉及死刑的罪行或刑罚","example":"The country abolished capital punishment in 1998.","exampleCN":"该国于 1998 年废除了死刑。","why":"Capital punishment was literally punishment of the head: the old phrase capital crime meant a crime for which one could lose one's head.","whyCN":"死刑字面上是对“头”的刑罚：旧短语 capital crime 指可能让人掉脑袋的罪。"},{"no":"06","title":"Chief or principal","titleCN":"首要的：排在最前面","definition":"most important or principal, used in formal or old-fashioned contexts","definitionCN":"最重要或主要的，用于正式或旧式语境","example":"The capital error of the plan was its cost.","exampleCN":"这个计划的首要错误是成本。","why":"Anything at the head of a ranking is capital. The adjective preserves the old sense of 'of the head, chief'.","whyCN":"排在序列最前面的东西就是 capital。形容词保留了“属于头部的、首要的”这一旧义。"},{"no":"07","title":"Share capital or stock","titleCN":"股本：公司发行股份形成的资本","definition":"the money a company raises by issuing shares","definitionCN":"公司通过发行股份筹集的资金","example":"The company increased its share capital by issuing new stock.","exampleCN":"公司通过发行新股增加了股本。","why":"The principal fund of a company is its capital. Shares divide that head-sum into portions.","whyCN":"公司的主资金就是它的 capital。股份把那笔“头”数分成若干份。"},{"no":"08","title":"Human capital","titleCN":"人力资本：人的技能也是本钱","definition":"the skills, knowledge, and health of people treated as an economic asset","definitionCN":"把人的技能、知识和健康当作经济资产","example":"Education is an investment in human capital.","exampleCN":"教育是对人力资本的投资。","why":"Economics extends the 'stock that produces more' image from money to people: skills are a fund that yields future output.","whyCN":"经济学把“能产出更多的存量”这一意象从钱扩展到人：技能是一笔能带来未来产出的本钱。"},{"no":"09","title":"Social capital","titleCN":"社会资本：关系网络也是资源","definition":"the value of social networks, trust, and cooperation as a resource","definitionCN":"社会网络、信任与合作作为资源的价值","example":"Strong social capital helps communities recover after disasters.","exampleCN":"雄厚的社会资本帮助社区在灾后恢复。","why":"Sociology applies the same model to relationships: trust and connections are a stock that can be drawn on later.","whyCN":"社会学把同一模型用到关系上：信任与连接是一笔日后可以支取的存量。"},{"no":"10","title":"The head of a column","titleCN":"柱头：建筑柱子顶端的“头”","definition":"in architecture, the decorated top of a column or pillar","definitionCN":"建筑中柱子顶端装饰性的“头”","example":"The columns have carved stone capitals.","exampleCN":"这些柱子的柱头是雕花石材。","why":"This is the most literal survival of caput: the capital is the head of the column, the part at the top.","whyCN":"这是 caput 最字面的留存：capital 就是柱子的“头”，位于顶端的部分。"}],"etymology":{"intro":{"en":"Capital comes from Latin caput 'head'. A capital city, a capital letter, a capital sum, a capital crime, and a column's capital are all 'heads' of different bodies.","cn":"capital 来自拉丁语 caput“头”。首都、大写字母、本金、死罪、柱头，都是不同“身体”的“头”。"},"items":[{"era":"LATIN caput","en":"Caput meant 'head'. Its genitive capitis supplies the stem capital- seen in capitalis 'of the head'.","cn":"caput 意为“头”。它的属格 capitis 提供词干 capital-，见于 capitalis“属于头的”。"},{"era":"LATIN capitalis","en":"Capitalis meant 'of or pertaining to the head', and by extension 'chief, principal'. A capital letter or capital city is the 'head' of its line or region.","cn":"capitalis 意为“属于头的”，引申为“首要的、主要的”。大写字母或首都，就是其行或地区的“头”。"},{"era":"MEDIEVAL LATIN capitale","en":"Capitale, the neuter of capitalis, came to mean 'stock, principal sum' — the head amount of money, as opposed to interest. This is the source of the financial sense.","cn":"capitalis 的中性形式 capitale 逐渐指“本金、本钱”——相对于利息的那笔“头”数。这是财务义的来源。"},{"era":"13C.–16C. ENGLISH","en":"English first used capital for 'of the head' and 'chief'; the financial noun and the capital city sense developed later, through French and commercial Latin.","cn":"英语最初用 capital 表示“属于头的”和“首要的”；财务名词与首都义稍后经法语和商业拉丁语发展出来。"},{"era":"LEGAL SENSE","en":"Capital crime and capital punishment preserve the old literal link: the penalty touches the head, the seat of life.","cn":"capital crime 与 capital punishment 保留了旧的直白联系：刑罚触及头部，即生命所在。"},{"era":"RELATED FAMILY","en":"Capital, captain, decapitate, and cabbage all come from caput. Capable, capacity, and capture do not: they come from capere 'to take'. Capitol is often linked to caput, but the connection is not certain.","cn":"capital、captain、decapitate、cabbage 都来自 caput。capable、capacity、capture 不是：它们来自 capere“拿”。Capitol 常被联系到 caput，但这种关系并不确定。"}]},"similar":{"note":{"en":"The first group shares caput or the capital family; the second collects money and city words with different scopes.","cn":"第一组共享 caput 或 capital 词族；第二组收“钱”与“城市”类词，范围不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"capitalism","ipa":"/ˈkæpɪtəlɪzəm/","tag":"derived noun","definition":"an economic system based on private ownership of capital. It is capital + -ism.","definitionCN":"以资本私有制为基础的经济制度。它是 capital + -ism。"},{"word":"capitalist","ipa":"/ˈkæpɪtəlɪst/","tag":"person or adjective","definition":"a person who owns capital, or an adjective describing that system. The -ist suffix marks the owner or supporter.","definitionCN":"拥有资本的人，或描述该制度的形容词。-ist 标记所有者或支持者。"},{"word":"capitalize","ipa":"/ˈkæpɪtəlaɪz/","tag":"verb","definition":"to write with a capital letter, or to turn something into capital. The two senses follow the letter and the money branches.","definitionCN":"用大写字母书写，或把某物转化为资本。两个义项分别沿字母与金钱两支。"},{"word":"capitol","ipa":"/ˈkæpɪtl/","tag":"spelling neighbour","definition":"a building where a legislature meets. It is often linked to caput 'head', but the historical connection is not fully certain.","definitionCN":"立法机关开会的大楼。它常被联系到 caput“头”，但历史联系并不完全确定。"}]},{"heading":"NEAR MEANING","entries":[{"word":"funds","ipa":"/fʌndz/","tag":"available money","definition":"money available for spending or investing. It is more concrete and spendable than capital, which often implies productive investment.","definitionCN":"可用于支出或投资的钱。它比 capital 更具体、更可花；capital 常暗示生产性投入。"},{"word":"assets","ipa":"/ˈæsets/","tag":"things of value","definition":"everything of value owned by a person or company. Assets include capital goods but also property that may not be productive.","definitionCN":"个人或公司拥有的全部有价值之物。assets 包括资本品，也包括未必生产性的财产。"},{"word":"principal","ipa":"/ˈprɪnsəpl/","tag":"head sum","definition":"the original sum of a loan, excluding interest; also 'chief'. It shares the 'head' image with capital.","definitionCN":"贷款的原始本金，不含利息；也指“首要的”。它与 capital 共享“头”的意象。"},{"word":"metropolis","ipa":"/məˈtrɒpəlɪs/","tag":"chief city","definition":"a large and important city. It is not necessarily a political capital, though it is often the economic head of a region.","definitionCN":"规模大、地位重要的城市。它不一定是政治首都，但常是一个地区的经济“头”。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: Latin caput 'head', the family captain/decapitate, and the financial branch capitale 'principal sum'.","cn":"只用真实成分与同族词：拉丁语 caput“头”、captain/decapitate 词族，以及财务分支 capitale“本金”。"},"normal":[{"en":"Capital is built on caput 'head': a capital city is the head of a country, a capital letter the head of a word.","cn":"capital 建立在 caput“头”上：首都是国家的头，大写字母是词的头。"},{"en":"Capital punishment touches the head; the old phrase capital crime meant a crime that could cost you your head.","cn":"死刑触及头部；旧短语 capital crime 指可能让你掉脑袋的罪。"},{"en":"The financial capital is the 'head' sum of money, the principal from which interest grows.","cn":"财务上的 capital 是那笔“头”钱，是利息由之生长的本金。"},{"en":"Capital and capable look alike but are not related: capital is caput 'head', capable is capere 'take'.","cn":"capital 与 capable 看起来相近，却不同源：capital 是 caput“头”，capable 是 capere“拿”。"},{"en":"The capital of a column is literally the column's head.","cn":"柱子的 capital 字面上就是柱子的“头”。"}],"abstract":[{"en":"Capital always marks the top or the source: the head of a body, the head of a word, the head of a sum.","cn":"capital 总标记“顶端”或“源头”：身体的头、词的头、一笔钱的头。"},{"en":"The financial sense turns a spatial image into an economic one: what is at the head is the stock from which the rest flows.","cn":"财务义把空间意象变成经济意象：位于“头”上的，是其余部分由之流出的存量。"},{"en":"The same word can mean a city, a letter, a sum, and a death sentence because each is a head in a different system.","cn":"同一个词可以指城市、字母、金额和死刑，因为每一个都是不同系统里的“头”。"}]},"examples":[{"en":"The capital moved from the coast to an inland city.","cn":"首都从沿海迁到了内陆城市。"},{"en":"The firm needs working capital to pay its suppliers.","cn":"公司需要营运资本来支付供应商。"},{"en":"Begin each sentence with a capital letter.","cn":"每个句子都以大写字母开头。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“开皮头”——开皮头把“头”放在最上面：城市之头、字母之头、钱之头 → capital 首都、资本、大写","word":"capital"},"root":"源自拉丁语 caput“头”及其形容词 capitalis；核心是“位于顶端、作为首要或本源的部分”，由此分化为首都、大写字母、本金、死刑与柱头。","sensesIntro":{"en":"Ten senses of capital, all built on caput 'head': the head city, the head letter, the head sum, the head crime, the head of a column, and the head forms of human and social wealth.","cn":"capital 的十个义项都建立在 caput“头”上：头城、头字母、头笔钱、掉头的罪、柱头，以及人力与社会财富的“头”。"},"semanticMap":{"core":{"en":"CORE IMAGE: a head placed at the top of a body — the chief or source part.","cn":"核心意象：放在身体顶端的头——首要或本源的部分。"},"chain":["CAPUT = HEAD","TOP OF A BODY","CHIEF OR PRINCIPAL","HEAD CITY AND HEAD LETTER","PRINCIPAL SUM OF MONEY","HEAD AS LIFE OR SOURCE"],"branches":[{"senses":"S1 · S6 · S10","en":"POSITION: the head city, the chief thing, and the head of a column.","cn":"位置：首都、首要之物、柱头。"},{"senses":"S2 · S3 · S7","en":"MONEY: the principal sum, financial capital as a factor, and share capital.","cn":"金钱：本金、作为生产要素的金融资本、股本。"},{"senses":"S4","en":"WRITING: the large letter that stands at the head of a word or sentence.","cn":"书写：站在词或句首的大写字母。"},{"senses":"S5","en":"DEATH: capital punishment touches the head, the seat of life.","cn":"死亡：死刑触及头部，生命所在。"},{"senses":"S8 · S9","en":"EXTENDED STOCK: human skills and social trust treated as capital that yields future returns.","cn":"扩展存量：人的技能与社会信任被当作能带来未来回报的资本。"}]},"affixes":{"intro":{"en":"Capital is a Latin adjective and noun. English adds -ism, -ist, -ize, and -ization, and forms compounds such as human capital.","cn":"capital 是拉丁形容词兼名词。英语加 -ism、-ist、-ize、-ization，并构成 human capital 这类复合词。"},"latinIntro":{"en":"Latin caput 'head' gives capitalis 'of the head' and capitale 'principal sum'. The financial branch grew from the idea of the head amount of a loan.","cn":"拉丁语 caput“头”给出 capitalis“属于头的”和 capitale“本金”。财务分支从“贷款的头笔金额”这一观念生长出来。"},"items":[{"word":"capitals","structure":"capital + -s (plural)","meaning":"more than one capital city, letter, or sum","meaningCN":"多个首都、大写字母或资本项（复数）","example":"The region has three historic capitals.","exampleCN":"该地区有三个历史古都。"},{"word":"capitalism","structure":"capital + -ism (system)","meaning":"an economic system based on private capital","meaningCN":"资本主义（-ism 表示制度或主义）","example":"Industrial capitalism changed the city.","exampleCN":"工业资本主义改变了这座城市。"},{"word":"capitalist","structure":"capital + -ist (person / adjective)","meaning":"an owner of capital, or relating to capitalism","meaningCN":"资本家；资本主义的（-ist 表示人或属性）","example":"The factory was owned by a wealthy capitalist.","exampleCN":"这家工厂归一位富有的资本家所有。"},{"word":"capitalistic","structure":"capitalist + -ic (adjective)","meaning":"characteristic of capitalism","meaningCN":"资本主义性质的（-ic 构成形容词）","example":"The reforms had a capitalistic direction.","exampleCN":"改革带有资本主义方向。"},{"word":"capitalize","structure":"capital + -ize (verb)","meaning":"to write in capitals, or to convert into capital","meaningCN":"用大写书写；资本化（-ize 构成动词）","example":"Capitalize the first letter of each name.","exampleCN":"每个名字的首字母要大写。"},{"word":"capitalization","structure":"capitalize + -ation (process noun)","meaning":"the act of writing in capitals, or the total capital of a company","meaningCN":"大写；资本总额（-ation 表示过程或结果）","example":"The company's capitalization reached one billion dollars.","exampleCN":"公司资本总额达到十亿美元。"},{"word":"recapitalization","structure":"re- (again) + capitalization","meaning":"a restructuring of a company's capital","meaningCN":"资本重组（re- 表示“再次”）","example":"The bank underwent recapitalization after the crisis.","exampleCN":"危机后银行进行了资本重组。"},{"word":"decapitalize","structure":"de- (remove) + capitalize","meaning":"to reduce a company's capital","meaningCN":"减少资本；去资本化（de- 表示去除）","example":"The board decided to decapitalize the subsidiary.","exampleCN":"董事会决定减少子公司的资本。"},{"word":"capital-intensive","structure":"capital + intensive (compound adjective)","meaning":"requiring a lot of capital relative to labour","meaningCN":"资本密集型的","example":"Steel production is a capital-intensive industry.","exampleCN":"钢铁生产是资本密集型产业。"},{"word":"human capital","structure":"human + capital (compound noun)","meaning":"people's skills and knowledge treated as economic capital","meaningCN":"人力资本","example":"The country invests heavily in human capital.","exampleCN":"该国大力投资人力资本。"}],"latinEntries":[{"word":"caput","structure":"Latin noun, genitive capitis","meaning":"head","meaningCN":"头"},{"word":"capitalis","structure":"caput + -alis (relating to)","meaning":"of the head; chief, principal","meaningCN":"属于头的；首要的；主要的"},{"word":"capitale","structure":"neuter of capitalis","meaning":"principal sum, stock, capital","meaningCN":"本金；存货；资本"}]}},{"word":"capture","ipa_uk":"/ˈkæptʃə/","ipa_us":"/ˈkæptʃər/","definition_zh":"捕获；俘获；夺取；捕捉","definition_en":"to catch a person or animal, take a place by force, record an image or sound, or attract and hold something","core_image":"一只手合拢，抓住正在移动的东西","scene":"The camera captured the exact moment the bird took flight.","sceneCN":"这里 capture 是「记录下画面」（第 3 个义项：用设备捕捉影像或声音）；句意：相机捕捉到了鸟起飞的瞬间。场景要点：相机取景框、起飞的鸟、按下快门的瞬间。","pos":[{"tag":"vt.","zh":"捕获；俘获；夺取；捕捉；吸引"},{"tag":"n.","zh":"捕获；俘获；夺取"}],"collocations":[{"phrase":"capture a moment","zh":"捕捉一个瞬间"},{"phrase":"capture the attention","zh":"吸引注意力"},{"phrase":"capture market share","zh":"抢占市场份额"},{"phrase":"capture data","zh":"采集数据"},{"phrase":"capture the essence","zh":"抓住本质"}],"forms":[{"label":"三单（he/she/it）","form":"captures"},{"label":"过去式（已经发生）","form":"captured"},{"label":"过去分词（完成／被动）","form":"captured"},{"label":"现在分词（进行体）","form":"capturing"},{"label":"复数（名词）","form":"captures"}],"derivatives":[{"word":"captor","pos":"n.","zh":"捕获者；俘获者"},{"word":"captive","pos":"n./adj.","zh":"俘虏；被俘的"},{"word":"captivity","pos":"n.","zh":"囚禁；被俘状态"},{"word":"captivate","pos":"v.","zh":"迷住；使着迷"}],"senses":[{"no":"01","title":"Seize a person or animal","titleCN":"擒获：抓住人或动物","definition":"to catch and hold a person or animal, especially by force or skill","definitionCN":"抓住并控制人或动物，尤指用武力或技巧","example":"The rescuers captured the injured eagle safely.","exampleCN":"救援人员安全地捕获了受伤的老鹰。","why":"Capture comes from Latin capere 'to take, seize'. The first sense is the literal closing of a hand or net around a living thing.","whyCN":"capture 来自拉丁语 capere“拿、抓”。第一个义项就是手或网合拢、罩住一个活物。"},{"no":"02","title":"Take a place or object by force","titleCN":"夺取：用力量拿下地点或物体","definition":"to take control of a place, building, or object, usually in war or conflict","definitionCN":"通常在战争或冲突中控制一个地点、建筑或物体","example":"The army captured the bridge before dawn.","exampleCN":"军队在黎明前夺取了那座桥。","why":"The thing taken is now larger than a hand can hold: a bridge, a city. The same act of seizing is scaled up to territory.","whyCN":"被拿下的东西已经大到一只手握不住：一座桥、一座城。同一个“抓取”动作被放大到领土尺度。"},{"no":"03","title":"Record an image or sound","titleCN":"捕捉影像：把瞬间固定下来","definition":"to record a scene, image, or sound with a camera, microphone, or other device","definitionCN":"用相机、麦克风或其他设备记录景象、图像或声音","example":"The microphone captured every word of the interview.","exampleCN":"麦克风录下了采访中的每一句话。","why":"A camera 'takes' light the way a hand takes an object: the moment is caught and held in a recording.","whyCN":"相机“拿住”光线，就像手抓住物体：瞬间被捉住并保存在记录里。"},{"no":"04","title":"Attract and hold attention","titleCN":"吸引注意：把目光抓住","definition":"to attract and hold someone's attention, interest, or imagination","definitionCN":"吸引并保持某人的注意、兴趣或想象","example":"The opening scene captured the audience's imagination.","exampleCN":"开场一幕抓住了观众的想象力。","why":"Attention is treated as something that can be caught. Once it is seized, the audience cannot easily let it go.","whyCN":"注意力被当作可以被抓住的东西。一旦被擒住，观众就不容易放手。"},{"no":"05","title":"Win market share or customers","titleCN":"抢占市场：把份额拿到手","definition":"to gain a share of a market, audience, or group of customers","definitionCN":"取得市场份额、受众或客户群","example":"The brand captured a third of the youth market.","exampleCN":"该品牌拿下了三分之一的青年市场。","why":"Business competition is a hunt: customers and share are the prize, and capturing them means taking them into your own territory.","whyCN":"商业竞争是一场狩猎：客户和份额是猎物，capture 它们就是把它们带进自己的地盘。"},{"no":"06","title":"Collect and store data or energy","titleCN":"采集：把数据或能量收进来","definition":"to collect data, particles, or energy and store or convert them","definitionCN":"收集数据、粒子或能量并储存或转化","example":"The sensor captures temperature readings every minute.","exampleCN":"传感器每分钟采集一次温度读数。","why":"A system takes in what flows past it. Capture here is technical intake: the data or energy is caught before it disappears.","whyCN":"系统把流过身边的东西接进来。这里的 capture 是技术性摄入：在数据或能量消失前把它们抓住。"},{"no":"07","title":"Express the essence or mood","titleCN":"抓住神韵：把本质表达出来","definition":"to represent the essential quality or atmosphere of something successfully","definitionCN":"成功地表现某物的本质或氛围","example":"The novel captures the mood of the city after the war.","exampleCN":"这部小说抓住了战后这座城市的气氛。","why":"What is captured is not a physical object but a quality. The image works because the essence is treated as something that can be caught and held.","whyCN":"被抓住的不是实物，而是一种品质。这个意象成立，是因为“本质”被当成可以被捉住、握住的东西。"},{"no":"08","title":"Capture a piece in chess","titleCN":"国际象棋：吃掉一子","definition":"in chess, to remove an opponent's piece from the board by moving onto its square","definitionCN":"国际象棋中，通过移动到对方棋子所在格而将其移出棋盘","example":"She captured his queen with a knight.","exampleCN":"她用马吃掉了他的后。","why":"The board is a small territory, and a piece is taken by force. The word's military sense shrinks to the size of a square.","whyCN":"棋盘是一小片领土，棋子被武力拿走。这个词的军事义缩小到一个格子的尺寸。"},{"no":"09","title":"Nuclear or particle capture","titleCN":"核捕获：粒子被吸收","definition":"in physics, the process in which a particle is absorbed by an atomic nucleus or another particle","definitionCN":"物理学中粒子被原子核或另一粒子吸收的过程","example":"Neutron capture can turn one isotope into another.","exampleCN":"中子俘获可以把一种同位素变成另一种。","why":"At the smallest scale, one particle takes in another and holds it. The hand image becomes an atomic nucleus absorbing a passing neutron.","whyCN":"在最小尺度上，一个粒子把另一个接进来并留住。手的意象变成原子核吸收经过的中子。"}],"etymology":{"intro":{"en":"Capture is the noun and verb of taking. Its root, Latin capere, is the same one behind capable and capacity, and its history is the spread of 'seize' from people to places, images, attention, data, and particles.","cn":"capture 是“拿取”的名词与动词。它的词根 capere 也是 capable 与 capacity 的来源；它的历史，就是“抓住”从人扩展到地点、影像、注意力、数据和粒子。"},"items":[{"era":"MID-14C.","en":"The noun capture is first recorded in the mid-14th century, meaning 'the act of taking or seizing'. The verb followed later, in the 16th century.","cn":"名词 capture 最早记录于 14 世纪中期，意为“拿取、夺取的行为”。动词形式较晚，在 16 世纪出现。"},{"era":"LATIN captura","en":"Captura meant 'a taking, seizure', from captus, the past participle of capere 'to take'.","cn":"captura 意为“拿取、夺取”，来自 captus，即 capere“拿”的过去分词。"},{"era":"LATIN capere","en":"Capere meant 'to take, seize, grasp, hold'. It also gives capable, capacity, captive, and captor.","cn":"capere 意为“拿、抓、握、持”。它也给出 capable、capacity、captive、captor。"},{"era":"MILITARY TO VISUAL","en":"From seizing people and places, capture extended in the 20th century to recording: a camera captures an image, a microphone captures a sound.","cn":"从擒获人和夺取地点，capture 在 20 世纪扩展到记录：相机捕捉影像，麦克风捕捉声音。"},{"era":"ATTENTION AND MARKETS","en":"The same metaphor produced capture the attention and capture the market: attention and customers are treated as prizes that can be taken.","cn":"同一个比喻又产生 capture the attention 与 capture the market：注意力与客户被当作可以拿走的战利品。"},{"era":"TECHNICAL SENSES","en":"Data capture, carbon capture, and neutron capture all use the same image at different scales: something flowing past is caught and held.","cn":"data capture、carbon capture、neutron capture 都在不同尺度使用同一意象：流经的东西被抓住并留住。"}]},"similar":{"note":{"en":"The first group shares the capere root; the second collects seizing words with different degrees of force and legality.","cn":"第一组共享 capere 词根；第二组收“抓取”类词，力度与合法性不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"captive","ipa":"/ˈkæptɪv/","tag":"same root, person or state","definition":"a person or animal held prisoner; also the adjective 'kept in confinement'. It is the thing taken, while capture is the act.","definitionCN":"被关押的人或动物；也作形容词“被囚禁的”。它是被拿住的对象，capture 是动作。"},{"word":"captor","ipa":"/ˈkæptə/","tag":"same root, person who","definition":"a person who captures someone. The -or suffix marks the one doing the taking.","definitionCN":"捕获他人的人。-or 后缀标记执行拿取的人。"},{"word":"recapture","ipa":"/ˌriːˈkæptʃə/","tag":"prefix form","definition":"to capture again, or to recover something lost. Re- 'again' + capture.","definitionCN":"再次捕获；夺回失去之物。re-“再次”+ capture。"}]},{"heading":"NEAR MEANING","entries":[{"word":"seize","ipa":"/siːz/","tag":"sudden force","definition":"to take hold of something quickly and forcefully. It stresses the speed and force of the grab more than capture does.","definitionCN":"迅速而有力地抓住某物。它比 capture 更强调抓取的速度与力量。"},{"word":"catch","ipa":"/kætʃ/","tag":"everyday taking","definition":"to take hold of something moving, or to discover someone doing something. It is the everyday word; capture is more formal and often larger in scale.","definitionCN":"抓住移动中的东西，或发现某人正在做某事。它是最日常的词；capture 更正式，规模常更大。"},{"word":"grab","ipa":"/ɡræb/","tag":"quick physical grab","definition":"to take something roughly and quickly with the hand. It is physical, informal, and small in scale.","definitionCN":"用手粗暴、迅速地抓住某物。它具体、口语、规模小。"},{"word":"apprehend","ipa":"/ˌæprɪˈhend/","tag":"legal arrest","definition":"to arrest someone, or to understand something. In the legal sense it is the formal word for capturing a suspect.","definitionCN":"逮捕某人，或理解某事。法律义中是“抓获嫌疑人”的正式说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: capere 'take', captus 'taken', captura 'a taking', and the pair captive/captor.","cn":"只用真实成分与同族词：capere“拿”、captus“被拿的”、captura“拿取”，以及 captive/captor 这对词。"},"normal":[{"en":"Capture is the act; captive is the person held; captor is the person holding.","cn":"capture 是动作，captive 是被关押者，captor 是关押者。"},{"en":"Capable, capacity, and capture share capere: able to hold, how much can be held, and the act of taking hold.","cn":"capable、capacity、capture 共享 capere：能握住、能装多少、以及握住的动作。"},{"en":"A camera captures light the way a hand captures an object: the moment is taken and stored.","cn":"相机捕捉光线，就像手抓住物体：瞬间被拿走并保存。"},{"en":"Capture the market means taking customers into your territory, not literally imprisoning them.","cn":"capture the market 是把客户带进自己的地盘，不是真的把他们关起来。"},{"en":"In chess, capture is the military sense reduced to one square.","cn":"国际象棋里的 capture，是军事义缩小到一个格子。"}],"abstract":[{"en":"Every capture involves a flow that is stopped: a running animal, a passing moment, a moving customer, a streaming particle.","cn":"每一次 capture 都涉及一个被停住的流动：奔跑的动物、流逝的瞬间、移动的客户、流过的粒子。"},{"en":"The word moves from force to attention to data without changing its shape: something is taken and kept.","cn":"这个词从武力走到注意力再到数据，形状没变：某物被拿走并留住。"},{"en":"What is captured may be a body, an image, a mood, or a value; the common thread is that it did not stay where it was.","cn":"被捕获的可以是身体、影像、情绪或数值；共同点是它没有留在原来的地方。"}]},"examples":[{"en":"The police captured the suspect after a short chase.","cn":"警方在短暂追捕后抓获了嫌疑人。"},{"en":"The photograph captures the light of early morning.","cn":"这张照片捕捉到了清晨的光线。"},{"en":"The company aims to capture a larger share of the online market.","cn":"公司旨在抢占更大的线上市场份额。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“开普车”——开普车追上去，一把将逃跑的人抓住 → capture 捕获、捕捉","word":"capture"},"root":"源自拉丁语 captura“拿取”，来自 captus（capere 的过去分词）“被拿的”；核心是“合拢手、把移动的东西抓住并留住”。","sensesIntro":{"en":"Nine senses of capture, all built on one gesture: something moving is taken and held — a body, a place, an image, attention, a market, data, a mood, a chess piece, or a particle.","cn":"capture 的九个义项都建立在同一个动作上：抓住并留住正在移动的东西——身体、地点、影像、注意力、市场、数据、情绪、棋子或粒子。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand closing around something that is moving away.","cn":"核心意象：一只手合拢，抓住正在离开的东西。"},"chain":["CAPERE = TAKE","HAND CLOSES","OBJECT HELD","CONTROL GAINED","FLOW STOPPED","VALUE OR MEANING SECURED"],"branches":[{"senses":"S1 · S2 · S8","en":"FORCE: catching a living being, taking a place, and removing a chess piece.","cn":"武力：擒获活物、夺取地点、吃掉棋子。"},{"senses":"S3 · S7","en":"REPRESENTATION: recording an image or sound, and expressing a mood or essence.","cn":"再现：记录影像或声音，表现情绪或本质。"},{"senses":"S4","en":"ATTENTION: interest is caught and held like a moving object.","cn":"注意力：兴趣像移动的物体一样被抓住并留住。"},{"senses":"S5","en":"MARKET: customers and share are taken into one's territory.","cn":"市场：客户与份额被带进自己的地盘。"},{"senses":"S6 · S9","en":"TECHNICAL INTAKE: data, energy, or particles are collected before they pass.","cn":"技术摄入：数据、能量或粒子在流走之前被收集。"}]},"affixes":{"intro":{"en":"Capture is a Latin-derived noun and verb. English adds -ed, -ing, -or, and re-, and keeps the related adjective captive.","cn":"capture 是拉丁来源的名词兼动词。英语加 -ed、-ing、-or、re-，并保留相关形容词 captive。"},"latinIntro":{"en":"The Latin family is capere 'take', captus 'taken', captura 'a taking'. English borrowed the noun and verb, then built captor, captive, and captivate.","cn":"拉丁词族是 capere“拿”、captus“被拿的”、captura“拿取”。英语借入名词与动词，再构成 captor、captive、captivate。"},"items":[{"word":"captures","structure":"capture + -s (plural / third person)","meaning":"multiple captures, or 'it captures'","meaningCN":"多次捕获；或动词第三人称单数","example":"The study captures data from three sites.","exampleCN":"这项研究从三个地点采集数据。"},{"word":"captured","structure":"capture + -ed (past participle)","meaning":"seized, recorded, or attracted","meaningCN":"被捕获的；被记录的；被吸引的","example":"The image was captured at sunset.","exampleCN":"这张影像是在日落时拍摄的。"},{"word":"capturing","structure":"capture + -ing (participle)","meaning":"the ongoing act of taking or recording","meaningCN":"正在捕获；正在采集（-ing 构成分词）","example":"The device is capturing readings every second.","exampleCN":"设备每秒采集一次读数。"},{"word":"capture","structure":"base noun / verb","meaning":"the act of taking, or to take","meaningCN":"捕获；捕捉（本词）","example":"The capture of the city took three days.","exampleCN":"夺取这座城市用了三天。"},{"word":"captor","structure":"capt(us) + -or (person who)","meaning":"a person who captures another","meaningCN":"捕获者；俘获者（-or 表示行为者）","example":"The captive escaped from his captor.","exampleCN":"被俘者从捕获者手中逃脱了。"},{"word":"captive","structure":"capt(us) + -ive (adjective / noun)","meaning":"kept in confinement; a person held","meaningCN":"被囚禁的；俘虏（-ive 构成形容词或名词）","example":"The captive was released after the treaty.","exampleCN":"条约签订后，俘虏获释。"},{"word":"captivity","structure":"captive + -ity (state noun)","meaning":"the state of being held prisoner","meaningCN":"囚禁；被俘状态（-ity 表示状态）","example":"The animals suffered in captivity.","exampleCN":"这些动物在囚禁中受苦。"},{"word":"captivate","structure":"capt(us) + -ivate (verb)","meaning":"to attract and hold someone's interest strongly","meaningCN":"迷住；使着迷（-ivate 构成动词）","example":"The storyteller captivated the children.","exampleCN":"讲故事的人迷住了孩子们。"},{"word":"captivation","structure":"captivate + -ion (process noun)","meaning":"the state of being fascinated","meaningCN":"着迷；被吸引的状态","example":"The audience watched in captivation.","exampleCN":"观众看得入迷。"},{"word":"recapture","structure":"re- (again) + capture","meaning":"to capture again or recover","meaningCN":"再次捕获；夺回（re- 表示“再次”）","example":"The army recaptured the hill.","exampleCN":"军队夺回了山丘。"}],"latinEntries":[{"word":"capere","structure":"Latin verb","meaning":"to take, seize, grasp","meaningCN":"拿；抓；夺取"},{"word":"captus","structure":"past participle of capere","meaning":"taken, seized","meaningCN":"被拿的；被夺取的"},{"word":"captura","structure":"captus + -ura (act noun)","meaning":"a taking, seizure","meaningCN":"拿取；捕获（-ura 表示行为）"}]}},{"word":"category","ipa_uk":"/ˈkætəɡəri/","ipa_us":"/ˈkætəɡɔːri/","definition_zh":"类别；范畴；种类","definition_en":"a group of things that share a feature, or a basic class used to organize knowledge","core_image":"一排贴着标签的抽屉，把散乱的事物分门别类","scene":"The film was entered in the documentary category.","sceneCN":"这里 category 是「评奖或比赛的类别」（第 5 个义项：竞赛分类）；句意：这部影片报名参加了纪录片类别。场景要点：电影节报名表、分类标签、参赛影片海报。","pos":[{"tag":"n.","zh":"类别；范畴；种类"}],"collocations":[{"phrase":"a category of goods","zh":"一类商品"},{"phrase":"fall into a category","zh":"归入某一类"},{"phrase":"the award category","zh":"奖项类别"},{"phrase":"a broad category","zh":"宽泛的类别"},{"phrase":"category mistake","zh":"范畴错误（哲学用语）"}],"forms":[{"label":"复数（名词）","form":"categories"}],"derivatives":[{"word":"categorize","pos":"v.","zh":"归类；分类"},{"word":"categorization","pos":"n.","zh":"分类；归类过程"},{"word":"categorical","pos":"adj.","zh":"绝对的；明确的；范畴的"},{"word":"categorically","pos":"adv.","zh":"断然地；明确地"}],"senses":[{"no":"01","title":"A class of similar things","titleCN":"类别：把相似的东西归到一起","definition":"a group of people or things that share a common feature and are treated together","definitionCN":"具有共同特征、被放在一起看待的一群人或有事物","example":"These animals fall into the category of mammals.","exampleCN":"这些动物属于哺乳动物这一类。","why":"Category comes from Greek katēgoria, a public statement or predication. To place things under one category is to say the same thing about them.","whyCN":"category 来自希腊语 katēgoria，意为公开陈述或断言。把事物放进同一类别，就是对它们说同一句话。"},{"no":"02","title":"A taxonomic category","titleCN":"分类学层级：生物分类的一级","definition":"in biology, a rank in the classification of organisms, such as genus, family, or order","definitionCN":"生物学中生物分类的一个层级，如属、科、目","example":"The species belongs to a newly defined category.","exampleCN":"这个物种属于一个新界定的分类层级。","why":"Taxonomy is a ladder of categories. Each rank groups organisms that share a level of similarity, from species up to kingdom.","whyCN":"分类学是一架类别的梯子。每个层级都把具有某一相似程度的生物归在一起，从种一直到界。"},{"no":"03","title":"A mathematical category","titleCN":"数学范畴：对象与态射的结构","definition":"in mathematics, a structure consisting of objects and the morphisms between them","definitionCN":"数学中由对象及对象之间的态射构成的结构","example":"Category theory studies structures that appear across many fields.","exampleCN":"范畴论研究出现在许多领域中的结构。","why":"Mathematics uses the word for a formal universe of objects and allowed arrows between them. It is a category in the strict structural sense.","whyCN":"数学用这个词指一个由对象和允许的箭头构成的形式宇宙。它是严格结构意义上的“范畴”。"},{"no":"04","title":"A grammatical category","titleCN":"语法范畴：时、数、格等","definition":"in linguistics, a feature such as tense, number, gender, or case that a language marks systematically","definitionCN":"语言学中被语言系统标记的特征，如时态、数、性、格","example":"Tense is a grammatical category in English.","exampleCN":"时态是英语的一个语法范畴。","why":"Grammar sorts words by the features they carry. A grammatical category is a slot in that sorting system.","whyCN":"语法按词携带的特征来分类。语法范畴就是这个分类系统里的一个槽位。"},{"no":"05","title":"A competition or award category","titleCN":"比赛类别：评奖时的分组","definition":"one of the separate groups in a competition, festival, or awards scheme","definitionCN":"比赛、电影节或评奖方案中分开的组别之一","example":"She won in the best new artist category.","exampleCN":"她获得了最佳新人奖类别。","why":"A competition must compare like with like. Each category is a box that keeps similar entries together so they can be judged against each other.","whyCN":"比赛必须让同类相比。每个 category 是一个盒子，把相似的参赛者放在一起，使他们可以互相比评。"},{"no":"06","title":"A product category","titleCN":"产品品类：货架上的大类","definition":"a group of related products sold or managed together","definitionCN":"一起销售或管理的一组相关产品","example":"The company dominates the household cleaning category.","exampleCN":"该公司主导家庭清洁品类。","why":"Retail shelves are organized by categories: products that answer the same need are placed in one box.","whyCN":"零售货架按 category 组织：满足同一需求的产品被放进同一个盒子。"},{"no":"07","title":"A philosophical category","titleCN":"哲学范畴：存在的基本谓词","definition":"in philosophy, one of the most basic kinds or predicates under which things can be understood","definitionCN":"哲学中理解事物的最基本种类或谓词之一","example":"Aristotle listed ten categories of being.","exampleCN":"亚里士多德列出了存在的十个范畴。","why":"Aristotle's Categories asked what can be said of a thing in the most general way. Those basic sayables are the original categories.","whyCN":"亚里士多德的《范畴篇》追问：对一物最一般地能说什么。那些最基本的“可说之物”就是最初的范畴。"},{"no":"08","title":"A category mistake","titleCN":"范畴错误：把不同层次混在一起","definition":"in philosophy, an error that treats something as belonging to a category it cannot belong to","definitionCN":"哲学中把某物当作属于它不可能属于的类别的错误","example":"Asking where the university is, as if it were a building, is a category mistake.","exampleCN":"问“大学在哪里”，好像大学是一栋楼，这就是范畴错误。","why":"If categories are boxes, a category mistake puts an item in the wrong box — or asks for it in a box where it cannot be found.","whyCN":"如果 categories 是盒子，范畴错误就是把东西放错盒子——或者在一个根本找不到它的盒子里找它。"}],"etymology":{"intro":{"en":"Category began as a Greek word for a public accusation or statement. Aristotle used it for the basic ways of saying what something is, and from that logical sense English derived the everyday meaning 'class'.","cn":"category 最初是希腊语中“公开指控或陈述”的词。亚里士多德用它来表示“说某物是什么”的基本方式，英语的日常“类别”义就是从这一逻辑义派生出来的。"},"items":[{"era":"GREEK katēgoria","en":"Katēgoria meant 'accusation, predication, statement'. It was formed from kata- 'against, down' and agorein 'to speak publicly', related to agora 'assembly'.","cn":"katēgoria 意为“指控、断言、陈述”。它由 kata-“反对、向下”和 agorein“公开讲话”构成，与 agora“集会”有关。"},{"era":"ARISTOTLE","en":"In the Categories, Aristotle used katēgoria for the most general kinds of predication: what can be said of a subject, such as substance, quality, quantity, relation.","cn":"在《范畴篇》中，亚里士多德用 katēgoria 表示最一般的谓述种类：关于一个主体能说什么，如实体、性质、数量、关系。"},{"era":"LATE LATIN categoria","en":"The word passed into Late Latin as categoria, keeping Aristotle's logical sense. French catégorie and English category followed.","cn":"这个词进入晚期拉丁语作 categoria，保留亚里士多德的逻辑义。随后有法语 catégorie 和英语 category。"},{"era":"1580S ENGLISH","en":"English category is first recorded in the 1580s in logic. For a long time it was a technical term in philosophy, not an everyday word for 'kind'.","cn":"英语 category 最早记录于 1580 年代，用于逻辑学。很长时间里它是哲学术语，而不是日常表示“种类”的词。"},{"era":"GENERAL SENSE","en":"Later English extended category to any class or group: types of products, awards, books, people, and organisms. The original 'what can be said' became 'what can be grouped'.","cn":"后来的英语把 category 扩展到任何类别或群体：产品、奖项、书籍、人、生物。原来的“能说什么”变成了“能被归为什么组”。"},{"era":"MODERN SPECIALISMS","en":"Biology uses taxonomic categories, mathematics uses category theory, linguistics uses grammatical categories, and philosophy keeps the original logical sense and the category mistake.","cn":"生物学用分类层级，数学用范畴论，语言学用语法范畴，哲学保留原初逻辑义和“范畴错误”。"}]},"similar":{"note":{"en":"The first group shares the categorize/categorical family; the second collects grouping words with different levels of formality and scope.","cn":"第一组共享 categorize/categorical 词族；第二组收“分类”类词，正式程度与范围不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"categorize","ipa":"/ˈkætəɡəraɪz/","tag":"verb form","definition":"to place things into categories. The -ize suffix turns the noun into an action.","definitionCN":"把事物归入类别。-ize 后缀把名词变成动作。"},{"word":"categorical","ipa":"/ˌkætəˈɡɒrɪkl/","tag":"adjective with two senses","definition":"relating to categories, or absolute and unconditional. The second sense developed from logical assertion.","definitionCN":"与类别有关的，或绝对的、无条件的。第二义从逻辑断言发展而来。"},{"word":"subcategory","ipa":"/ˈsʌbkætəɡəri/","tag":"prefix form","definition":"a smaller category inside a larger one. Sub- 'under' adds a level.","definitionCN":"大类内部的小类。sub-“在下”增加一个层级。"}]},{"heading":"NEAR MEANING","entries":[{"word":"class","ipa":"/klɑːs/","tag":"general grouping","definition":"a group of things or people with shared characteristics. It is broader and more everyday than category, which often sounds technical.","definitionCN":"具有共同特征的一组事物或人。它比 category 更宽泛、更日常；category 常带技术感。"},{"word":"type","ipa":"/taɪp/","tag":"kind or model","definition":"a kind or sort, or a model of something. Type often stresses a representative pattern rather than a formal class.","definitionCN":"种类，或某物的模型。type 常强调代表性模式，而不是正式类别。"},{"word":"classification","ipa":"/ˌklæsɪfɪˈkeɪʃn/","tag":"system or act","definition":"the act or system of putting things into classes. It is the process behind a category.","definitionCN":"把事物归入类别的行为或系统。它是类别背后的过程。"},{"word":"kind","ipa":"/kaɪnd/","tag":"everyday sort","definition":"a group of things of the same sort. It is the plainest word and has no technical edge.","definitionCN":"同一类的一组事物。它是最朴素的词，没有技术色彩。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and relatives: Greek kata- 'against/down', agorein 'speak publicly', and the family categorize/categorical.","cn":"只用真实成分与同族词：希腊语 kata-“反对/向下”、agorein“公开讲话”，以及 categorize/categorical 词族。"},"normal":[{"en":"Category began as a public statement: to put something in a category is to say what can be predicated of it.","cn":"category 最初是公开陈述：把某物放进一个类别，就是说出关于它能断言什么。"},{"en":"Aristotle's categories were the basic answers to 'what is it?' — substance, quality, quantity, relation.","cn":"亚里士多德的范畴是对“它是什么？”的基本回答——实体、性质、数量、关系。"},{"en":"Categorize is the verb: to put items into the boxes.","cn":"categorize 是动词：把条目放进盒子里。"},{"en":"Categorical can mean 'absolute', because a categorical statement asserts without conditions.","cn":"categorical 可以表示“绝对的”，因为 categorical statement 是无条件断言。"},{"en":"A category mistake puts a thing in the wrong box, or asks for it in a box where it cannot be.","cn":"category mistake 就是把东西放错盒子，或在找不到它的盒子里找它。"}],"abstract":[{"en":"A category is a box, but the box is made by a decision: which features count as the same?","cn":"类别是一个盒子，但盒子由决定造出：哪些特征才算“相同”？"},{"en":"Every classification hides a choice. The same objects can be grouped by colour, function, origin, or value.","cn":"每一种分类都藏着选择。同样的对象可以按颜色、功能、来源或价值分组。"},{"en":"Categories are tools for thought, not features of the world; the world does not come pre-sorted.","cn":"范畴是思维工具，不是世界自带的特征；世界并不是预先分好类的。"}]},"examples":[{"en":"The books are arranged by category, not by author.","cn":"这些书按类别排列，而不是按作者。"},{"en":"The prize has a separate category for short films.","cn":"该奖项为短片设有单独类别。"},{"en":"Calling a university a building is a category mistake.","cn":"把大学称作一栋建筑是范畴错误。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“卡特区”——卡特区把每件货贴上标签，放进对应的抽屉 → category 类别、范畴","word":"category"},"root":"源自希腊语 katēgoria“公开陈述、断言”，由 kata-“向下、反对”+ agorein“公开讲话”构成；亚里士多德用它指最基本的谓述种类，核心是“把事物归入可说的一类”。","sensesIntro":{"en":"Eight senses of category, all built on one act: saying what a thing is, and placing it in a box with other things that can be said the same way.","cn":"category 的八个义项都建立在同一个动作上：说出某物是什么，并把它放进一个盒子，和其他能被同样说出的东西放在一起。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of labelled boxes; each box groups things that share a sayable feature.","cn":"核心意象：一排贴着标签的盒子；每个盒子把共享某一可陈述特征的东西归在一起。"},"chain":["KATA- + AGOREIN","PUBLIC STATEMENT","WHAT CAN BE SAID OF A THING","BASIC PREDICATION","A CLASS OR GROUP","A SLOT IN A SYSTEM"],"branches":[{"senses":"S1 · S5 · S6","en":"EVERYDAY GROUPING: similar things, competition entries, and products placed together.","cn":"日常归类：相似之物、参赛作品、产品被放在一起。"},{"senses":"S2","en":"BIOLOGICAL TAXONOMY: a rank in the classification of organisms.","cn":"生物分类：生物分类体系中的一个层级。"},{"senses":"S3","en":"MATHEMATICS: a structure of objects and morphisms.","cn":"数学：对象与态射构成的结构。"},{"senses":"S4","en":"LINGUISTICS: a feature such as tense or number that grammar marks.","cn":"语言学：语法标记的特征，如时态或数。"},{"senses":"S7 · S8","en":"PHILOSOPHY: Aristotle's basic predicates, and the error of putting something in the wrong one.","cn":"哲学：亚里士多德的基本谓词，以及把事物放错范畴的错误。"}]},"affixes":{"intro":{"en":"Category is a Greek-derived noun. English builds the verb with -ize, the noun with -ization, the adjective with -ical, and the adverb with -ically.","cn":"category 是希腊来源的名词。英语用 -ize 构动词、-ization 构名词、-ical 构形容词、-ically 构副词。"},"latinIntro":{"en":"Late Latin categoria carried the Greek word into European learned language. The Greek elements kata- and agorein remain visible in the etymology but are not live English affixes.","cn":"晚期拉丁语 categoria 把这个希腊词带入欧洲学术语言。希腊成分 kata- 与 agorein 在词源中仍可见，但不是英语中能产的前缀。"},"items":[{"word":"categories","structure":"category + -ies (plural)","meaning":"more than one category","meaningCN":"多个类别；多个范畴（复数）","example":"The entries were sorted into five categories.","exampleCN":"参赛作品被分成五个类别。"},{"word":"categorize","structure":"category + -ize (verb)","meaning":"to put things into categories","meaningCN":"归类；分类（-ize 构成动词）","example":"The librarian categorized the new books.","exampleCN":"图书管理员对新书进行了分类。"},{"word":"categorization","structure":"categorize + -ation (process noun)","meaning":"the act or process of classifying","meaningCN":"分类；归类过程（-ation 表示过程）","example":"Categorization makes the data easier to search.","exampleCN":"分类使数据更容易检索。"},{"word":"categorical","structure":"category + -ical (adjective)","meaning":"relating to categories; or absolute and unconditional","meaningCN":"类别的；绝对的；无条件的（-ical 构成形容词）","example":"The committee gave a categorical refusal.","exampleCN":"委员会断然拒绝了。"},{"word":"categorically","structure":"categorical + -ly (adverb)","meaning":"absolutely; without conditions","meaningCN":"断然地；无条件地","example":"She denied the claim categorically.","exampleCN":"她断然否认了这一说法。"},{"word":"subcategory","structure":"sub- (under) + category","meaning":"a smaller category within a larger one","meaningCN":"子类别；下级分类（sub- 表示“在下”）","example":"The award has a subcategory for animation.","exampleCN":"该奖项设有动画子类别。"},{"word":"recategorize","structure":"re- (again) + categorize","meaning":"to classify again, usually in a different way","meaningCN":"重新分类（re- 表示“再次”）","example":"The archive recategorized the photographs by date.","exampleCN":"档案馆按日期重新分类了照片。"},{"word":"miscategorize","structure":"mis- (wrongly) + categorize","meaning":"to put something in the wrong category","meaningCN":"错误分类；归错类（mis- 表示“错误”）","example":"The software miscategorized the file as an image.","exampleCN":"软件把这个文件错误地归为图像。"},{"word":"uncategorized","structure":"un- (not) + categorized","meaning":"not yet placed in a category","meaningCN":"未分类的（un- 表示否定）","example":"The uncategorized items were moved to a temporary folder.","exampleCN":"未分类的项目被移到一个临时文件夹。"},{"word":"category theory","structure":"category + theory (compound noun)","meaning":"the mathematical study of structures and the mappings between them","meaningCN":"范畴论（研究结构及其映射的数学分支）","example":"Category theory is used in computer science.","exampleCN":"范畴论被用于计算机科学。"}],"latinEntries":[{"word":"categoria","structure":"Late Latin, from Greek katēgoria","meaning":"predication, category","meaningCN":"谓述；范畴"}]}}]);
